/* 平成19年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h19.committeeSessions.push(...[{"id":"h19-20070313-3","meetingId":"h19-c-budget","date":"2007年3月13日","dateIso":"2007-03-13","committee":"予算特別委員会","time":"午後５時３８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を148件整理しています。","topics":[{"id":"topic-01","title":"平成１９年度品川区一般会計予算","agenda":"平成１９年度品川区一般会計予算","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"もちろん守るべきものではあるんですけれども、もう１回、信号機の位置づけというのを考えてみなければいけないのではないかと思います。それについて、信号機の位置づけ、意味合いについて、どのように、担当の課長はお考えになっているのか、答えるよう求めました。","respondent":"松嶋交通安全担当課長","answer":"設置は困難であると、守られるのかということを投げかけられますので、まずはそこが一番かと思います。やはり狭い幅員のところでの信号機の設置というのは、現在も、狭い幅員のところはあまりつけていないのが実情です。","id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"守れる工夫をしたらいかがでしょうかというお話をさせていただいて、それからさらに、守られる信号って何だろう。守る行動がより惹起されるのではないかと思うんですけれども、そこのところを、どういうふうにお考えなのか。","respondent":"松嶋交通安全担当課長","answer":"東京都内では数字の表示ではなくて、それにしたら確実に守られるかというと、これもまた断定はできないところです。私も考えておりますので、そこら辺は、今後も申し入れはしていきたいと考えております。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問・要望","question":"ですから、もし要望として、警察のほうに申し入れをしてほしいと求めました。この緑道整備について、そのときの要望をそのまま、これからの設計上に受け入れるのかどうか。","respondent":"松代管理工事課長","answer":"それを基本的なものとして、今後の進め方ですけれども、平成１９年度、詳細な設計に入ってまいります。実際につくります沿道の方々との調整、また地元町会長を含めた地域の方の意見といったものを集約しまして、広く呼びかけをした説明会を開きます。","id":"exchange-003"},{"speaker":"大沢委員","kind":"質問・要望","question":"そのときの要望だったと思いますけれども、ぜひとも地域の要望に合った緑道をつくっていただきたいし、設計をしていただきたい。少なくなっていくことについて、よしとするのか、あまり好ましくないとするのか、どちらか、簡単でよろしいので、ご意見を伺わせてください。","respondent":"松代管理工事課長","answer":"１回事故が起きますと、それに対する対応で、どうしても引いたような状態になっていきます。これは大体３歳ぐらいまでが使う遊具、これはもうちょっと大きい子が使える、そんな表示をしながら遊んでいただけるように考えているところです。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"小さなけがによって、大きな事故を防ぐための自分の方策がわかってくるということは、非常に大事なことだと思います。ここでちょっとお伺いしたいんですけれども、どちらの位置づけのほうが強いのか、ちょっと説明を求めました。","respondent":"松代管理工事課長","answer":"やはり児童を中心にしたものというふうに考えておりますけれども、そのほかの方も使えるように、いろいろとご意見を聞きながらつくっております。そういうような配置も含めて、使い分けをし、中身を考えているところです。","id":"exchange-005"},{"speaker":"大沢委員","kind":"意見","question":"子どものための公園であってほしいと思いますし、一つの例で言えば、普通の雑草が生えているような風景も大事なのではないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"２６３ページの自転車駐車場問題について、ご質問したいと思います。自転車の放置状況がどの程度なくなったのか、その辺について、今の認識を伺います。","respondent":"松嶋交通安全担当課長","answer":"しかしながら、いろいろな方のご意見を伺いながら、また、目で見た範囲の中で、かなり放置台数は減ってきていると考えております。年に２回ほど、放置台数の調査を行いますけれども、これも年々、減ってきている状況にあります。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"平成１３年度から１７年度の数字が挙げられているんですが、どういうことなのか、改めて説明を求めたいと思います。そして、周辺の放置状況がなくなったのか、どうかについても伺います。","respondent":"松嶋交通安全担当課長","answer":"放置禁止区域外でも、そういった要望等があった場合には、積極的な撤去を実施しています。しかしながら、きれいにはなってきているのではないかなと、私自身、考えているところです。","id":"exchange-008"},{"speaker":"南委員","kind":"確認","question":"改めて確認したら、９時ちょっと前ぐらいの時間帯で、定期利用がすごくあいているんですよね。どうしてほしいのかということについて、区民の意見をきちんと聞くべきだと思っていますけれども、いかがか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"いずれにしましても、放置禁止区域外ですので、日ごろからやれなかったわけですけれども、あまりにもひどい状況の中で、撤去活動を実施したです。それに対する実態調査については、現在のところ、考えておりません。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"しかし、そういうことと、利用している方の認識の差があまりにもありすぎるって、ここが問題なんじゃないですか。どの程度、どういうふうに行われたのか、それをちょっと改めて伺いたいと思います。","respondent":"松嶋交通安全担当課長","answer":"その席上におきまして、いろいろ申し入れをしていますと同時に、個別的にも申し入れをしています。工事を着工しておりますけれども、今年度中の開放ということで、自転車駐輪場をつくっていただけるようになってあります。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"大森駅は、ＪＲの敷地に結構スペースがあると、私は思っています。したがって、ＪＲも含めてきちんとした働きかけを、さらに強めていただきたいと要請して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"武内委員","kind":"質問・要望","question":"私は、２８０ページの公園新設改良費と、２８７ページの住宅建築物耐震改修促進計画の策定の２点、お伺いしたいと思います。そのソーラス条約改正によって、何かそういうお話が聞こえているか、どうかということをお聞きしたいと思います。","respondent":"藤田道路公園課長","answer":"もともと東京湾に面した側のほうは、ほとんどがコンテナヤードでございまして、もともと一般の人の立ち入りはできない場所であったです。平成１３年からしながわ区民公園のほうで、プールのシーズンが終わった１０月から５月の連休明けまでの期間、釣り堀として開放をしています。","id":"exchange-012"},{"speaker":"武内委員","kind":"質問・要望","question":"もともと港湾の地域は立ち入り禁止というのは、これは当たり前だということなんですね。品川区でそういう適切な場所があるかどうかは、ないのか、その辺だけ教えてほしいと求めました。","respondent":"藤田道路公園課長","answer":"ただ、そのときにもう少し海辺に近いほうでということで、しながわ区民公園で実施してきた経緯があります。ご意見を聞きながら、それぞれの公園のあり方については、十分に検討をしていきたいと考えております。","id":"exchange-013"},{"speaker":"武内委員","kind":"質問・要望","question":"釣り堀というよりも、自然の釣りができるような場所がもしあれば、今後、ぜひ検討していただきたいと要望だけします。１,４００万円ほど計上されていますけれども、おそらく、その辺の内訳を教えてほしいと求めました。","respondent":"片田建築課長","answer":"昨年の促進法の改正施行に伴いまして、区としても計画を策定していくという考え方で、１,４００万円ほど計上させていただきました。１,４００万円のうち、計画策定が４５０万円ほど、分析等を含めた内容で考えております。","id":"exchange-014"},{"speaker":"武内委員","kind":"質問","question":"品川区は、これから正確なところはこれからだと思うんですけれども、大体、この程度なんですか。それとももっとぐっと低いのか、その辺の見込みというか、予測はどうなんか尋ねました。","respondent":"片田建築課長","answer":"その中で、区のほうとしても、都の計画そのものが国の考え方を踏まえたものですので、当然、それを下回るということは考えておりません。基本的には、区のほうとしても９０％以上、重要なものについては１００％を目標とするといったような見当になろうかなと考えています。","id":"exchange-015"},{"speaker":"武内委員","kind":"質問","question":"昨年の予算特別委員会でもお聞きしたんですけれども、評価基準というんですか、１.０以上というものがあるわけですよね。耐震化の中で、１.０以上にならないと、耐震化されたというパーセンテージに含まれないのか、どうか、この辺を説明を求めました。","respondent":"片田建築課長","answer":"耐震化の評価についての考え方ですけれども、国のほうも含めてですけれども、上部構造の評点基準というものを１.０以上ということで考えております。","id":"exchange-016"},{"speaker":"武内委員","kind":"質問・要望","question":"この簡易補強は、先ほどの１.０に満たないわけです。この辺のところを、区としてはどう考えているかということについて、教えてほしいと求めました。","respondent":"片田建築課長","answer":"今回もまた、３月の末ぐらいかと思いますけれども、東京都のほうで公表していきたいといったような話を聞いております。区のほうとしても十分に生かしまして、ＰＲ等も含めて、普及に努めてまいりたいと考えております。","id":"exchange-017"},{"speaker":"武内委員","kind":"質問・要望","question":"前回も質問しましたけれども、たしか０.７まで基準を落として、区独自で安価な簡易改修についても補助しているという経緯があるわけです。その辺についても、この計画との整合性なんかについても、教えてほしいと求めました。","respondent":"片田建築課長","answer":"ほかの区等についても、１.０未満のものでも支援していきたいといったような考え方を持って、進めている区もあるということで聞いております。","id":"exchange-018"},{"speaker":"本間委員","kind":"質問","question":"それから、２８１ページ、しながわ区民公園再整備計画検討とありますが、今後の取り組みの内容について、お伺いします。そしてさらに、その利用状況の中身で、定期利用という部分と、一時利用という形がありますが、その割合についてお尋ねします。","respondent":"松嶋交通安全担当課長","answer":"続きまして、西口第２ですけれども、これは池上通りの下になりますけれども、定期の自転車７７％、バイクが１００％。当日利用につきましては、自転車のみですけれども、９９％となっております。","id":"exchange-019"},{"speaker":"本間委員","kind":"質問","question":"一時利用の部分が、場所によっては１００％を超える状況があるという話です。先ほど、台数は出ておりましたけれども、やはり定期と一時利用の内訳を、ちょっと教えていただけますか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"三つ目は、現在のネコ公園の隣の区道、西口第１駐輪場の前の区道の部分です。バイク３４台ということで考えているところですけれども、とりあえず予定としては、こういった台数になっております。","id":"exchange-020"},{"speaker":"本間委員","kind":"質問","question":"最近の実情に素早く対応した中身というふうに受けとめておきます。入口が大変出入りがしにくいといいますか、その地域での実情と、苦情等を聞いておりませんか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"郵便局の前ということでは、具体的に苦情は聞いておりませんけれども、付近のところでの苦情は聞いているところです。","id":"exchange-021"},{"speaker":"本間委員","kind":"質問","question":"そこを実際に利用している人かどうか、そのような状況になっているということが、私どもの耳に届いています。駐輪場の取り込みについてのかかわりについて、どのように接触されたのか、説明を求めました。","respondent":"齋藤住宅課長","answer":"建築確認、あるいはそういった関係は東京都のほうに出されておりまして、総合設計制度という制度を使ってやります。区と協議をいたしまして、駐車場につきましても適正、駐輪場につきましても適正に配置されるように指導をしてまいります。","id":"exchange-022"},{"speaker":"本間委員","kind":"質問","question":"これまでの、平成１７年、１８年に、それぞれ八潮地区の区道で遮熱性舗装を実際に検証してみた。平成１８年度にはゆたか商店会で、保水性舗装の整備について検証してみたですが、その効果について、それぞれ簡単で結構ですが、説明を求めました。","respondent":"松代管理工事課長","answer":"それを受けまして、平成１８年度、ゆたか商店会の皆さんとお話をしまして、協力が得られるということから、そちらのほうに保水性舗装をやりました。家で使われる風呂水とか、それにより１５度ほど下がってございまして、平均でも１０度ほど下がったという効果が出ている状況です。","id":"exchange-023"},{"speaker":"本間委員","kind":"質問","question":"そのような中で、関連しますが、雨水利用タンク設置促進事業。今回出ている助成の内容についても、簡単で結構ですが、説明を求めました。","respondent":"原田下水道河川課長","answer":"この事業そのものが平成１８年度から実施したものでありまして、区報を利用したり、そこの商店街の方にお伝えしたりといったことを行っております。","id":"exchange-024"},{"speaker":"本間委員","kind":"質問","question":"助成の中身は、これは２０件ですから、割り出しをするとどのぐらいの助成か、数万円程度だと思いますけれども、わかりました。その件について、もしご承知でしたら、お願いします。","respondent":"藤田道路公園課長","answer":"その場合、区内に非常用の井戸がございまして、そこから水をくんで散水をしております。水のほうについては、井戸からくんでおりますので、特に費用はかかっておりません。","id":"exchange-025"},{"speaker":"本間委員","kind":"質問","question":"山のような部分がありますが、その水の流れの部分、導水の部分をどうしているのかなというのが一つ。プールと釣り堀を交互に使っておりますが、この辺の利用状況を、簡単に説明を求めました。","respondent":"藤田道路公園課長","answer":"あるいは、点検のときは流れていないというようなことも、当然あろうかと思います。プールと釣り堀のほうですけれども、たくさんの方にご利用いただいております。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"２７１ページ、それから２８８ページの区営住宅、２８７ページの建築紛争調整についてお聞きします。それから特にお聞きしたいのは、指定管理者にどういうお金がいくのかということについて、お聞きしたいと思います。","respondent":"松嶋交通安全担当課長","answer":"指定管理者の契約状況ですけれども、現在、最終的な協定をやっているところです。４月１日から全部がぽんとなるのではなくて、運営費、そこら辺でご理解をいただきたいと思います。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"できれば、利用料金で維持できれば一番いいわけですよね、コストがかからないわけですから。そういう形でやっていけるものなのか、いかがか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"期間的なものは５年間です。それから、利用料金制につきましては、自転車駐輪場は取らないことでやっていくということです。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"ですから、利用者は１００円とか、かかりますよね。その料金というのは、ではどういう形で入ってくるんですか、ここに。","respondent":"松嶋交通安全担当課長","answer":"利用料金につきましては、今までと一緒で、区のほうに入ってきます。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"ですから、毎年、維持費という形で、区のほうから支出ということが要らない場合もあるんです。そういうところを含めて選定をしているのかどうかを、お聞きしたいと思います。","respondent":"松嶋交通安全担当課長","answer":"いろいろ協定を結んでいるわけなんですけれども、これまでの５年間の比率と割合を比べたときには、おおむね２０％ぐらいの削減になる予定です。そういった場所があるという委員のご指摘ですけれども、そこら辺も含めて、今後の協定に生かしていきたいと思っています。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"今、自転車の管理については、いろいろ業者がいるようですので、この辺、研究をしていただきたいと思っています。次に、避難道路の件ですけれども、この内容を少しお知らせほしいと求めました。","respondent":"伊勢住環境整備担当課長","answer":"機能強化の検討といたしましては、戸越公園一体のほうに避難していくというようなことの検討、そちらにも二つに分れて避難するというような検討です。沿道建築物の配置だとか、あるいは権利調査、それから地元の説明会というものを予定している内容です。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"やっているのは去年からでしょうか、そのときに、地域の方たちには、どういうような情報を出していたのかなと思うんです。自分の生活自体も変えなきゃいけないという事態もありますので、地域の方たちの関係は、どのようになっているんか尋ねました。","respondent":"松代管理工事課長","answer":"平成１８年度に、避難道路の検討をしてまいりました。ご説明をしながら、避難道路の位置づけをぜひご理解いただき、それを具体的な形に結びつけていくといった形で進めているものです。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"ですから、こういうふうに地域をつくっていきましょうというのが先であるべきなのかなと、私は思います。いろいろ事情はわかっておりますが、今後の調整も含めて、お考えを聞きたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"今後、地域に入っていきますけれども、事前に調査はしましたけれども、十分にこの辺の検討内容を皆さんにお知らせして、ご意見を聞きながら進めていきたいと思っています。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"担当は違うと思いますが、スクールゾーンの子どもたちの安全も含めて、歩道の改良をお願いしたいと思っています。次に、区営住宅についてですが、障害者に対する区営住宅の枠というのは、どういうふうな形になっているのか、お聞きしたいと思います。","respondent":"齋藤住宅課長","answer":"西大井六丁目第三区営住宅に３戸ほどあります。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"今、何棟でしょうか、数が少ないというふうに聞いております。それはどういう経緯だったのか、まず、お知らせほしいと求めました。","respondent":"齋藤住宅課長","answer":"そこを、たまたま障害者がお住まいだったので、重度の、ほとんど全盲の方が入れるものだと思ってご案内をしました。障害者用住宅ではなく、あなたが入れる住宅ではございませんので、入居はできませんというご案内をしたところです。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"障害者用住宅と、それから一般用という形は、施設的にやはり大きな違いがあるんでしょうか。そこはいかがか尋ねました。","respondent":"齋藤住宅課長","answer":"ただ、その方といろいろトラブルになりました。きちんとご説明をして、障害者の住宅ではありませんからご理解くださいと、よろしくお願いいたします。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"ここで、まずちょっと今後改善をお願いしたいなと思っているところは、実際、障害者が入れる区営住宅の枠というのは、どのぐらいになっているのか。それはいかがか尋ねました。","respondent":"齋藤住宅課長","answer":"公営住宅法の中で、障害者枠、高齢者枠をどの程度取るか、これは決まりがございません。区では、先ほど間違えましたが、単身で２、家族用で２、合計４の障害者向けの区営住宅がある、このようになっております。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"区営住宅は、たしか４３９戸ですよね、そのぐらいだったと思うんですが、その中で、四つの枠というのは、品川区として十分なのか、それとも、今後、改善を必要とするというお考えがあるのか、ということについて、いかがか尋ねました。","respondent":"齋藤住宅課長","answer":"歳入のところで若干ご説明をいたしましたが、大変なかなかつくりがたい、建設しがたい。区も考えて、障害者のために住宅を供給してまいりたいと、このように考えております。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"いろいろ相談できるということは、可能な部分があるんじゃないかと思うんですが、必ずその四つの枠の中でしかできないものなのか。考慮が多少できるんではないかと思いますが、その辺の融通性というのはいかがか尋ねました。","respondent":"齋藤住宅課長","answer":"障害者の方でも、一般の枠に応募されて入っている方はいらっしゃいます。宅建の職員が取り違えまして、それでそういったトラブルになっただけでありまして、従前も柔軟に対応しております。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"同じことを繰り返さないようにお願いしたいとは思いますけれども、きちんとその状況を踏まえながら、今後運営してほしいと求めました。これで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"井上委員","kind":"確認","question":"２６６ページ、２６２ページの土木総務費、伺います。この建築確認がおりたという情報があり、その建築確認について、現況を説明を求めました。","respondent":"齋藤住宅課長","answer":"誤記の原因と対応ですが、どうも設計事務所の方がやめられて、うまくそれを建築概要書に反映しなかった。区役所で説明をし、大阪から設計事務所の職員を呼んで説明をさせ、なにとぞご理解のほどをお願いいたします。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"地域の中で、品川区がつくった要綱を遵守するための努力は、さらにしていただきたいというふうに要望しておきます。そしてその整備は、今後、どのようなスケジュールで行われるのかということを、固まっていれば説明を求めました。","respondent":"浜脇街路事業担当課長","answer":"それから、予定ですが、駅前広場につきましては、平成１９年度に電線の共同化の工事が始まる。そして、平成２０年度に、上のほうの植栽とか、舗装とか、そういったことを始めて、平成２０年度中の完成を目指すというふうになってあります。","id":"exchange-042"},{"speaker":"井上委員","kind":"意見","question":"西小山の桜並木の整備のところは、平成２０年度完成ということでいいのかということをもう一つ。そこの工事のスケジュールは、いつごろ、どうなるのかということを説明を求めました。","respondent":"浜脇街路事業担当課長","answer":"１年間の中で、この立会道路２００ｍということの予算を使いまして、やらせていただきます。それらを保存しながら、あるいは、一部移植しながら進めてまいるとなっています。","id":"exchange-043"},{"speaker":"井上委員","kind":"質問・要望","question":"的な意見を求めるために、区民の声を聞いて政策を決定をしていくという、そういった大前提が保障されないと思っています。住民の側への資料提供という意味で、お考えをお聞かせほしいと求めましたが、いかがか尋ねました。","respondent":"浜脇街路事業担当課長","answer":"それにつきましては、今後の西小山の駅前広場の中で検討してまいるということを、これまでお答えしてまいりました。住民説明会での皆様方のいろいろな声をまとめたものをお伝えして、今回、このような計画を実行してまいるです。","id":"exchange-044"},{"speaker":"井上委員","kind":"質問・要望","question":"私が、今お伺いしたのは、一般的に情報を提供するとき、両者の立場に立った情報提供に対して、どうなんですかということをお伺いしたかったんで、その説明会に至る経過とか、そういうことを聞いているんじゃないので、質問に適切にお答えほしいと求めました。","respondent":"福田まちづくり事業部長","answer":"しかしながら、それだけではなくて、やはり、声に出さない方が大勢いるということも、我々はよく覚えておかなければならないことだろうと思います。そこにお住まいの方たちを対象とする住民説明会におきましては、できるだけ適切な資料を提供する、これが私どもの手法です。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問・要望","question":"議事録などを提示してほしいということで、担当者に伺いましたら、そういった議事録はないという。これはもう既に担当部長に改善をするように求めてありますから、こういった、こういったものになりますという説明では不十分だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"井上委員","kind":"質問","question":"後先になりましたけれども、資料が２点あります。使わせていただいて、よろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"井上委員","kind":"質問","question":"それで、こういったところで、樹木を、３１本のうち１２本、ここで切りますということになります。これを住民説明会に出すべきだということで、これは出しませんというお話でしたけれども、その理由をお伺いしたいと思います。","respondent":"浜脇街路事業担当課長、岩田まちづくり事業部次長","answer":"補助３０号線の桜並木につきましては、あるいは保存できるところということで、丁寧にご説明申し上げております。ですから、私どもは、図面を全員に配らなくても、大きな画面でパワーポイントでやっておりますので… この立会道路の桜並木については、基本的に伐採はありません。ただ、桜はかなり老木ですので、活着率は若干悪いですけれども、可能な限り生き残すような方向で、今、検討させております。","id":"exchange-048"},{"speaker":"井上委員","kind":"質問・要望","question":"こういったものを１枚ずつ配ってくださいということではなく、会場に張り出してもいいわけですから、やっぱり目で見えるように。簡単には育たないものですから、住民説明会に対して、それをどういうふうにコーディネートしていくかというのが行政の役割だと思います。","respondent":"浜脇街路事業担当課長、松代管理工事課長","answer":"私どもが住民説明会において、私どもが行っている説明会としては、最大のことをやったつもりでおります。でも、そういうご意見がありますから、丁寧にやることにつきましては、今後とも心がけてまいります。 幅員が８ｍぐらいのところに、昭和４０年代、歩行者の安全ということで歩道をつくってまいりましたけれども、狭かった。歩道の平坦化等の整備を、今、進めているところです。","id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"歩道の広いところでは、車道側の斜面に切ってあったりするのでいいんですけれども、狭いところで、ご自宅の駐車場に入るところとかで斜めになっている部分というのは、そういったところは、区としてはどういう対応がとられるんか尋ねました。","respondent":"松代管理工事課長","answer":"車道側からの構造で言いますと、車道と歩道の段差が１５cmありますが、それを１０cmぐらいにすることによって、少しでも勾配をゆるやかにする。","id":"exchange-050"},{"speaker":"井上委員","kind":"質問・要望","question":"公道ですので、歩行者優先で、車が入れる段差を短くするとかということではないと思うんです。ですから、区民のニーズに沿った改善をしていただくということで、時間がないので、要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"本多委員","kind":"質問","question":"４点目の、開校にあわせて歩道改良ができないかという質問をしようと思ったんですが、開校にあわせてこういうのって整備できないのか。できるか、できないか、その辺のことを説明を求めました。","respondent":"浜脇街路事業担当課長、松代管理工事課長、藤田道路公園課長","answer":"補助１６３号線の件のほうからお答え申し上げます。庁舎のほうにも補助１６３号線の線型が入っている部分がありますので、平成１９年度に調査… その外構工事とあわせて、道路整備も、私どもでやるということから、若干４月を越えてしまうということがあります。今後も、そういったご指摘の点… そうした中で、安全安心という観点が、最近ではよく話題になります。効果的で、効率的な予算執行が図れるようにということで、位置づけたものです。踏切対策です。","id":"exchange-052"},{"speaker":"本多委員","kind":"質問・要望","question":"協力はするんだけれども、長期的な計画が組めないので、何か教えてほしいと。その辺の調整といいますか、報告もしてほしいなと思って、それを説明を求めました。","respondent":"松代管理工事課長、阿部都市計画課長、浜脇街路事業担当課長","answer":"踏切内は、ＪＲ等々との鉄道事業所との調整で、グリーンを色合いとして使ってあります。これは通る方に、少しでも視認性をよくするというところから… 開かずの踏切の対策ですけれども、実は、ＪＲの住吉踏切で、賢い踏切を導入いたしまして、実験いたしまして、短縮したという例があります。これまで平成９年度ごろから、やっかいだろうということで、東急の架道橋のところを研究するわけです。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"提案","question":"西小山４号踏切を、また住宅近接の急カーブで、実態として不可能ですから撤回をしてくださいと。この辺の認識と、その根拠について、お伺いをしますとの意見を述べました。","respondent":"岩田まちづくり事業部次長","answer":"この案を地域にお示ししたときから、何らかの代替の方策を検討すべきだろうということを、地域の方から声をいただいております。東西が分断されることの補完施設として、品川区側から目黒区側への車の通行もできるように、きちっと対応策をご提案したものです。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なので、危険性からして、安全対策がまだまだとられていないままに、このままこの計画を押し通すのか、どうか、その点を１点、伺いたい。説明も不十分だし、安全対策も不十分、私は、このまま押し切ってはならないと思っていますが、いかがか尋ねました。","respondent":"浜脇街路事業担当課長","answer":"説明会を７回、それから、反対派の方との話し合いも二十数回にわたってやってまいりました。平成１９年２月以降は、東急の監督たちを回らせまして、工事の内容について説明を行ってきたものです。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"不安のままに日々過ごされているということを受けとめて、もっと意見をちゃんと聞いて、最善の対策をこれからも求めます。この点について、ご答弁をお願いします。","respondent":"浜脇街路事業担当課長","answer":"再度にわたるご説明についてですけれども、広範の方々に、今の計画案については好意を持って迎えられていると考えています。説明がないと言いますけれども、近隣には説明をしておりますので、今後ともあわせてやっていくと考えております。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"武蔵小山駅周辺の地域整備、この方針について、お伺いをします。どういう流れの中でこの方針をやることになったのか、教えてほしいと求めました。","respondent":"伊勢住環境整備担当課長","answer":"武蔵小山中心街の将来を考える会が結成されまして、商店街の活性化に向けた検討がされており、まちづくりに向けた動きをされております。それから、地元協議等との調整を予定しています。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"提案","question":"今後の進みぐあい、スケジュールを教えていただきたい。それから、広範な地域の住民アンケートをしてほしいのと、地区計画提案に当たっては、地域に対して十分な説明会と、意見交換をお願いしますとの意見を述べました。","respondent":"伊勢住環境整備担当課長","answer":"スケジュールですけれども、まず、４月に入りましたら、契約手続がありまして、委託先が決まってまいります。それから、アンケート等はやります。","id":"exchange-058"},{"speaker":"若林委員","kind":"質問・要望","question":"私は２８２ページの都市開発費につきまして、質問します。このような逆の意味でも、お知らせほしいと求めました。","respondent":"青木都市開発課長","answer":"大崎全体としましては、基本方針に基づいて整備していっているです。そうしますと、今後もやはり、場所に応じた再開発手法などは積極的に展開していく必要があると考えております。","id":"exchange-059"},{"speaker":"若林委員","kind":"質問","question":"もう１点、今まで、どのようにされてきたかというのをお聞きしたいと思います。そして、理解をしていただかなければならないと考えていますので、この点につきまして、ご答弁をお願いいたします。","respondent":"青木都市開発課長","answer":"事業者からの説明会でありますとか、その対策についても、各事業者にお願いしています。区としましても、その手続、説明会等の中でご説明をしているところで、ご理解を願っているところです。","id":"exchange-060"},{"speaker":"若林委員","kind":"質問・要望","question":"一つお願いというんでしょうか、要望として、１ページ使ってやられております。確かにプラスとマイナスはあるけれども、このようなご努力もほしいと求めましたけれども、いかがでございましょうか。","respondent":"青木都市開発課長","answer":"お金のかかる事業だということは、まさに金額的にも大きいものですから、そういった点でのご説明は、確かに不足している部分があると思います。そういった広報の活動を進めていく必要があると思いますので、委員のご指摘のとおり、今後の対応を考えていきたいと考えます。","id":"exchange-061"},{"speaker":"若林委員","kind":"質問・要望","question":"そして、平成１７年でしたでしょうか、大崎駅周辺の都市再生ビジョンを発表されております。そこら辺も含めまして、今後の品川区の再開発に対する、まちづくりに対する区民へのメッセージというものをお知らせいただきたいと考えています。","respondent":"濱野区長","answer":"こういう変化に対応したまちづくり、あるいは老朽に対応したまちづくりというのは、どの地域であれ必要になってくるものだと考えています。","id":"exchange-062"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"それから、２点目が、２６９ページの都市計画道路の補助１６３号線、一本橋地区のことを、ちょっとお伺いします。それから、３点目は、伊藤学園の歩道状空地の樹木について、お伺いをさせてほしいと求めました。","respondent":"松嶋交通安全担当課長、浜脇街路事業担当課長、宍戸施設担当課長","answer":"自転車だけを特化して考えたときには、いろいろな交通安全活動について、自転車は取り入れてあります。ここに１,６００万円と入っておりますけれども… 約９億円乗せてもらえば、残りの約１０％、全部乗せております。 できる限り既存樹木は残したいということで、この間、外構工事を進めてまいりました。それとのバランスで、やむなく若干、剪定をさせていただいたものです。","id":"exchange-063"},{"speaker":"原（雅）委員","kind":"質問","question":"ですから、もうちょっとその辺のところを、配慮のある施策を考えてほしいと思うんですが、いかがでございましょうか。これであとの１０％を何とか用地取得をしたいと、平成１９年度の工事の予定について、ちょっと聞かせてください。","respondent":"松嶋交通安全担当課長、浜脇街路事業担当課長","answer":"そういった中で、いろいろな検討項目を実際に出してきております。この総合プランにうまく乗っていって、効果的な活動ができるように、実施していきたいと考えています。 １６３号線の関係ですけれども、平成１９年度からは、あるいは埋設管の移設といったものを始めてまいりたいと考えております。","id":"exchange-064"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"おそらくそれは教えていて、ぜひその辺を加味して、自転車の安全対策には力を注いでほしいと求めました。その時期にもよるんでしょうけれども、その辺、どういうふうにお考えなのか。","respondent":"浜脇街路事業担当課長","answer":"今後どういうふうに進めていくかといったことも提供しながら、その辺もお話し合いといいますか、進めてまいりたいと考えております。","id":"exchange-065"},{"speaker":"原（雅）委員","kind":"意見","question":"装飾灯の移設についても、説明会みたいなものはお持ちになるのか、どうか。ちょっとその辺だけ聞かせてくださいとの意見を述べました。","respondent":"浜脇街路事業担当課長","answer":"説明会といいますと、どこまでというのがありますけれども、私ども、今のところ、一番お話し合い相手になっていただいているのは商店街の方々です。２０５号線に近いところなんですけれども、商店街としての対応については、お話をしたいなと考えています。","id":"exchange-066"},{"speaker":"原（雅）委員","kind":"質問","question":"それからもう一つ、西地区の再開発とかかっていますよね。一本橋の商店街の補助１６３号線の拡幅につながる部分がたくさん出てくると思うんですけれども、その辺の考え方を、ちょっと説明を求めました。","respondent":"浜脇街路事業担当課長","answer":"先に道路整備をやるということになると思いますけれども、その辺は、今後とも再開発のほうと調整をしながら進めてまいりたいと考えております。","id":"exchange-067"},{"speaker":"阿部委員","kind":"質問","question":"２８３ページ、２８５ページにあります滝王子通りの避難道路の機能強化の検討について、お伺いしたいと思います。そしてまた、車の流入を防ぐような何か対応というのは考えていらっしゃいますでしょうか、説明を求めました。","respondent":"青木都市開発課長","answer":"そこに交通負荷が乗るだろうということで想定しておりまして、その段階では、８,４００台ほどの上下通行が双方通行で来るだろう見込んでおります。看板を設置して、そういった形での、流入をなるべく抑止するような対策をとっていきたいと考えております。","id":"exchange-068"},{"speaker":"阿部委員","kind":"質問","question":"供用のぐあいを見て考えていくことになるんでしょうか、ある程度、構造的にも入りにくいようなことも含めて検討してほしいと求めました。どんな状態になっているか、あるいは、どういった対応を考えていらっしゃるのかということをお伺いしたいと思います。","respondent":"青木都市開発課長","answer":"改札口等の改修が必要だろうということで、ＪＲは認識しているようですけれども、交通処理は問題なしと考えております。北品川で開発が完了しますのが平成２４年ごろを予定しておりますので、それは今後、鉄道事業者と協議をしてまいります。","id":"exchange-069"},{"speaker":"阿部委員","kind":"質問","question":"具体的にどうしようというところまで、これから区がやっていくわけですから、ある程度成果がつかみやすい課題だと思うんです。一石二鳥というんですか、一挙両得というんですか、理事者のお考えを伺えればと思います。","respondent":"青木都市開発課長、原田下水道河川課長","answer":"戦略５という５番目の戦略として、これから、まちの運営のほうにだんだん軸足を移して進めていきたいと考えています。そういった自治会活動などとも連携していこうということで、今後… 来年度、しっかり浄化対策をいろいろ検討していきたいと考えています。それに対して、どんなことをやればきれいなるのかということをしっかり説明しながら、対策を考えて決めていきたいと思います。","id":"exchange-070"},{"speaker":"阿部委員","kind":"意見","question":"その辺は、理事者の方々のお考えとしては、何かありますか。あるいは、そういう方向で、今後検討していくというようなことはありますかとの意見を述べました。","respondent":"青木都市開発課長","answer":"これを、ご指摘のとおり、大崎というまち全体で共同して、連携できるような組織体制をつくっていきたいと考えております。区としてお手伝いしていきたいということを、今、考えているところです。","id":"exchange-071"},{"speaker":"阿部委員","kind":"質問","question":"２８５ページの滝王子通りの拡幅についても、お伺いしたいと思います。ちょっとお話を伺ったんですけれども、現在の滝王子通りが、特に子どもやお年寄りにとって危ない状況になっていると。","respondent":"松代管理工事課長","answer":"計算でいきますと、２２ｍぐらい幅員を広げないといけないんですが、そうはできません。それを地域にお示ししながら、地域の皆様の理解と協力を得るような形で進めていきたい、このように考えているところです。","id":"exchange-072"},{"speaker":"須貝委員","kind":"質問","question":"人が住むんですから、延焼遮断帯が増えるわけでもなく、これでは密集住宅市街地整備促進事業は進まないんじゃないか。延焼遮断帯になる耐火建築物の建築促進にこそ、区としては向かうべきだと思いますが、ご見解を説明を求めました。","respondent":"片田建築課長、伊勢住環境整備担当課長","answer":"私のほうから密集事業の関係と、耐震診断、あるいは補強工事の関係について、ご説明します。区としては支援するという考え方はございませんし、公益性の観点から重点的に支援しているですので、ご理解いただければと思います。 密集事業は、国の補助金を使いまして、道路の拡幅、公園の整備、あるいは不燃化というものを３本柱としてやっています。あるいは６ｍ道路の防災生活道路を拡幅する、必ずしも、相反するというものではないと考えております。","id":"exchange-073"},{"speaker":"須貝委員","kind":"質問","question":"そういうものを区が仲介役になってもいいですから、その先の１１ｍから先はできません、いつまでたっても進まないんじゃないかと思うんです。その辺、ちょっと将来の展望として、どのようにお考えか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"今年度につきましては、共同化や共同化以外のことについて、いろいろアンケートをやりました。いろいろなケースで、皆さんのご要望におこたえして、その地域の防災性を高めていきたいと考えております。","id":"exchange-074"},{"speaker":"須貝委員","kind":"質問・要望","question":"いっときも早くこういう事業を進めなきゃいけないというふうな区の方針だと思うんですが、それに対して、いかに早くできるか。区独自ではなくて、民間会社も活用して、いっときでも早く密集市街地改修をして、災害に強いまちづくりを目指してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先日もちょっと、ある事業者から書類を見せていただいた中で、区からの要望事項の中に、ＣＡＴＶが視聴できるようにという要望が出ております。ですから、また、商店街はこんなことをやっているんだということが全然出てこないと思うんですよ。","respondent":"齋藤住宅課長、片田建築課長、堀越行財政改革担当課長","answer":"したがいまして、１年間に、その住宅で退去された方が出たら、優先順位に従って入居していただく。例年、１２から１４ぐらいの方が入れるという仕組みにな… これを強制して、事前にマンション計画の中に入れ込ませるということは、なかなか難しいところがあります。引き続き、これについても… かなり強力に営業を展開していると聞いておりますので、今後とも、そういう方向で進めていくものと考えております。","id":"exchange-076"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これは、お答えとしてはもう両方とも検討がつきますので、申しわけない、お答えはもらわないで、次の質問をさせてもらいます。お聞きしたかったのが大井町駅西口自転車駐車場増設、金額全体としては５,０００万円かかりますけれども、設備費というのはかかるんか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"これは当日利用ですので、機器を設置してチェーンで引っかけるような状況、それでお金を入れるとそれが抜けるような設備をつけるものです。","id":"exchange-077"},{"speaker":"鈴木（真）委員","kind":"質問","question":"３４台の一時利用のバイク駐車場というお話があったんですけれども、一時利用の費用的なものというのは、どのぐらいの金額を考えていらっしゃるのか。今既にオートバイの一時利用があると思うんですけれども、この部分の単価が、今お幾らになっているのか説明を求めました。","respondent":"松嶋交通安全担当課長","answer":"今度、つくるところですけれども、実はこれはより効率的な運営方式ということで、民間の導入もちょっと検討しています。したがいまして、これは２５０円にするかは、これから検討をしていきたいと考えているところです。","id":"exchange-078"},{"speaker":"鈴木（真）委員","kind":"質問","question":"２５０円ということで、安価な金額になると思います。それともそれは望まないで、区はあくまでも場所をつくっていきますという考えなのか、どちらか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"区としましては、本来であれば、民間につくっていただくのが基本であると考えているところです。そういった中で、二輪の駐車場はありませんので、コインパーキングであれ、民営の既存の駐車場であれ、バイクの取り入れを強く望んでいるところです。","id":"exchange-079"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"結局、オートバイ置き場はないんだから、結局やっぱりまた区がやらなきゃいけないという話になってくるんじゃないかなと思うんです。高くしろということじゃないですよ、民間参入できる範囲の、その辺の整合性もとって検討していっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"山路委員","kind":"質問","question":"３点目が２７９ページ、４点目が２８１ページ、お伺いをいたします。何人かの方から、危険なところがあったということをお伺いしたんですが、この辺について、どのように状況を把握されていますか、お伺いいたします。","respondent":"松代管理工事課長","answer":"この道路の、今の中央分離帯の件ですけれども、道路築造に当たりまして、いろいろと変遷がございました。横断ができないような、横断抑止となるような形というような要望がきて、設置したように記憶しております。","id":"exchange-081"},{"speaker":"山路委員","kind":"質問・要望","question":"もう１点は、海岸通り東品川三丁目のサンゲツ前と、その周辺ですが、交差点の横断歩道が一つしかないんです。横断歩道を二つつけていただけないかですが、この辺はどういうふうに認識されていますか、お伺いいたします。","respondent":"松嶋交通安全担当課長","answer":"委員、ご指摘の部分は、多分、交差点でコの字型に横断歩道がついている部分だと思います。うちのほうは所轄警察署並びに本部の交通規制課を呼びまして、現場を確認の上、つけられるものだったらつけるように努力をしてまいりたいと思います。","id":"exchange-082"},{"speaker":"山路委員","kind":"質問・要望","question":"至急、即やっていただきたいという要望が強く出ておりますので、よろしくお願いいたします。３点目は、都市景観形成事業について、南品川三丁目と旧東海道ということですが、景観計画について、内容をお知らせほしいと求めました。","respondent":"阿部都市計画課長","answer":"平成１８年１月に、旧東海道周辺地区をモデル地区に指定しまして、景観形成について検討してまいりました。平成１９年度につきましては、それを素案というか、そういうものを考えていきたいと考えています。","id":"exchange-083"},{"speaker":"山路委員","kind":"意見","question":"ちょうど旧東海道の青物横丁と鮫洲間に、お寺の隣に、計画を立てて工事をストップしたビルがありますね。そこと高さ制限とどのように整合性があるのか、地元の方が非常に心配しているんですが、ご説明できたら、お願いいたしますとの意見を述べました。","respondent":"阿部都市計画課長","answer":"そこにつきましては、今、南品川三丁目地区の方々が、沿道について地区計画を考えております。地区計画を考えておりまして、これを支援をしていくということで、その支援のための予算を措置しているです。","id":"exchange-084"},{"speaker":"山路委員","kind":"質問・要望","question":"地域の皆さんは、このビルはこのままストップしていくのか、あるいは、どうなるのかと。高さ制限を早く決めていただきたいと、早い時期に解決できるようにお願いしたいと思いますが、どういうふうに展開してまいりますか尋ねました。","respondent":"齋藤住宅課長","answer":"ただいま建築がとまっておりますが、既に建築確認がおりて着工している物件です。条例が定まったといたしましても、新しい地区計画が遡及してマンションに適用されるものではございませんので、ご理解のほどをお願いいたします。","id":"exchange-085"},{"speaker":"山路委員","kind":"質問","question":"公園整備について、東品川海上公園と二日市公園改修、横丁公園改修について、お伺いをいたします。オープンするに当たりまして、いろいろなイベントの企画等もあると思うんですが、その辺についての説明をお願いいたします。","respondent":"松代管理工事課長","answer":"３月３１日、土曜日、１０時から式典等を行いたいと考えています。地元の商店街等々を入れまして、６団体の協力を得て、開園式等を進めていきたいと考えているところです。","id":"exchange-086"},{"speaker":"山路委員","kind":"提案","question":"平成８年の第１回定例会におきまして、品川区で香りのある公園づくりということで、ハーブ公園のご提案をさせていただいたんです。御殿山の桜のような、いろいろ季節感のあるものにしていきたいということでしたが、ここも全面開園するんか尋ねました。","respondent":"松代管理工事課長","answer":"屋上庭園には、以前から香りのする木、いろいろな樹種の木を植えてほしいというようなこともございまして、多数植えてあります。１年、確実に成長して、そういった香りを出すように計画をしたものです。","id":"exchange-087"},{"speaker":"山路委員","kind":"質問","question":"１１年かかりまして、やっと品川区に香りを楽しめる公園、ハーブ園が誕生するのかなと思ったら、とても嬉しい限りです。平成１９年度の予算書には、どういう内容の工事をやられるのか、お伺いいたします。","respondent":"松代管理工事課長","answer":"公園の整備、改修等を計画的に進めておりまして、今、ご質問にありました横丁公園と二日市公園等々の改修をしてまいります。今回、なくしまして、少し広めの広場型にしてご利用いただければといった改修内容です。","id":"exchange-088"},{"speaker":"山路委員","kind":"質問・要望","question":"二日市公園のほうですけれども、地域住民の皆さんは、高齢者がたくさん多いので、健康器具を設置できないかというご要望もございましたが、この辺は検討されるんでしょうか、お伺いいたします。","respondent":"松代管理工事課長","answer":"平成１９年度予算ということで、説明会等も実施して、いろいろとご意見を聞きながら計画を進めていきたい。その中には、今ありましたような健康遊具等も含めて検討します。","id":"exchange-089"},{"speaker":"安藤委員","kind":"質問","question":"２月１３日、都知事あてに提出されたと伺って、短絡線への基本的認識を伺いたいと思います。反対なのか、賛成なのかということを、お伺いしたいと思います。","respondent":"阿部都市計画課長","answer":"まず地元の理解を十分に得るようにということと同時に、環境対策に十分配慮するようにということで、まずＪＲに申し入れを行いました。そういうことで、これからも環境影響評価の中でもそうですけれども、ＪＲに対しても申し入れをしていきたいと考えています。","id":"exchange-090"},{"speaker":"安藤委員","kind":"質問・要望","question":"具体的なことについて２点お伺いしたいんですけれども、区として、ＪＲのほうに地中化を求めていくということはあるんでしょうかということが一つ。その後、平面交差は解消されないということが、今わかってしまったわけですけれども、区としての立場といいますか、どうなんか尋ねました。","respondent":"阿部都市計画課長","answer":"去年の１１月の中で、当初からそういう説明がなかったではないかということを申し上げておりますし、十分に住民の方に再度説明してほしいと。きちっとした説明がなかったということを、１点、きちっと説明をしてほしいということも申し入れをしております。","id":"exchange-091"},{"speaker":"安藤委員","kind":"質問・要望","question":"交差が解消されない場合は反対ですという、区側のちょっと強い姿勢は、後退というか、撤回ということになってしまうのかということを確認したい。それから、やっぱり、玉虫色にするのではなく、具体的に地中化ということも文言として求めていってほしいなと思うんですけれども、いかがか尋ねました。","respondent":"阿部都市計画課長","answer":"先ほど申し上げましたけれども、短絡線について反対ということは申し上げてございませんので、その辺はご理解願います。先ほど申し上げましたとおり、意見書の中で、ルートについて事業計画案にかかわらず再検討されたいという申し入れをしております。","id":"exchange-092"},{"speaker":"安藤委員","kind":"質問・要望","question":"具体的にちょっとお伺いしたいんですが、こういった具体的な指導を、事業者、ＪＲ東日本に対して行っていただいているんでしょうか。区として独自に実施していただいて、その結果、情報を区民に提供していただけるんか尋ねました。","respondent":"田中環境課長","answer":"その点で、直接指導というよりは……。","id":"exchange-093"},{"speaker":"石田委員","kind":"質問・要望","question":"それには地域の要望もあるだろうし、そういうことを含めたことを、まちづくりの観点から。どうしても教育委員会からぽっと出てくると、お考えなのか、どうかということをお聞かせ願いたいと思います。","respondent":"松代管理工事課長","answer":"認識力といいますか、そういったものを、我々がきちっと持たなきゃいけないということを改めて感じております。公園としての機能は何としてでもきちんと保っていきたいと考えていますが、委員、少し柔軟に考えていくというのも一つかなと考えているところです。","id":"exchange-094"},{"speaker":"石田委員","kind":"質問・要望","question":"そういう打診もするのかどうかということも含めて、もう一度、お考えをお聞きしたい。ずっとそういうことがあったわけですから、まちづくりの観点からも、皆さんのほうからも声を挙げていただかないと。","respondent":"松代管理工事課長、日下部企画財政課長、阿部都市計画課長","answer":"権現山公園の位置づけ等と、今後の考え方です。多様な考え方を入れるとすれば、それに見合った公園がまた担保されて… もう１点の品川小学校入口の隣接地の問題でありますけれども、いずれにしましても、一つの課題として受けとめてさせていただきたいと考えております。私どもも、当然それを引き継いで、単年度で終わらせることなくやっていきたいと考えています。","id":"exchange-095"},{"speaker":"川西委員","kind":"質問","question":"ああいうのは、道路の維持管理の中に入っているのかどうか、伺います。それから、２６７ページ、道路安全施設修繕費と、側溝修繕というのはどういう内容のものか、一緒に、答えるよう求めました。","respondent":"藤田道路公園課長、齋藤住宅課長","answer":"今般、そういうような形での維持管理、パトロール体制に変更してきてあります。１１０番的に地域の方からご連絡、そのように取り組んでまいっておりますので、あとお話を聞くということに努めているところです。 そこは民地の部分ですので、維持補修は事業者にお願いをしております。維持補修が十分でない場合につきましては、私たち、事業者に対して、直すようにと指導をしております。","id":"exchange-096"},{"speaker":"川西委員","kind":"質問","question":"拡幅しているから、このように、事業がわりと有効に生きてきたんでしょうか。ちょっとその辺を伺います。","respondent":"片田建築課長","answer":"あるいは、区が整備させていただいたりといった形で、整備しています。そういう意味で、次は自分の番かなというような話も聞きますし、着実に整備が進んできているかなという認識を持っております。","id":"exchange-097"},{"speaker":"川西委員","kind":"質問","question":"建築完了検査済証というんですか、そういうのをいただかない場合は、どうなっているかわからない。しかし、検査完了済証というんですか、あれをいただく場合には、必ずそれが実施されていないと渡さないという了解でよろしいか尋ねました。","respondent":"片田建築課長","answer":"基準法の中で道路拡幅を求めているものは、必ずＬ型、あるいは舗装までして検済をおろさなきゃいけないというものにはなってございません。区がその工事のタイミングをとらえて事業者に働きかけて、今、整備を行っているというような状況です。","id":"exchange-098"},{"speaker":"川西委員","kind":"質問","question":"質問に出ていました南品川三丁目のことですが、地区計画の進み方について、これからの期間的にどうなっていくのか。私も、これだけの人が賛成して、書類は整っているというところまで聞いているんですけれども、いかがか尋ねました。","respondent":"阿部都市計画課長","answer":"今年の１月になりまして、街並みを考える会が、地域の方々を対象に、自分たちのまちづくりの案をお示しをしました。それが１週間、２週間でできるということではなくて、それにかかっているのかなと考えています。","id":"exchange-099"},{"speaker":"川西委員","kind":"質問","question":"ということになると、世帯数も多く、とてもこれは２０年かかってもだめかもしれないという不安も地元の人にありました。そういう点では、帯状の地区計画策定の方向で、区は進んでいただけるんか尋ねました。","respondent":"阿部都市計画課長","answer":"ある一定の地区のまちづくりの方針を示していく、地区計画の考え方ですので、原則はそれです。今、そういう用途の部分だけで地区計画を定めていくというものもありますので、そういうことも視野に入れながら検討してまいりたいと考えています。","id":"exchange-100"},{"speaker":"川西委員","kind":"質問・要望","question":"ですから、少し重点的に区としてはお考えいただきたいと、心から思います。いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"川西委員","kind":"質問・要望","question":"そういう点で、今後、ぜひ考えてほしいと求めました。それから、すみませんが、補助２８号線の計画について、進捗状況を伺っておきたいと思います。","respondent":"阿部都市計画課長","answer":"補助２８号線ですけれども、現在、きゅりあんのほうから事業開始していまして、国道まで事業を進めております。その中で進めさせていただいているのは、もう１点は、今は事業をされている区間が先ですと。","id":"exchange-102"},{"speaker":"川西委員","kind":"意見","question":"やはり、かなり歩行者の数が多い地域ですので、ぜひ、これは地区計画とともに、あの周辺の道路整備は必要だと思います。地域の皆さんにはいろいろなご意見があるようですけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-103"},{"speaker":"堺委員","kind":"確認","question":"２６９ページの補助１６３号線について、３点目が２８１ページにあります、お尋ねをします。過去何人かの委員の方からもお尋ねが出ておりましたけれども、ちょっと確認の意味で、教えていただけますか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"現在、戸越三丁目交差点につきましては、歩車分離信号機ということで、歩行者専用現示式をとっております。","id":"exchange-104"},{"speaker":"堺委員","kind":"質問","question":"たしかあそこは、幼いお子さんの事故によって、今、おっしゃったような形に切り替わりましたね。こうしてほしい、ああしてほしいとかという意見が寄せられているかと思うんですが、それはいかがか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"二現示の間、待っていななければいけないということで、そういう声も出ております。もう１点は、それを解消するために、スクランブル方式はいかがなものかという質問が出ています。","id":"exchange-105"},{"speaker":"堺委員","kind":"質問・要望","question":"今、交通安全担当課長がおっしゃっておられたように、それぞれの立場の方からと言っていいんでしょうか、改善策が出ていますね。改善策を早急に検討して、結論を出していただきたいと思うんですが、いかがか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"２番目に言いました、歩行者が２現示待たなければいけない、その次にまた２現示待って補助２６号のほうに行かなくちゃならない。説明をいたしているところなんですけれども、国道、警視庁と協議を重ねているところです。","id":"exchange-106"},{"speaker":"堺委員","kind":"質問・要望","question":"２点目の、補助１６３号線に関連してお尋ねをしておきたいんですが、特に未整備区間についての早期完成ということについて訴えてまいりました。我々としては、早く事業に着手して完成をしていただきたいという思いから、この件について確認をしておきたいんです。","respondent":"浜脇街路事業担当課長","answer":"はそれについて、どのぐらいの影響があるかということを、来年の予算で検討し、架道橋で言えば、概略設計等をしてみたいです。平成２０年度に予定して、できれば平成２０年度に検討し、なおかつ周辺の方々の土地の調査をしたいと考えております。","id":"exchange-107"},{"speaker":"堺委員","kind":"提案","question":"歳出の中での質問になるわけでありますけれども、昭和６２年１１月の第４回定例会の一般質問のときに、このように提案をした経緯があるんです。「来年２月の移転がはっきりしておりますので、今、所管のほうでえがいておられるイメージはどういうことなんか尋ねました。","respondent":"松代管理工事課長","answer":"私ども、ちょっと戸越の森というような仮称で呼んでおりますけれども、広く整備ができないかなということを考えております。そういったことを調査、研究、検討したいと思っているところです。","id":"exchange-108"},{"speaker":"堺委員","kind":"提案","question":"ほかにあるわけですから、昨年の予算特別委員会のときにもお尋ねをした際に、耐震診断はしていないとか。そういった意向をもとにしながら、最終的な決定を下していただければなと思いますが、いかがか尋ねました。","respondent":"松代管理工事課長","answer":"そういった意味では、非常に関心も高いですし、我々も、区民の皆様のいろいろな意見を聞きながら、その計画に反映できればと考えています。ですから、どういった手法が一番いいのかは、今後、検討しますけれども、十分に聞いて、研究、検討を重ねていきたいと考えています。","id":"exchange-109"},{"speaker":"松澤委員","kind":"質問・要望","question":"４目の百反歩道橋整備計画策定、これは、業務委託ですから３,０００万円の内容をお知らせいただきたい。それから、３項河川費、１目河川総務費、２７７ページですけれども、雨水利用タンク設置促進事業助成２０件、これについてもお伺いしたいと思います。","respondent":"原田下水道河川課長、青木都市開発課長","answer":"ということで、今回も同じように貯留管を整備していこうというで考えております。１３件、大体２０件程度の申込みを来年度は想定していくということで、予算を組んでいるものです。社宅の敷地につきまして、ＪＲが土地利用転換を図るのであればどのようなまちづくりができるかということをＪＲと共同で検討しているものです。","id":"exchange-110"},{"speaker":"松澤委員","kind":"質問","question":"やはりどうしても貯留部も必要だということですが、やはりできたら、ここでどの辺を計画しているかというのをお聞きしたいと思うんです。それから、平塚の上流部では、どのぐらいの容量の貯留管ができたのか、その辺をお聞きしたいと思います。","respondent":"原田下水道河川課長","answer":"ここを進めるに当たって、かなり可能性高く、我々としては検討しております。貯留管を２カ所つくっておりまして、１,２００ｔずつでありまして、合計２,４００ｔの貯留管ができ上がりました。","id":"exchange-111"},{"speaker":"松澤委員","kind":"質問","question":"浸透枡は３０カ所、透水舗装ということが全くないんですけれども、これは死語になっちゃったんでしょうか。そのような政策そのものは、どうなっているんか尋ねました。","respondent":"松代管理工事課長","answer":"一部歩道等にはする場合もありますし、透水性のアスファルトもありますし、ほかのブロック等のものもあります。現在でも、歩道の改良にあわせて透水性舗装等をやっている部分もあります。","id":"exchange-112"},{"speaker":"松澤委員","kind":"質問・要望","question":"当時は墨田区の路地尊ですか、あれがいいと、盛んに視察に行ったり、いろいろ質問もたくさん出ました。雨水を利用して打ち水をしてくださいという施策ですから、どうかこの地域の方たち、なかなか広がらないと思うんです。","respondent":"原田下水道河川課長","answer":"ただいま、ご指摘いただいたとおり、確かにＰＲの仕方としてはまだまだ改良の余地があると考えています。平成１８年度に実施したＰＲ内容をしっかり見直しまして、今以上に涼のみち整備事業とも連携を密に図りまして、助成事業を詰めていきたいと思います。","id":"exchange-113"},{"speaker":"松澤委員","kind":"質問","question":"２方向、環状６号線のほうに抜けるような歩道橋をつくるのかなと、相当大きなものになると思うんです。当然ながら、もっと人がたくさん通れるような大きなものを想定しての整備ということで、よろしいんか尋ねました。","respondent":"青木都市開発課長","answer":"そういう意味では、歩道橋に関しては、人が増える可能性があります。老朽化しておりますので、ある程度状況を見て、かけ替えも視野も入れた検討をしなきゃいけないということで、検討を始めるものです。","id":"exchange-114"},{"speaker":"松澤委員","kind":"質問","question":"目の前にある同じ社宅が直されているのは、あれは何だろうという気がしてるんですけれども、ここは含んでいないんでしょうか。その辺、もうちょっと説明を求めました。","respondent":"青木都市開発課長","answer":"歩道橋の３,０００万円につきましては、その結果を検討に反映したいということで、若干お高い値段を予算計上しています。平成１５年から継続してＪＲと協議を重ねながら検討を進めておるんですけれども、区としては継続してこの取り組みを進めていきたいと考えております。","id":"exchange-115"},{"speaker":"松澤委員","kind":"質問・要望","question":"バブルのときに大きな乱開発をとめるということで、構想をして、大きなお金をかけています。大変にちょっと、この先どうなるのかと思いますので、むだにならないような形で予算を使ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"宮崎委員","kind":"質問","question":"２８５ページの密集住宅市街地整備促進事業について伺いたいと思います。この計画案について、区のほうは、まちづくり協議会での合意があったのか、どうなのか、そこら辺の認識を、まず伺いたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"では計画案というのは、だれがつくるんだといった場合に、基本的には、事業を実施します区が責任を持ってつくるということで話をしております。特にその計画案をつくるのに、協議会の方々の合意等をあえて取っているというようなことはございません。","id":"exchange-117"},{"speaker":"宮崎委員","kind":"質問・要望","question":"本当に一生懸命まちづくりのために参加してきた方は何と思うんでしょうか。４月からいよいよ事業開始となっているんですけれども、都市計画なんだと、この関連というのは一体どういうふうに進めているんか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"それから、既に都市計画決定されているものものせる必要があるということで、のせております。これは、密集事業でやるものではないんですが、総合的に、このまちをどういうふうにしたらいいのかということで、のせたという経緯です。","id":"exchange-118"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、私は、今の発言は撤回していただきたいということを、改めて言いたいと思います。例えばスケジュールも含めて、具体的にいつごろどういうふうなことを考えているのか、今わかっている範囲で説明をほしいと求めました。","respondent":"福田まちづくり事業部長、伊勢住環境整備担当課長","answer":"そういう意味で、私どもは合意をとりつける、そのための理解を促す、この努力は継続していきます。いきますけれども、しかし、今の段階において、何か物差しではかって合意があるとか、ないとか… ２９号線は、これまで若干質問等がありまして、議会の請願等の採択状況、あるいは、延焼遮断帯について、口頭ではありますが、説明した記憶があります。","id":"exchange-119"},{"speaker":"宮崎委員","kind":"質問","question":"例えば、本当に延焼遮断帯として２９号線が適当なのかどうなのか、そういうことも話をしてないというふうに言っているんです。そういう話し合いというのはやったんでしょうか、そこのところ。","respondent":"伊勢住環境整備担当課長","answer":"２９号線のお話はしましたけれども、皆さんでこうしたらどうかというようなお話はしませんでした。２９号線の働きかけというのは、また見直すときには、そういう形で働きかけたいと考えております。","id":"exchange-120"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、今の東京都の計画だとか、そういう中で、これをどう整合性を持たせるのか、こういう課題は、それはそれであると思うんですよ。そこのところをぜひ、説明ほしいと求めました。","respondent":"伊勢住環境整備担当課長","answer":"２９号線の防災性に果たす役割というのはありますけれども、さらに２９号線につきましては、こういう位置づけです。","id":"exchange-121"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、ここで、住民同士でもっと話し合いをしたい、これが一番の願いなんです。そういう要望にこたえて、どうなのか、説明をお願いしたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"２９号線を整備するときに、密集事業を進める中で、地域の方々のご相談に乗りながら進めていきたい。それから、もう一つ、延焼遮断帯ですけれども、東京都の防災都市づくり推進計画でも位置づけられているという位置づけもあります。","id":"exchange-122"},{"speaker":"宮崎委員","kind":"質問","question":"住民参加でということであれば、そもそもそこのところからの議論がなぜできないのかということが、一番の疑問と思っているところです。いろいろ話を聞くと、そういう心配もあるんですけれども、そこのところはどうなんか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"コンサルタントは、もちろん住民の方と直接お話をするという機会はないわけではないんですけれども、基本的に、今、計画段階ですので、住民の方と特に接触するのは我々区役所の職員で、コンサルタントのほうは、いろいろな資料の作成というようなことをやっているのが現状です。","id":"exchange-123"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私は、そこの計画づくりから住民とかかわるのがコンサルタントの役割だと思います。ここのところを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-124"},{"speaker":"土井委員","kind":"確認","question":"二千何百万円もかけるわけですから、そんなものに塗装したってしようがないわけですから、お伺いをしたい。ちょっと２７１ページの１６３号線の鉄道架道橋等のところでのお話では、確認をいたしますと、これはそこだけ確認をしておきたいと思います。","respondent":"松嶋交通安全担当課長、松代管理工事課長、浜脇街路事業担当課長","answer":"検討会等を実施してきた中で、横断歩道の直近に設置することは、５ｍ以内駐停車禁止場所であることから言えば。考えているところは… 昨年の９月ごろ、予算計上したときには、正直言いまして、まだ今回のこのかけ替えのスケジュールがきちんと決まっておりませんでした。… それから、品川区の庁舎の一部が１６３号線にかかっているですので、それをまず調査をしてみたいです。","id":"exchange-125"},{"speaker":"土井委員","kind":"質問・要望","question":"ですから、自転車が通るんです。こちらと向こうを結ぶ交通体系の中にどう取り入れていくのかということで考えていただかなきゃいけない、お話しているんですが、いかがか尋ねました。","respondent":"青木都市開発課長","answer":"再三ご説明しているとおり、百反隧道の安全性の確保も、当然テーマに入っております。今の段階でのあらあらの検討ですけれども、エレベーター等を設置して、そういったことを検討しております。","id":"exchange-126"},{"speaker":"須藤委員","kind":"意見","question":"２８５ページ、平成１１年から実験されて、遮熱性を広場とか広い範囲でという考え方でよろしいのかどうかとの意見を述べました。","respondent":"松代管理工事課長","answer":"委員ご指摘のとおり、保水性舗装は、そういう商店街等の協力を得て打ち水をやっていただく、そういったところでの施工を考えております。遮熱性舗装は、もう１カ所、大井町駅前の西口のバスのレーンがありますけれども、そこにします。","id":"exchange-127"},{"speaker":"須藤委員","kind":"質問","question":"それで合っているか、どうかだけ答えてください。１m2が２万７００円、１m2２万２,７９０円というような数字が出てきているんですけれども、遮熱性にするとかという考え方はできるか尋ねました。","respondent":"松代管理工事課長","answer":"私どもも八潮で実験をして、商店街等に実施しています。これを将来どうするかというのは、もう少しそういった市場の価格等も含めて、十分に検討をしていきたいと思っているところです。","id":"exchange-128"},{"speaker":"須藤委員","kind":"質問","question":"そうすると、そういうところも、そういった整備をしてくる考え方を持ってもらえないか。仮称中延五丁目の広場整備についても、せっかくやるんですから、そのあたりの考え方はいかがか尋ねました。","respondent":"松代管理工事課長","answer":"取り組みに参加していただいて、そういう機会の一つの場は、検討の一つかなと考えています。公園整備とか、そういったところにも、可能性があれば少し研究をしたいと考えています。","id":"exchange-129"},{"speaker":"須藤委員","kind":"質問・要望","question":"平成１１年からこういった制度に取り組んでもらったというのは、先ほどの雨水のあれも含めながら、全体計画としてつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-130"},{"speaker":"三上委員","kind":"質問・要望","question":"最初に防災生活圏の中で、小山台一丁目の、ちょっと関係する４６号線の現状、簡単でいいですから、お教えいただきたい。どうしていくかということについて、簡単でいいですから、お願いしたい。","respondent":"阿部都市計画課長、伊勢住環境整備担当課長、松代管理工事課長、齋藤住宅課長","answer":"４６号線の現状ですけれども、平成１９年度までの事業認可を取っておりまして、現在、委員ご承知のように、２件について収用手続に入っているです。… それから、目黒公園、事業認可の取消しについては、去年１１月２２日に決定しております。地区防災道路３からの取付け道路の関係ですけれども… 私どもで手直しをしまして、今後管理していくということで、了解をとってあります。施工等は、来月になろうかと考えています。インターホンのことから、ご説明いたします。","id":"exchange-131"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、そこらあたり、もうちょっときめ細かく、お年寄りの方もいらっしゃいますから、ぜひ、そうしてやってほしいと求めました。それは東京都との話し合いになるのかもわかりませんけれども、ちょっとご検討いただけるかどうか、お願いします。","respondent":"松嶋交通安全担当課長","answer":"あそこはちょっとまだ正式ではありませんけれども、こちらのほうから、そこら辺もあわせて聞いてみます。","id":"exchange-132"},{"speaker":"三上委員","kind":"質問","question":"その期間だけでも、自転車を暫定的でもいいから置かせてくださいと。少しでも小山の駅のほうに広がっていくわけですから、一時期でもいいですから、お願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-133"},{"speaker":"沢田委員","kind":"質問・要望","question":"再開発事業、とりわけ北品川五丁目第一地区の開発に絡んで、質問をさせてほしいと求めました。総事業費、補助金、都市再生事業として見込まれる税金投入、どれぐらいになるのか、示してほしいと求めました。","respondent":"青木都市開発課長","answer":"都市再生事業につきましては、小関橋のかけ替えが直接的には関連するもので、これが１３億円ほどで、現在、施工中です。北品川五丁目の第１地区に直接関係するものでの都市再生整備事業は、特にございません。","id":"exchange-134"},{"speaker":"沢田委員","kind":"質問","question":"この中で、今の話では、区と地権者の意向が一致したということを言われたんですが、地権者以外でこの中に住んでいる人、事務所を持っている人、工場数、要するに立ち退きを余儀なくされる工場と住民は、どのぐらいいるか、説明を求めました。","respondent":"青木都市開発課長","answer":"都市計画決定に向けての準備を進めていて、現段階ではまだ確定していませんので、お答えできません。","id":"exchange-135"},{"speaker":"沢田委員","kind":"質問","question":"８月には都市計画決定をすると、どんな雰囲気だったのか、教えてほしいと思います。それは、権利者が中心になるということは、私は否定しませんよ、その土地や財産を出して開発をやるんですから。","respondent":"青木都市開発課長","answer":"再度、確認でお答えいたしますと、住んでいる方を含めまして、約３００人が方々が、住むとか、権利を持つとかという形でかかわっていらっしゃいます。企業数は、１１社いらっしゃいます。","id":"exchange-136"},{"speaker":"沢田委員","kind":"質問","question":"それから、１１というのは要するに地権者ではないけれども、賃貸などで企業が営業しているということでよろしいか、どうかということが一つ。この地域内にどのぐらいいて、準備組合に加入している人がどれぐらいいるのか、改めて説明を求めました。","respondent":"青木都市開発課長","answer":"説明会につきましては、２日間行いまして、あわせて都市計画決定を予定しておりまして。高層マンションを建てますので、その高さについては何とかならないのか、自分のところは日影になっちゃうというようなご意見もいただいております。","id":"exchange-137"},{"speaker":"沢田委員","kind":"意見","question":"８月に都市計画決定をやるという具体化をしてきている中で、だけれども、地域住民で暮らしている人たちに説明されたのか。それから、今後、理解を得るためにどういう努力をしていこうとする計画なのか、説明願いたいと思いますとの意見を述べました。","respondent":"青木都市開発課長","answer":"設計も進んでまいりますので、今度は、いわゆる高層建物の建築紛争条例に基づく近隣の方々に対する説明会という形になっていきます。工事着工段階では、施工者も交えての工事説明会という形で、近隣の方々とのお話し合いが続いていくものと考えております。","id":"exchange-138"},{"speaker":"沢田委員","kind":"質問","question":"これは住民参加の品川区の方針ですか。不十分だとは思わないか尋ねました。","respondent":"青木都市開発課長","answer":"独自にそれぞれの判断でご説明するなり、ご理解を求めるなりしてくださいという形で、今までは進めてきております。それについては、できれば大家との関係でやっていただきたいというのが、これまでの私どもの取り組みです。","id":"exchange-139"},{"speaker":"沢田委員","kind":"質問","question":"品川区は、大崎体育館、３５年でまだまだ使えるのを、小中一貫校に持っていったじゃないですか。区が入っていればこそ、住民に十分な説明、さまざまな意見を聞いて調整をするということが、まちづくりのあり方じゃないんか尋ねました。","respondent":"福田まちづくり事業部長","answer":"それから、さまざまな責任者、今のご質問に沿って言うならば、さまざま説明責任者がいる。できる限りの説明を、これからも、事業者がそれを伝えていくと考えております。","id":"exchange-140"},{"speaker":"沢田委員","kind":"質問","question":"それから高層棟が大崎のまちに林立しているけれども、こんなまちは望んでいない、もっと超高層をなくして低い住宅にしてほしいという声もありました。最大の地権者の１人でもあるわけですから、それ１回にとどめずに、そういう要求もありました。","respondent":"青木都市開発課長","answer":"地元の方々、近隣の方々のご意見はどうなのか意見掌握してくださいということで実施したものですので、今回の１回という言い方をしたんだと思います。先ほどの繰り返しになりますけれども、手続にのっとって、皆さんのご意見をもちろん集約していくということは予定しています。","id":"exchange-141"},{"speaker":"沢田委員","kind":"質問・要望","question":"東五反田二丁目第１地区だって、今、いろいろな反対運動が起きていますよ。それは、ほとんど説明がないということに集約されます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-142"},{"speaker":"伊藤委員","kind":"確認","question":"確認は、京浜運河からの水を導入をした等々、いろいろな浄化実験をやってきました。確認したいので、そういう実験の結果を、品川区としてはどういうふうにまず評価をしたのかということが一つ。","respondent":"原田下水道河川課長","answer":"そういった取り組み一つ一つの教訓をしっかり踏まえまして、次につなげていきたいと考えている中で、今後の計画を考えているです。立会川で本格実施できるか、あるいは、目黒川への適応性等についても考えていきたいと考えているところです。","id":"exchange-143"},{"speaker":"伊藤委員","kind":"確認","question":"次に質問しようと思っていたことが出てきたんですが、どういうタイミングで、まず一つ考えなければいけない。確認したいのが、どういうタイミイグで投入して、どれぐらいの量を投入したらいいかということの計画があればということが一つ。","respondent":"原田下水道河川課長","answer":"これを本当に実験で確かめていこうと考えていますが、今後、決めていきたいと考えているところです。そのようなことで、下水道による根本的な対策が終わるまでの間の対策として、我々として水質浄化の取り組みを進めていきたいと考えております。","id":"exchange-144"},{"speaker":"伊藤委員","kind":"質問・要望","question":"川本体をどう頑張ってきれいしたとしても、次に出てくる、どうしても避けて通れないのが鮫洲運河の浄化です。川本体のことをどんどんやっていただきたいし、下水道も整備していただきたいんですが、品川区の考え方を説明を求めました。","respondent":"原田下水道河川課長","answer":"そのようなことで、要望活動をしっかり続けていきたいと思います。住民への説明等、我々も一緒に説明するといったことで、区としても応援していきたいと考えております。","id":"exchange-145"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それから、広町地区は、簡単にお伺いします。確認したいのが、ＪＲと区長の間で協議が整った内容が、まずあるかどうかということを説明を求めました。","respondent":"青木都市開発課長","answer":"簡単に申し上げます。現段階で、まとまったものはございません。","id":"exchange-146"},{"speaker":"伊藤委員","kind":"確認","question":"となると、この検討委託の位置づけが非常に微妙になってくるわけですよね。勝手に人の土地に絵をかくという形になりかねないわけですから、確認したいのが、お願いします。","respondent":"青木都市開発課長","answer":"この検討につきましては、平成１６年度以降は、ＪＲ東日本との協議に基づいて共同で発注するという形をとってあります。その半分は歳入としてＪＲからお金をいただくという形での検討ですので、ＪＲとずれのない一定の方向性のあるものができ上がると考えております。","id":"exchange-147"},{"speaker":"伊藤委員","kind":"確認","question":"もう一つ確認したいのが、検討委託という表現ですから、どこかに計画を委託をするわけですね。お伺いしたいのが、どういう形の検討を委託していくのかということ。","respondent":"青木都市開発課長","answer":"現在も、検討を進めておりますので、ちょっと不確定ですみません、場合によっては、ＪＲとの一定の方向性が出れば、広く公表したいと考えております。不明な部分がありますので、現段階では、具体的なことは申し上げられません。","id":"exchange-148"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/472478?Template=document&Id=884#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":119768,"voices":356}},{"id":"h19-20070314-3","meetingId":"h19-c-budget","date":"2007年3月14日","dateIso":"2007-03-14","committee":"予算特別委員会","time":"午前１０時０４分～午後５時５３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を150件整理しています。","topics":[{"id":"topic-01","title":"平成１９年度品川区一般会計予算","agenda":"平成１９年度品川区一般会計予算","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"プラン２１関連事業関係、３２１ページ、歴史館の関係で質問させてほしいと求めました。状況の細かいことはわからないんですけど、資料の開示をどういうふうに考えているかということを説明を求めました。","respondent":"古里学務課長、富田生涯学習課長","answer":"そのうち、最終的に全部が繰り上がらなかった学校が、第二日野小学校、原小学校、この２校です。現在入れなかったというか、最終的に待ち状態のまま終わってしまった方が約６０名程度… お見えになった区民の方々をはじめとして、レファレンス等も行っているところですが、大変申しわけございません。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"意見","question":"上の子がいるから優先的に入れてあげるべきなのか、それとも、公平に抽選で考えていくべきなのか、そこら辺が、我々にも声が伝わってきています。その辺どうお考えかなとの意見を述べました。","respondent":"古里学務課長","answer":"この中では、選択をした結果、兄弟が別々の学校になるということについても、学校案内に周知をしています。検討いたしましたけれども、やはり従来どおり、品川区の方式を継続するということで考えております。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"プラン２１の中で、これは前も質問したことがあると思うんですけれども、地域的なハンデがあると思うんですね。既にやっていらっしゃるんでしょうけれども、これからどういうふうに考えていかなきゃいけないのかなという点でお答えをほしいと求めました。","respondent":"吉村小中一貫教育担当課長","answer":"教員の問題が１つ課題として出てまいりますので、連携校に非常勤の教員を配置して、その連携を少しでも補助する。そういったことを今現在進めているところです。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問","question":"一貫校ですと、そのまま顔を知った子がみんな一緒に上へ上がっていく。そこに小学校が３つか４つついていたら、そこの交流というのはどういうふうに考えていくのかなというのを説明を求めました。","respondent":"吉村小中一貫教育担当課長","answer":"考え方としては、１つは、こういった部分についての研究を２校の小学校が一緒にやる。１年目を終えて、２年目に向けて、準備をしています。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"意見","question":"やっぱり接触は非常に少ない部分があると思うので、子ども同士の交流という面でも、これからもまたその辺もよくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"私は、２９７ページのプラン２１関連事業に関連して質問したいと思います。改めて、品川の教育改革の目的、プラン２１の目的についてお尋ねしたいんですが。","respondent":"河野指導課長","answer":"プラン２１の目的ですが、プラン２１は、子どもたち、あるいは保護者の期待にこたえる公立学校づくりということが一番大きな目的です。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"子どもの姿が全然見えてこない。子どもは学びの主人公のはずですから、その目的の中に、もう少し丁寧な答弁をお願いしたいと思います。","respondent":"河野指導課長","answer":"ただ、私たちはそういう学校に対して、さまざまな支援を行ってきております。さまざまな教材関係の購入の支援であるとか、目標としている成果が達成できるように、教育委員会としても支援をしています。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"品川なんですけれども、すべての子どもたちに学ぶ権利を保障するということをどのように行っているのかということをお伺いしたいです。この冊子を読ませていただいたんですが、習熟度別授業を取り入れている理由と、何を根拠にしているのかということをお伺いしたい。","respondent":"吉村小中一貫教育担当課長","answer":"これが品川区の実施している習熟度別学習です。できない子に分けているのではなくて、わかっている子とまだわかっていない子、このまだわかっていない子に対するきめの細かい指導をしているです。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"４年生の担任で、現役で品川区で先生をやっている方の話を伺う機会がありまして、１人先生を加配するということをお伺いしたんですが。まだ４年生なので、丁寧に教えてもらうことが素直にうれしい。","respondent":"吉村小中一貫教育担当課長","answer":"プラス、品川の場合には、再三ご説明しておりますが、指導助手という形で、教員免許を持っている人間を配置している。あくまでも固定的なもので勉強していることではないということを十分ご理解いただければと思います。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"もう一度お伺いしたいんですが、先ほど紹介したような実態というのはご存じか尋ねました。","respondent":"吉村小中一貫教育担当課長","answer":"習熟度別学習については、平成１２年から各学校でスタートし、７年間を経ております。そういう部分をきちんと指導しましょうということをこの７年間やってきておりますので、例えば今年、我々は把握しておりません。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"私が視察した浜之郷小学校でも、明確に習熟度別の導入はやめておりましたので、そういった習熟度別はやめるべきではないかと。そういうことをやめた上での少人数の学び合いの教育スタイルをとるべきではないかと思うんですが、いかがか尋ねました。","respondent":"吉村小中一貫教育担当課長","answer":"そしてもう一つ、保護者の方がこのきめ細かな授業スタイルについて、非常に好意を持って評価をしてくださっている。品川区の現実の子どもたち、保護者の声を聞きつつ、今現在はこの習熟度別学習を変えていくという気持ちは全くございません。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"４年生から９年生まで毎年テストがあるという、品川区の学力、冒頭で申し上げましたよね。確かな学力というのは、東京でやっていたり、国でやっているやつの品川区の学力テストの結果の推移はどうなっているんか尋ねました。","respondent":"河野指導課長","answer":"国語７３.５％に対して、平成１８年度の学力調査においては、８３.７％というような到達度の向上を示しております。なお、東京都においては、学力テストの平均点ですので、これは比較の対象にはならないかと思います。","id":"exchange-012"},{"speaker":"武内委員","kind":"質問・要望","question":"２９７ページの小中一貫教育の推進と、３１９ページの品川版総合型スポーツクラブの設置の３点についてお伺いします。原小学校が約２０名と、残念ながら希望に沿えなかった方がいるというお話を伺ったんですが、定員が何名だったのか。","respondent":"古里学務課長","answer":"３クラスの定員そのものは、１２０名ですけれども、将来の転校枠を考えて、１００名まで受け入れをしています。それぞれ１１０名程度、１０７名程度というふうに、最終的な数ですが、その程度でということで聞いてあります。","id":"exchange-013"},{"speaker":"武内委員","kind":"質問","question":"その１０名、７名、１００名受け入れに対して増えたのは、いわゆる転入ということでよろしいんか尋ねました。","respondent":"古里学務課長","answer":"抽選を行う時点での定数以外に、転居によって入ってこられる方がいらっしゃいました。その方によって、定員の１００名より超えた受け入れの数になっているというものです。","id":"exchange-014"},{"speaker":"武内委員","kind":"質問","question":"３番目、ぎりぎりになって１０名近くがいきなり転入してきたということで、あなたたち待機はもう入れませんよということになってしまった。今、そんな看板を出すぐらい白熱しちゃっているということをお聞きしているんですけれども、その辺の状況はどのように認識されていますか尋ねました。","respondent":"古里学務課長","answer":"私どもとしては、一体型小中一貫校をできるだけ各地区に速やかに展開するということで、小中一貫校６校構想を立ち上げてあります。私どもとしては、全力を挙げて、その実現方、努めたいと考えています。","id":"exchange-015"},{"speaker":"武内委員","kind":"質問","question":"今回、小学校５校、中学校６校で抽選があったということなので、必ずしも日野と原の小中の施設一体型のところだけということではないとは思うんですけれども、実際にこの２つの小学校に入れなかったということで、この人気の原因はどのように考えていらっしゃるんか尋ねました。","respondent":"古里学務課長","answer":"それ以外にも、学校の特色をきちんと見て、その中で選択された結果だと考えています。そういう意味では、選択制そのものの権利を皆さんが行使なさっているということの結果かと思います。","id":"exchange-016"},{"speaker":"武内委員","kind":"質問・要望","question":"転入というんですか、平等なチェック体制もできれば厳しくやっていただきたいし、そのようなお声の起きないようなことをぜひ期待したいと思います。これもお聞きしたいんですけれども、なかなかうまく調整がいかないという声を聞いたんですけど、その辺の実態はどうなんか尋ねました。","respondent":"富田生涯学習課長","answer":"両方が時間を、３０分なり１時間なり、譲り合う形でご利用いただいているところがほとんどであると考えております。","id":"exchange-017"},{"speaker":"武内委員","kind":"提案","question":"私も具体的にどこの学校でどういうあれだというところまでは今日言うつもりはないので、ただ、またご相談させてほしいと求めました。私たちも提案させていただいたときは、今回、スポレクとかというのをどんなふうな形で運営していくのかということを教えてほしいと求めました。","respondent":"富田生涯学習課長","answer":"多レベルで行っていくということで、東京都でも、国体実施の２０１３年までには各区市町村に１つはということで言われているところです。","id":"exchange-018"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、拠点は日野学園の体育館とか総合体育館とか、そういうところを使われるのかということと、あと、自主運営でやられるということなので、その辺、スポレクを中心とした新たな組織、運営協議会みたいなものをつくるのか、その辺も説明を求めました。","respondent":"富田生涯学習課長","answer":"こちらにスポレクの方々のご協力をいただきながら、地域の方が参加する会員制のものに順次移行する形にしてまいりたいと考えています。体育指導委員会内部でも検討組織を設け、検討を重ねてきているところであり、１７とまではいきませんけれども。","id":"exchange-019"},{"speaker":"武内委員","kind":"質問","question":"今、最終的には文部科学省のほうも各中学校区に１つ、こういった総合型のスポーツクラブを設置していきたいという目標があるみたいなんですね。今そのお話なのかなと思ったんですけれども、その辺のところと、あと先ほどお伺いした、自主的な運営主体の考え方を説明を求めました。","respondent":"富田生涯学習課長","answer":"区民の皆様方の実行委員会のような、そうした組織になっていこうかと思いますが、これはまた今後検討してまいりたいと考えています。大きなまとまりで、４ブロックありますので、その辺で広げていければというふうに現在では考えております。","id":"exchange-020"},{"speaker":"武内委員","kind":"質問・要望","question":"そういう取り組みの趣旨があると思いますので、ぜひ期待をしておりますので、頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"阿部委員","kind":"質問","question":"２９９ページ、３０３ページのプラン２１、３２１ページの文化センター建設費についてお伺いしたいと思います。そのスケジュールと、議会としてどこまで内容に関与できるのかということを説明を求めました。","respondent":"河野指導課長","answer":"教員の独自採用の今後の予定ですが、平成１９年度中に検討して、計画を立てているところです。","id":"exchange-022"},{"speaker":"阿部委員","kind":"質問・要望","question":"それから、自主的にそういったことが言っていけないというのであれば、この場で、要望を兼ねてなんですけれども、言わせていただきます。ですから、あるいはそういった資質を持った方ということが必要ではないかと思いますが、事務局のお考えを説明を求めました。","respondent":"河野指導課長","answer":"先ほどのご質問の中の議会の関与という点ですが、こちらの検討過程につきましては、逐次、文教委員会にもご報告させていただきたいと思います。県費負担教職員という立場で任用になりますので、そういうようなことも含めて、今後さらに検討してまいりたいと考えております。","id":"exchange-023"},{"speaker":"阿部委員","kind":"質問","question":"次に、特別支援教育体制についてお伺いしたいのですが、聞きたいことが山のようにあるんですけど、終わらなくなっちゃいますので、１点だけ。個別指導計画については、小中学校の普通学級などでの作成も平成１９年度から始められるというイメージでよろしいのか尋ねました。","respondent":"河野指導課長","answer":"通常学級においても今後作成を支援するということで、保護者の要望も受けとめながら、具体的に作成していく予定です。なお、現在のところ、１年間ごとには最低つくるということで、できれば学期ごとに見直せるような方向で今詰めているところです。","id":"exchange-024"},{"speaker":"阿部委員","kind":"質問","question":"特別支援教育で、もう一つ忘れていました。第二日野小学校部分にも心障学級があるのが理屈の上ではすっきりするのではないかなと思うんですけれども、その辺いかがお考えか尋ねました。","respondent":"河野指導課長","answer":"日野中学校のほうに心障学級が設置されておりましたので、日野中学校のほうの心障学級はそのまま継続ということで現在も開設しております。","id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"中学校部分での心障学級ではあるけれども、運用としては、９年間にわたる支援のリソースルーム的な存在であると解釈してよろしいですか。平成１９年度からというわけにはいかないかもしれませんけれども、これは学校規模の適正化の話と絡めて行っていくようなお考えはあるのか尋ねました。","respondent":"林（宏）委員長、古里学務課長","answer":"平塚中学校と平塚小学校の一貫校ということですよね。平塚学園というのはまだありませんから。 当然のことながら、今後検討されることの中では、学区域の問題も検討されるべき課題というふうには認識しています。地域の方々とよく協議をしながら、学区域の問題については検討してまいりたいと考えています。","id":"exchange-026"},{"speaker":"阿部委員","kind":"質問","question":"もちろん社会教育施設ですから、それも、それを各学校に配置して教材として使ったほうがよほど感動的な授業ができるのではないかと考えています。そういうような考えを持っておりますが、いかがか尋ねました。","respondent":"富田生涯学習課長","answer":"４０人定員ですので、今の５,０００人弱の利用でありますけれども、１学級単位しか利用できないということもあります。それとともに、現在の観覧者数を圧倒的に超えるような多くの方々に末永く利用いただけるような施設にしていきたいと思っているところです。","id":"exchange-027"},{"speaker":"山内委員","kind":"質問・要望","question":"私からは、２９５ページ、生活指導対策費のクラブ活動指導対策費についてお尋ねさせてほしいと求めました。確認なんですけれども、クラブ活動指導対策費というのは、外部指導員の報酬ということでよろしいのか尋ねました。","respondent":"古里学務課長","answer":"外部講師の費用として予算計上しています。","id":"exchange-028"},{"speaker":"山内委員","kind":"質問・要望","question":"そんな中、特色のあるクラブ活動、部活動というものをしていかなくてはならないのではないかと思って、本日質問させていただきたいなと思いました。中学の教員の方の負担軽減というものも組み入れた形での外部指導員というものを積極的に入れていくお考えはあるのか、説明を求めました。","respondent":"河野指導課長、古里学務課長","answer":"特に中学校の教員は、先ほど申し上げたような部活動の意義を踏まえて、部活指導にも取り組んでいる実態があります。さらにすぐれた技術… 外部指導員の招聘費用については、予算書３００ページの下から９行目、これが私が先ほど申し上げた経費です。訂正させていただきたいと思います。","id":"exchange-029"},{"speaker":"山内委員","kind":"質問・要望","question":"じゃあ、どうするのと。外部指導員という部分の意味で考えていただきたいなと思うんですけれども、これはまだ同じお答えになっちゃうかもしれないんですが、すいません。","respondent":"河野指導課長","answer":"ある程度の人数を要する部活の場合は、幾つかの種目で数校が集まって、合同で活動するという取り組みも行っております。これからも、できるだけ大勢の子どもが、自分がやりたい活動ができるように、私どもといたしましても支援してまいりたいと考えているところです。","id":"exchange-030"},{"speaker":"山内委員","kind":"質問・要望","question":"外部指導員を積極的に受け入れる体制を要望いたしまして、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"２９７ページのプラン２１関連事業のうちで、まちの人々に学ぶ授業についてお伺いします。この授業の目的と授業内容と対象年齢を説明を求めました。","respondent":"河野指導課長","answer":"あるいは最近では、そういうような昔の遊びを紹介していただくという取り組みまで含めて、さまざまな形で取り組んでいただいている実績があります。それぞれ、中身によって、特に年齢制限ということはとってございません。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"人生を教えるという形にもなっていくと思うんですけれども、どうかこの事業にそういうことが反映できないかということが１点。よく企画部のほうで、団塊の世代に地域を担っていただくということが出ますが、そこら辺については、お考えはありますか尋ねました。","respondent":"河野指導課長、日下部企画財政課長","answer":"学校の中では、子どもたちといろいろな経験を持っているまちの人々が、そういう触れ合いを行ってくれるということも私たちは期待をしています。そういう意味も含めて、子どもたちとの触れ合いを通して… さらにまた、今ご指摘ありましたように、教育面でのいろいろな経験を伝えていただく。非常に重要なことだと思いますので、私どもとしましても、その辺は教育委員会との連携等も含めて、今後積極的に取り組んでいきたいと考えております。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"次当選できたら、次の質問で、「あれはどうなりましたか」と必ず質問させてほしいと求めましたので、よろしくお願いいたします。それと、子どもたちが地域を担っている１つである商店街に出ていったり、いろんな現場に出ていって学ぶという形は何か考えているんか尋ねました。","respondent":"吉村小中一貫教育担当課長","answer":"例えば３年生の商店街の勉強が社会科にありますけれども、そういうときには、積極的に子どもたちを商店街に連れていきます。必ず現場に出ていって、社会のいろいろな仕組みを考えていくということをやっておりますので、これについては今後も継続していきたいと考えています。","id":"exchange-034"},{"speaker":"井上委員","kind":"質問","question":"私からは、３２１ページの五反田文化センターの改築についてお伺いをいたします。この文化センターの改修は、もしそうであれば、どういった利用団体を想定しているのかということをお伺いしたいと思います。","respondent":"富田生涯学習課長","answer":"五反田文化センターの改築に当たりましては、これまで区の中で２００人から２５０人規模の音楽ホールというのがあまりございませんでした。演劇とか、ほかでも使いたいよということであれば、利用はできるという形で進めてまいりたいと考えています。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問","question":"プロポーザルのところに、太鼓なんかをする団体も想定をされているということも書いてあったかなと思うんですけれども、ここの音楽専用ホールというところでは、太鼓の演奏者とか、そういう発表の場というふうには考えていらっしゃいますか尋ねました。","respondent":"富田生涯学習課長","answer":"区内に太鼓、特に和太鼓等を含めた防音設備のある施設が全くございませんので、そういう意味では、太鼓、和太鼓の防音を含めた仕様の施設にしていきたいと考えています。","id":"exchange-036"},{"speaker":"井上委員","kind":"質問","question":"私がお伺いしたところによると、きゅりあんの大小ホールでも和太鼓は振動があって使えないという状況だと伺っているんですね。遮音というか、複合施設でもあるわけですから、その辺の設計にはきちんとそういう構造的な対策をとるということは十分考えられているのか尋ねました。","respondent":"富田生涯学習課長","answer":"ないとは思いますけれども、遮音ができるかということについては、できる限り努力をしてまいりたいと思っています。設計業者にも、その旨ははっきりと最初の条件として提示をしているところであります。","id":"exchange-037"},{"speaker":"井上委員","kind":"質問","question":"ここは２５０人ですから、利用団体、ここで利用ができる利用団体というのは限られていると思うんですね。きっちりと専門的な知識を持った人が入ることが一番だと思うんですけれども、その辺についてのプロポーザルに対するお考えはいかがか尋ねました。","respondent":"富田生涯学習課長","answer":"プロポーザルに当たりまして、音響の専門家を入れることを条件として、そういった防音を徹底することを条件としてやっております。","id":"exchange-038"},{"speaker":"井上委員","kind":"質問・要望","question":"中にはプロとしてアマチュアの方とまじってされている方も多くいらっしゃるということなので、当事者の意見を反映させてほしいと求めました。９時とか、ぜひ当事者の声を聞く場を設けてほしいと思いますけれども、実際にどういうところで声を拾っていこうと考えていらっしゃるんか尋ねました。","respondent":"富田生涯学習課長","answer":"五反田文化センターにも利用者協議会がありますので、そういったところを中心に意見を聞いていく予定にしております。","id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"それから、改修の時期的なものなんですけれども、今実際に文化センターで活動されている方たちが、改修に当たって、行き場所がなくなってしまう。そういった場合に、教育センターのほうが改修がずれたりした場合には、代替えみたいな利用は考えていらっしゃるんか尋ねました。","respondent":"富田生涯学習課長","answer":"工事のスケジュールというのは、これから決まってくるものであろうと思いますが、教育総合会館のほうの工事が始まるまでの間ということでは、ぜひ教育センター部分の活用等を含めて、検討してまいりたいと考えています。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問・要望","question":"そういった基礎部分での改修を絶対にきっちりとやっていただきたいという思いがありますけれども、ただ、大変大きな政策変更だと思うんですね。どういうコスト変化が見込まれてきて、そういう決定をされたのかとか、その辺の比較検討について少しお話を伺いたいと思います。","respondent":"市川庶務課長","answer":"これまで何回か説明していますけれども、この同じ年度に、隣接しております五反田文化センターと教育総合会館の耐震診断を実施いたしました。この結果が出た昨年の秋から、耐震診断の結果への対応と合わせて、改めて平成１９年度予算として計上させていただいた経緯です。","id":"exchange-041"},{"speaker":"本多委員","kind":"質問","question":"平成２０年度に採用選考、平成２１年度から採用ということなんですけれども、人事委員会とのかかわりがどうなるのか。引き続き同じように特別区人事委員会に構成員としているのか、その辺を説明を求めました。","respondent":"河野指導課長","answer":"今、幼稚園教諭に関しましては、特別区人事・厚生事務組合の中で採用選考を実施している経緯がありますが、独自採用教員につきましては、品川区独自ですので、最終的には、人事委員会とも協議はいたしますが、採用そのものは品川区として進めていきたいと考えております。","id":"exchange-042"},{"speaker":"本多委員","kind":"質問・要望","question":"教えていただきたいのと、その辺について、採用する枠の理想像を説明を求めました。","respondent":"河野指導課長","answer":"２次で分けて行っているんですが、採用した後１年間の試験採用期間というのがありますが、毎年自主退職される方が後を絶ちません。そういうようなことをできるだけ予防するために、ある程度経験や実績を積んだ方を私どもとしてはぜひ採用したいと考えているところです。","id":"exchange-043"},{"speaker":"本多委員","kind":"質問","question":"人事に関連してお聞きしたいんですけれども、校長と副校長が同時に移ってしまうことはできればないようにしてもらいたいと思います。校長、副校長が同時に異動というのは避けたほうがいいんじゃないかと思うんですけど、その辺を説明を求めました。","respondent":"河野指導課長","answer":"副校長になるわけですが、同時に異動するということにつきましては、私どももできる限り避ける方向で検討しております。ただ、さまざまな条件がございまして、中にはそのようにいかないケースもありますので、その辺はぜひご了承いただきたいと思います。","id":"exchange-044"},{"speaker":"本多委員","kind":"質問","question":"次の２９５ページのＣＡＰ事業について聞きます。２年生が実施されていたと思うんですが、毎年新しい２年生がやるわけですから、その辺を説明を求めました。","respondent":"河野指導課長","answer":"ＣＡＰですが、今、実施している学年は小学校３年生と５年生です。対象となる子どもは毎年初めての体験ですので、ある程度、現状では一番望ましいと思われるプログラムを継続して実施しているです。","id":"exchange-045"},{"speaker":"本多委員","kind":"質問・要望","question":"工夫をして、さらに進めてほしいと求めました。３０８ページの学校施設建設費ですとか、学校管理費に関連して、学校整備に当たって樹木を整える計画みたいなものを説明を求めました。","respondent":"市川庶務課長","answer":"こういうことでそれぞれ計画をし、実施をしてきてあります。既存校の樹木につきましても、現状の維持ということで、植栽の管理に当たってきてあります。","id":"exchange-046"},{"speaker":"本多委員","kind":"質問","question":"桜のことでお聞きしたいんですけれども、主に９種類ぐらいあるそうなんですけれども、開花が早いです。そういうことも考慮しながら、何か考えができないか、説明を求めました。","respondent":"市川庶務課長","answer":"そういう桜は今後どうなのかということについては、検討します。そういったことも考えあわせて、今、ご指摘のあった点、今後検討させていただければと思います。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いつ、どこで、だれの要望で出てきたのか教えてほしい。現在の平中、二中の体制と統合されたときの体制についても教えてほしいと求めました。","respondent":"古里学務課長、河野指導課長","answer":"荏原西地区一貫校の建設に際して、建設前、周辺の皆さんにご説明を申し上げる機会を持たせていただきました。そうした中で、私どもとしては… 二中と平中の現在の教員体制ですが、二中のほうが現在、通級を除いた人数ですが、５学級に対して、教員定数が９名プラス、少人数加配が現状１名です。","id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"数十年かけて培ってきた学校と地域との社会環境を壊さない範囲内で小中一貫校を実現すべきではないでしょうか」。ということでは、町会で平成２０年度統合というのは、求めていないのではないかと思うんですけれども、改めてこのことについて説明を求めました。","respondent":"古里学務課長","answer":"こうした判断を教育委員会でした上で、この決定をいたしたものです。私どもとしては、荏原西地区全体の中学校の教育環境を考えて、決定をしたものです。","id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"「選択制の中で３年間は保証してほしい。２校存在もあり得ると検討してほしい」との意見を述べました。","respondent":"古里学務課長","answer":"この発表を１年おくらせることによる混乱、私ども、誠心誠意説明をさせていただいたです。あるいはこれからの成長過程にある人間ということを考えて、両校の統合ということを真摯に事務を進めていく、その中で誠心誠意対応するということ。","id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"平成２０年度、荏原二中、平中の統合はやめてほしいという声です。この点で、大半が反対という意思表示になれば、計画変更もあり得るということで考えてもいいか尋ねました。","respondent":"長田教育次長、河野指導課長","answer":"こういったところに関しまして、精力的に説明をやってきた、こういう経過です。したがいまして、私どもは、荏原二中を含めた一貫校の建設につきましては、引き続き進めさせていただきたいと考えています。 その影響に対して、最少限度にとどめるのが私たちの努めです。そういう発言をしています。","id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"このことに対してどう思うのかを改めて問いたいと思うんですが、今の１年生は、二中も平中も一緒にならないということで選んでいるんです。改めて、平成２０年統合はやめるべき、平成２２年３月までは荏原二中、平中を存続させるべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"若林委員","kind":"提案","question":"これまで私も一般質問、また予算特別委員会の場でもさまざまなご提案を含めまして、質問等させていただきました。これまでの体制からどのように拡充をされたのか、そこら辺も含めまして、丁寧なご答弁をお願いしたいと思いますとの意見を述べました。","respondent":"河野指導課長","answer":"平成１６年度より特別支援教育検討委員会を立ち上げて、品川区としての特別支援教育のあり方について、今年度まで検討を進めてきたところです。既に実施している取り組みといたしましては、年間４回ですが、さらに継続したアドバイスというような形で取り組んできております。","id":"exchange-053"},{"speaker":"若林委員","kind":"質問・要望","question":"小学校が８,４００万円余、中学校が２,９００万円余、合計で１億１,４００万円余。この金額がちょっと下がった理由について、検討委員会の中で内容について変化があったのかどうか、ご答弁をお願いいたします。","respondent":"河野指導課長","answer":"専門家チームによる特別支援教育関係で、品目を心障学級経費から特別支援教育費のほうへ一部移行したことに伴う減額でございまして、特別支援全体にかかわる経費としては。","id":"exchange-054"},{"speaker":"若林委員","kind":"質問・要望","question":"今回、特別支援教育経費として２９９ページに載っているのは、１億３,６００万円余です。それと、言葉尻をとらえるようで申しわけないんですが、今のご答弁の「思います」という部分のお答えをお願いしたいと思います。","respondent":"河野指導課長","answer":"私の説明が不十分であったことをおわび申し上げます。そちらのほうが１,９７０万ほど新たに予算措置をさせていただいておりまして、そういう経費を賄う予定です。","id":"exchange-055"},{"speaker":"若林委員","kind":"質問・要望","question":"最後に、今回のプレス発表によりますと、１５ページのほうに、小中一貫教育特別支援教育と、こういうタイトルがついております。私も質問の中では、小中一貫特別支援教育がスタートになりますので、改めてこれの意味を一言お願いいたします。","respondent":"河野指導課長","answer":"特別支援を要する子ども、あるいは特別支援を特に要しない子どもも含めて、このように名称変更をさせていただいたところです。それぞれ就学後の個別的な支援策について直接保護者の方から意見、就学支援シートという新しい取り組みを通して、あるいは伸ばしたいところ。","id":"exchange-056"},{"speaker":"若林委員","kind":"質問","question":"これは１点、プラン２１の中で、学校外部からの講師を呼んで授業を行うことがあります。この講師の方々への謝礼ということなんですが、これは今どういうふうにされておりますか尋ねました。","respondent":"河野指導課長","answer":"それぞれご協力いただいた皆さんには、区の商品券、１回につき３,０００円ずつお礼ということで差し上げております。","id":"exchange-057"},{"speaker":"若林委員","kind":"質問","question":"学校、一人ひとりの子どもたちがつくった詞に対して曲をつけて、世界で１つだけの私の歌という特別授業もされています。謝礼という部分で、力強いご支援を賜りたいと思うんですが、教育委員会のお考えをお聞きしたいと思います。","respondent":"河野指導課長","answer":"今、委員からご指摘のありましたような、特に著名な方ですとか、専門家をお招きする場合には、通常の区の商品券による謝礼とは別に、それぞれの基準に照らしたお礼をお支払いできるように予算措置をして、それぞれの学校が取り組んでいるところです。","id":"exchange-058"},{"speaker":"若林委員","kind":"意見","question":"既に平成１９年度の予算が決まっていて、それが各学校に配分をされて、その中で学校が工夫するという理解でいいんですね。もし学校からの要請があれば、柔軟な対応がお願いできるかどうか、一言お願いいたしますとの意見を述べました。","respondent":"河野指導課長","answer":"学校からの要望に応じて、私どものほうもできる限り柔軟に対応してまいりたいと考えています。","id":"exchange-059"},{"speaker":"原（浩）委員","kind":"確認","question":"３１１ページ、および３２１ページ、そこをもう少しお伺いしていきたいと思います。初めのほうに関しては、私、一般質問でもしたんですけれども、複合化ということなんですけれども、もう１回確認させてください。","respondent":"市川庶務課長","answer":"これらの敷地の上に１つの建物を建てることによって、さまざまな建築規制に対して、効率的な床の確保ができる。こういった意味での複合化です。","id":"exchange-060"},{"speaker":"原（浩）委員","kind":"質問・要望","question":"隣が図書館ということなものですから、特別な講演会ができないのかなと、その辺も考えていただきたいです。時間がないものですから、ですから、まず所管のほうのご意見をほしいと求めました。","respondent":"富田生涯学習課長、市川庶務課長","answer":"それと同時に、学校施設の地域開放というのも進めていかなければなりませんので、この辺の動線に配慮した設計にしてまいりたいと考えています。いずれも５割ということで、学校との活用ができないか等を含めて… ただ、今の選択肢の中で、私どもが考えている中で、既存の旧の日野中のプールの活用ができないかどうか。","id":"exchange-061"},{"speaker":"原（浩）委員","kind":"質問","question":"ですから、もう１回耐震構造の関係で、その辺のところをひとつよろしくお願い申し上げます。もう１回くどいようなんですけれども、どのような運営等をお考えか、もう一度、答えるよう求めました。","respondent":"富田生涯学習課長","answer":"五反田文化センターの運営方法ですけれども、文化センター、既に受付等、委託をしています。運営方法については、今後、新設設計と同時並行で検討を進めてまいりたいと思っているところです。","id":"exchange-062"},{"speaker":"原（浩）委員","kind":"意見","question":"一番初めに申し上げたように、立地条件があまりいい場所ではないので、その辺のところを含めまして、今後もまたいろいろと、集客という意味合いも、あと地域の活性化という意味合いも含めまして、よろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"須貝委員","kind":"質問・要望","question":"地域の要望もあり、事前に、近隣町会の町会長には残念ながら話していなかったと。その３点について確認をさせてください。","respondent":"古里学務課長","answer":"先ほどもご説明申し上げましたけれども、具体的に町会長の皆さんにこの件でご相談を申し上げたという経過はございません。さまざまなことを検討していく中で、そういう点で、生徒にも話していなかったということは事実です。","id":"exchange-064"},{"speaker":"須貝委員","kind":"質問","question":"品川区で、昨年いじめ調査のアンケート調査もやったわけですから、そういう実態も踏まえていると思うんですね。そこまで強引というのか、性急にやることもないんじゃないかと思うんですが、その辺のご見解を説明を求めました。","respondent":"古里学務課長","answer":"平成２２年４月に一貫校が立ち上がるというスケジュールの中で、こうしたことを考えながら、今回の決定をさせていただいている。選択時期の最終時期ですから、そこには遅くとも出させていただきたいということで、ご提案申し上げているです。","id":"exchange-065"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区の公立中学校が年度の途中でバレーボールをやるために９人の生徒を受け入れたということはどうかと思うんですが、これは、今。人間形成を培う意味で大事な、こういうクラブ活動にもっと目を向けてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"各学校で異なる実際の教育の進め方などなど、何回も紹介されましたけれども、平成２０年の統合をぜひおくらせてほしい。なぜ延期ができないのか、その辺をきっちりとお答えをほしいと求めました。","respondent":"古里学務課長","answer":"先ほど来るる説明をいたしております。私どもも、平成２０年、平成２１年、平成２２年、それぞれに検討いたしました。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問","question":"子どもたちの責任を負っているのは、親であり、また、本人にも意向がしっかりあるじゃないですか。その辺を踏まえて、望ましいと一方的におっしゃる理由をもう１回聞きます。","respondent":"古里学務課長","answer":"平成２２年の４月ですけれども、平成２２年４月は小中一貫校が、文字どおり一体となって立ち上がらなければならない大変な時期です。これが私どもの考え方です。","id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問","question":"私は平成２２年４月をおくらせればいいと思います。地域で今反対が起こっていますが、地域の了解を得られない場合は、考えを直せるのかどうか、その辺を最後にお伺いします。","respondent":"古里学務課長","answer":"現在のところ、在校生の保護者の方までしか説明ができておりません。これからるる説明をしていくという過程ですので、今の段階でそのようなことは判断できないと思います。","id":"exchange-069"},{"speaker":"川西委員","kind":"質問","question":"３０１ページになるんでしょうか、３０３ページに関係があるかと思いますが、特色ある教育活動の中の小規模校についての配慮について伺います。保育園の保護者、子どもが来たときの、そこの施設への連絡体制などを伺います。","respondent":"河野指導課長","answer":"毎月１回相互に情報交換会を持ちまして、それぞれの取り組みについて、日常的に連携をしながら進めているところです。継続的なカウンセリングを必要とする場合には、スクールカウンセラーを通して、教育相談センター等につなぐという形で連携しています。","id":"exchange-070"},{"speaker":"川西委員","kind":"質問・要望","question":"要望については後ほどにいたします。４７人の職員と、今の現況の体制について、１つの学校の中におけるすまいるスクールの統括責任者というのはどういう体制になっておりますか。","respondent":"市川庶務課長","answer":"この４７人のうちの４０人は、小学校４０校に各１名ずつ常勤の指導員として配置している職員ですけれども、その者が当該校の事業の責任者ということで位置づけてあります。","id":"exchange-071"},{"speaker":"川西委員","kind":"質問","question":"心配事があるような雰囲気を持つ子どももいたりというのは、どなたがどういうふうに把握して、だれに相談をしているのかということを伺います。６時以降の体制で、すまいるスクールで相談を受けたことはありますか。","respondent":"市川庶務課長","answer":"常勤の指導員の不在の場合の対応ですけれども、その職員を１名ないし２名、配置しています。その上で、その状況に応じて、担任の教諭、あるいは保護者、そういうような状況に応じた対応をとるようにしています。","id":"exchange-072"},{"speaker":"川西委員","kind":"質問","question":"８３運動、３１７ページの関連でしょうか。これを先に伺います。","respondent":"市川庶務課長","answer":"監視員が巡視をして、子どもの安全確保に当たろうということで、平成１８年度から新たに加えた事業です。交通安全指導と通学路の巡視、この２つで通学安全監視という事業を構成しています。","id":"exchange-073"},{"speaker":"川西委員","kind":"質問・要望","question":"どうしても対外的には、口から口へ伝わることなんでしょうか、いいように思っている保護者の方もいます。特色ある教育活動がそれの１つなんでしょうか、そういうものを区としてもＰＲをしてほしいと思いますが、伺います。","respondent":"吉村小中一貫教育担当課長","answer":"今委員がおっしゃったように、小規模校のよさについては、教育委員会も十分に認識しております。こういったことを年間を通して、学校と指導しています。","id":"exchange-074"},{"speaker":"川西委員","kind":"質問","question":"ですから、それはそれとして評価いたしますが、学校公開というのは本当に効果があったなと考えています。平成１８年度の人数と、１園何人ぐらい預かれるのかということと、いかがか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"その中で、昨年度９月から実施しましたところは、総数はありませんけれども、平均でよろしいでしょうか。平均では、４園につきましては、１日３人から４人、１月実施につきましては、今のところ、１人とか２人という状況です。","id":"exchange-075"},{"speaker":"大沢委員","kind":"確認","question":"大体１０個の研修があると。ほかには研修がないということか、確認をさせてください。","respondent":"河野指導課長","answer":"研修は、今委員ご指摘のほかにもまださまざまな研修があります。","id":"exchange-076"},{"speaker":"大沢委員","kind":"質問","question":"さまざまな研修、そうすると、大体どれぐらいの研修が行われているのか、数がおわかりになれば、説明を求めました。","respondent":"河野指導課長","answer":"ざっと十五、六の研修項目があります。１回で行う研修もあれば、数回に分けて実施する研修もあります。","id":"exchange-077"},{"speaker":"大沢委員","kind":"質問","question":"そして継続的にやる研修ということで今伺いましたけれども、継続的か単発的かということで伺っただけで、年間トータルするとどれぐらいの日数になるのかというのは伺っていませんけれども。","respondent":"河野指導課長","answer":"初任者に関する研修につきましては、月に２回ないしは３回程度、どうしても研修に出なければならないという実態があります。あるいは時間講師等を配当して、子どもたちの授業に影響が出ないように配慮して、研修に参加させているところです。","id":"exchange-078"},{"speaker":"大沢委員","kind":"質問・要望","question":"先生方、いろいろな研修を受ける上で、授業時間のコマをいろいろと工夫をされなければいけない部分もあるんじゃないかと思います。中には、自習になったり、短縮になったりするような状況も見受けられるんですが、そこのところ、確認をさせてほしいと求めました。","respondent":"河野指導課長","answer":"その研修に出る教務主任、あるいは生活指導主任については、その時間帯は授業を入れないように通常から時間割を組んでいるのが原則です。なお、このような研修については、開始の時間を午後３時ということで、子どもたちの授業に支障がないように配慮しています。","id":"exchange-079"},{"speaker":"大沢委員","kind":"質問・要望","question":"昭和３４年でしょうか、昔の農業生活には欠かせない、重要な生活のかなめの用水であったわけです。１冊だけでクローズアップされているように思われますけれども、どこら辺ぐらいまでとらえていらっしゃるでしょうか、答えるよう求めました。","respondent":"富田生涯学習課長","answer":"そういった冊子を出すのも１つでありますし、知らせ、伝えていきたいと考えております。","id":"exchange-080"},{"speaker":"大沢委員","kind":"質問","question":"それに関して、ポイントというか、それを表示するような工夫は何かないのだろうか。こっちの蛇窪の２つに分かれていくわけですけれども、考えてはいらっしゃらないでしょうけど、何かアイデアはお持ちか尋ねました。","respondent":"富田生涯学習課長","answer":"品川用水の橋等につきましては、品川の史跡めぐりの付図の中の一覧として残しています。それをまちのサインの１つとして表示するということにつきましては、今後検討課題とさせていただきたいと思います。","id":"exchange-081"},{"speaker":"大沢委員","kind":"質問・要望","question":"荏原一中、そういう意味では文教のまちの１つでもありますし、まさに通学路にかつての用水が通っていた部分もあります。そこのところをぜひとも啓発運動をしてほしいと求めましたし、検討していただけるに値するのであれば、お願いをして終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"山路委員","kind":"質問","question":"３点目が、３１１ページ、品川地区一貫校基本設計委託等についてお伺いいたします。平成１９年度は７名増加して、この数字から今後の展開についてはどういうふうに考えていらっしゃるか、お伺いいたします。","respondent":"河野指導課長","answer":"特別支援教育に絡んで、支援を要する子どもたちに対する配慮について、助言をしてもらう。あわせて、そういう該当する子どもたちの個別指導計画を立てるに当たって、専門家の立場から指導、助言をいただくということを想定しています。","id":"exchange-083"},{"speaker":"山路委員","kind":"質問・要望","question":"やっぱりこういう問題が多いのでしょうか。ほとんど言えないと思いますが、データがあったら、言える範囲で何点か教えてほしいと求めました。","respondent":"河野指導課長","answer":"これが現状ではスクールカウンセラーのところに一番多く寄せられております。教員からスクールカウンセラーへの相談については、不登校問題、あるいは発達障害に関する助言を求めるというケースが圧倒的に多数を占めております。","id":"exchange-084"},{"speaker":"山路委員","kind":"質問","question":"あるいはその関係、先生たちの相談だと思いますので、慎重にくれぐれもよろしくお願いいたします。しっかりやられていると思うんですが、現在はどういう情報教育の徹底をやられているか、お伺いいたします。","respondent":"吉村小中一貫教育担当課長","answer":"７年生にいくと、１年から系統的にそういったものを学習するように、条件整備しています。","id":"exchange-085"},{"speaker":"山路委員","kind":"確認","question":"大体昨年と同じような答えだと思うんですけれども、分野がどんどん広がってきましたよね。この辺に関しましては、年代に応じて共通の情報教育が行われているのかどうか、確認をしたいと思います。","respondent":"吉村小中一貫教育担当課長","answer":"１年から９年まで設けるということも実は考えたんですけれども、２年生の場合には、まだその辺の理解はかなり難しい。そういったプログラムにして、今、実施しています。","id":"exchange-086"},{"speaker":"山路委員","kind":"質問","question":"３１１ページの品川地区一貫校基本設計委託等として計上してありますが、その「等」というのは、どういう意味をなすのか。これから設計されて、平成２３年ですか、その推移についてお伺いします。","respondent":"市川庶務課長","answer":"ここにあります「等」の中身ですけれども、基本設計に伴いまして、例えば地中調査等が必要な場合、こういったことで関連経費、基本設計をするに当たっての関連経費ということで「等」という言葉を使わせていただいてあります。","id":"exchange-087"},{"speaker":"沢田委員","kind":"質問・要望","question":"私も、先ほどから議論があります、荏原二中の荏原西地区の統廃合の問題について質問させてほしいと求めました。２月９日から説明に入っていったというんですが、一体この方針を品川区教委として決定したのはいつの段階なのか、もう一度聞かせてほしいのですが。","respondent":"古里学務課長","answer":"２月９日に説明をいたしました。この両校の今後のあり方を多方面から検討した中で、そのような内容で予算編成をしたということ、この説明をさせていただいているところです。","id":"exchange-088"},{"speaker":"沢田委員","kind":"意見","question":"私が聞いているのは、その方針を、いつ、どういう期間で決定をしたのか。予算編成の中で決定したというのはわかったんですが、どこで決めたのかと聞いているんですとの意見を述べました。","respondent":"古里学務課長","answer":"決定のプロセスですけれども、平成１８年の１１月の教育委員会の中で予算要求の概要ということでご説明をし、ご審議をいただいてあります。","id":"exchange-089"},{"speaker":"沢田委員","kind":"質問","question":"教育委員会として決定したんですか。要するに、教育委員会で、これを議案として提出して、決定したのはいつですかと私は聞いているんです。","respondent":"古里学務課長","answer":"１１月の教育委員会には議案として提出していますから、当然議案として教育委員会として決定したものと考えています。","id":"exchange-090"},{"speaker":"沢田委員","kind":"質問","question":"これは一体どういうことなんでしょうか。そこを飛び離れて、どんどん教育委員会事務局が進めているのではないかと思うんですが、いかがか尋ねました。","respondent":"古里学務課長","answer":"文教委員会のときにもご説明申し上げましたけれども、平塚小の場所にでき上がる荏原西地区一貫校についての建設準備会での地域での説明についても。","id":"exchange-091"},{"speaker":"沢田委員","kind":"質問","question":"いかがでしょうか」とやらなかったんですか。手順が全然違うじゃないか尋ねました。","respondent":"古里学務課長、市川庶務課長","answer":"１点目のご質問の内容ですけれども、手順ですけれども、２月９日のプレス発表時にこれをあえてつけ加えなかったです。そうしたことも含めて、あえてこの中でそのことは触れなかったです。 ６校構想の決定に関しては、平成１８年度の予算査定の中で最終的に決められたです。","id":"exchange-092"},{"speaker":"沢田委員","kind":"質問","question":"それからもう一つ、小中一貫校を６校構想に新たに展開するときに、予算査定の中で決めたと言うけど、教育委員会ではいつ決めたんでしょうか。その点、お答え願いたいと思います。","respondent":"市川庶務課長","answer":"ご質問の順番は前後いたしますけれども、６校構想にしても、荏原西地区の取り扱いにしても、最終的には学校設置者としての判断が伴います。荏原西地区の一貫校についての計画説明の場ですけれども、それぞれ１回ずつ、計３回説明会を実施してきてあります。","id":"exchange-093"},{"speaker":"沢田委員","kind":"質問・要望","question":"その点をもう一度お答え願いたいと思うんですが、去年私どもで、小中一貫校６校構想を決めたファイルを提出してほしいと情報公開を求めました。いかがか尋ねました。","respondent":"古里学務課長","answer":"再三同じ回答で申しわけございませんけれども、平成１９年度予算の編成をする過程で、昨年１１月に教育委員会で議案として審議をいただいてあります。教育委員会の中でそのようなことをきちっと論議をして、この議案を決定している、こういう手順は踏んでいるものと考えています。","id":"exchange-094"},{"speaker":"沢田委員","kind":"質問・要望","question":"教育委員会は、子どもたちに地方自治、住民参加をどう教えるんですか。こういうスタンスで言ってきましたけれども、今後これは変わらないか尋ねました。","respondent":"古里学務課長","answer":"学校選択制にかかわって、区が過去申し上げてきたことは、委員がおっしゃるとおりです。このことについては何ら変わらないと考えています。","id":"exchange-095"},{"speaker":"沢田委員","kind":"質問","question":"３年生まで、先ほど課長からもありましたから、そこは調整をしていく。せめてこの立場で貫いてほしいと思いますけれども、いかがか尋ねました。","respondent":"長田教育次長","answer":"それから、説明会の中では、ぜひ進めていただきたいという意見が出ているのも確かです。こういった説明の中で、進めているところですので、そういった方向で今後も進んでいきます。","id":"exchange-096"},{"speaker":"沢田委員","kind":"質問・要望","question":"仮校舎やいろんな問題を考えてというのなら、なぜそれを決めた去年の１１月から説明しなかったんでしょうか。改めて私は、みんなの意見を聞いて考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"伊藤委員","kind":"質問・要望","question":"３１９ページ、２９９ページの校務システム開発等経費について、関連して質問いたします。確認したいのが、こういう健康管理の中から、いじめの発見につながる仕組みを構築しているかどうかということをまず確認ください。","respondent":"古里学務課長","answer":"学校ごとに設置をされますけれども、学校ごとの設置の中で、今年度立ち上げました。来年度以降、保健委員会の活動の充実ということについて話し合うということを予定していますので、その中で検討させていただきたいと思います。","id":"exchange-098"},{"speaker":"伊藤委員","kind":"確認","question":"今、少し答弁がありましたけれども、もう少し先をにらんだ対処の中で、毎年何千人の子どもたちを診察しているわけじゃないですか。その中で、広い意味でいじめ撲滅につながっていくと思われますので、そのことについての再度の確認答弁をお願いいたします。","respondent":"古里学務課長","answer":"そういう意味では、子どもの健康に関する総合的な情報が集まる場所だと考えています。その上で、委員がおっしゃった、その他の情報、それから児童課との連携、教育委員会との連携等々もその中で検討させていただきたいと思います。","id":"exchange-099"},{"speaker":"伊藤委員","kind":"質問","question":"次に、家庭教育支援ネットワーク講習について質問します。このネットワーク講習が１つの事業としてできたと思われますが、対象者、どこで行われるかということについて説明を求めました。","respondent":"富田生涯学習課長","answer":"いわゆるニートですとか、ひきこもりと言われる青少年本人と、またそういったことに悩みを抱える保護者対象の講座を新たに今年度行いました。文化センターですとか、児童センター、中小企業センター等々で実施しています。","id":"exchange-100"},{"speaker":"伊藤委員","kind":"確認","question":"ですから、確認したいのが、今回親育て施策を打ち出しました。妊娠から中学校卒業までの間はある程度一貫して、品川区は親育ちにかかわる施策を構築していくべきと思うんですが、いかがか尋ねました。","respondent":"富田生涯学習課長","answer":"そういった仕掛けにもなってまいりますので、それをいかに有効な内容にしていくかということについても、努めてまいりたいと思っています。学校等、保護者の集まりでありますＰＴＡともうまく連携しながら、そういった問題を抱えた方々の問題も進めてまいりたいと思っています。","id":"exchange-101"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ただ、１点だけお願いしたいのは、学校単位で将来は開いていっていただきたいということをお願いだけしておきます。それから、親育ち施策というふうに堂々とうたっていますけれども、これはとてもテーマが広いじゃないか尋ねました。","respondent":"日下部企画財政課長","answer":"非常に難しいご質問です。いろいろ施策の取り組み分野が広がってまいりますので、１つの段階を追った親育ちへの対応がしっかりできるようにしてまいりたいと考えております。","id":"exchange-102"},{"speaker":"三村委員","kind":"質問・要望","question":"５月からワーキングマザーという生活に戻りますけれども、子どもたちの放課後の居場所についてお聞きしたいと思います。そういったことを考えますと、ご両親が共働きの家庭の子どもたちが利用した場合の課題やその対策についてお考えをお聞かせほしいと求めました。","respondent":"市川庶務課長","answer":"現在６時まで利用時間を設定しております考え方は、１人で親の帰りを家で待てる、そういうように成長してほしいという基本的な考え方があります。なるべく早い時期から、早い時期からそういうことを保護者に理解を求めていく、そういうことが必要であると考えています。","id":"exchange-103"},{"speaker":"三村委員","kind":"質問","question":"実際は、子どもをねらった犯罪や何かがいろいろある中で、子ども１人を家に置いておくというのが実際には難しい。決算特別委員会のほうでもそういった質問をさせていただきましたけれども、その後どういうふうな検討をされたのか、お伺いしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"今お尋ねの件ですけれども、すまいるスクールの考え方については、今、庶務課長から答弁申し上げたとおりです。平成１９年度、児童センター等を中心に進めておりますので、ご相談に応じながら対応していきたいと考えているところです。","id":"exchange-104"},{"speaker":"三村委員","kind":"質問・要望","question":"ぜひ来てほしいという声もありましたけれども、それ以外にも区としてもぜひこういったところの支援、充実をお願いしたいと思います。そういった要望をしてこなかったんですけれども、すまいるスクールで提供してほしいという保護者の声も聞きますので、いかがか尋ねました。","respondent":"市川庶務課長","answer":"ただ、事情のある子どもは、特に保護者の方からの相談があって、その子が補食をとらざるを得ないときには、必要な対応を既に現場でもとってあります。そういった個々の子どもの事情に応じた対応ということは、今後ともとってまいりたいと思ってあります。","id":"exchange-105"},{"speaker":"堺委員","kind":"質問","question":"療育支援体制の整備と小中一貫教育特別支援教育というタイトルの中の３番目でしょうか、それ以降に、教育の場の拡充に努めると。利用者にとって使い勝手のいい改修をぜひお願いしておきたいと思うのですが、その中身、内容についてお知らせいただけますか尋ねました。","respondent":"河野指導課長","answer":"これからは、できるだけ個々の子どもたちへの対応というのが中心になってまいりますので、個別対応できるような部屋につくりかえるというものです。","id":"exchange-106"},{"speaker":"堺委員","kind":"質問・要望","question":"教育長にも直接会って要望させていただいた経緯がございましたので、この件について確認させていただきました。今現在、特に少年野球、少年サッカーのチーム数とか人数は把握されておりますか。","respondent":"富田生涯学習課長","answer":"１,５００人強の選手の方がいらっしゃるということでありまして、小学生３３チーム、１,３００人強と聞いております。","id":"exchange-107"},{"speaker":"堺委員","kind":"意見","question":"こういう中でも、先ほどご答弁いただきましたように、野球についても、５８チームで１,５００人、サッカーについても、３３チームで１,３００人。お尋ねをしておきたいのは、どこでどういうふうにやっているか、お知らせいただけますかとの意見を述べました。","respondent":"富田生涯学習課長","answer":"少年サッカーにつきましては、主にそれぞれの小学校のグラウンド、校庭で放課後等に練習をしている。あるいは土曜、日曜も少年野球と調整しながら使っているチームもあると聞いております。","id":"exchange-108"},{"speaker":"堺委員","kind":"質問","question":"しながわ中央公園１カ所、ここは多目的ですから、野球やサッカー等もできるんでしょうか。ある学校の監督をやっている人からそんな話があったんですが、そういう現状は把握されておりますか。","respondent":"富田生涯学習課長","answer":"そのような学校もあると聞いております。","id":"exchange-109"},{"speaker":"堺委員","kind":"意見","question":"にもかかわらず、サッカーチームの人が使えるような、例えば少年サッカー場とか、そういう明確に冠がついた場所がない。関係者の人たちから、そういうところがないので、何とかしてほしいという要請があったんですが、そういう声は届いていますかとの意見を述べました。","respondent":"富田生涯学習課長","answer":"サッカーにつきましては、学校の関係者が育成に当たることが歴史的に比較的多かったということで、学校施設を多用しているものと思います。あるいはケーブルテレビ杯ですとか、そういった大会でもって開催が増えてきておりますので、そういったときにはご活用いただいております。","id":"exchange-110"},{"speaker":"堺委員","kind":"質問・要望","question":"少年サッカー場というのは明確に冠をつけたところがないので、できれば、今後いろんな形で、例えば小中一貫校の施設であくところが出ますね。冠をつけても使えるような場所を、ぜひ創意工夫しながら設置をしていただきたいと思うんですが、もう１回ご見解をお伺いできますか。","respondent":"富田生涯学習課長","answer":"サッカー人口が大変増えてきているという状況等を踏まえ、今後の課題ということで受けとめさせていただきたいと思います。","id":"exchange-111"},{"speaker":"堺委員","kind":"質問","question":"ぜひひとつご検討をお願いしておきたいと思います。３点目に、どこをどう改修されるのか、教えていただけますか。","respondent":"富田生涯学習課長、宍戸施設担当課長","answer":"約３億円ほど予算計上していますが、改築から２０年ほどたちまして、照明の取りかえ等々です。 アスベスト除去も当然入ってあります。","id":"exchange-112"},{"speaker":"堺委員","kind":"意見","question":"それから、あそこの現況なんですが、駐輪場と駐車場、たしかあそこは駐車場はないですよね。どのような認識を持っておられますかとの意見を述べました。","respondent":"富田生涯学習課長","answer":"戸越体育館の駐車場は２台分ございまして、１台は障害者用ということで、ご案内をさせていただいておりました。駐輪スペースについては、４０台程度分ということで確保しております。","id":"exchange-113"},{"speaker":"堺委員","kind":"質問","question":"駐輪場も４０台あるとはおっしゃっていますけれども、あの辺も、かなり駐輪場も大変な状況になっている。全体的に戸越体育館利用者のための利便性向上のための創意工夫もお願いをしておきたいと思うんですが、その辺はいかがか尋ねました。","respondent":"日下部企画財政課長","answer":"土木費でも出てまいりましたけれども、資料館の跡地を取得する。戸越公園との一体的な整備ということで検討を平成１９年度する予定になっておりますので、今のご指摘の点は。","id":"exchange-114"},{"speaker":"松澤委員","kind":"質問・要望","question":"この３校がどこにいっちゃったのか、どうなっているのかを聞きたいと思います。３月３１日で退職されますけれども、その学校に残って校長をやるんだといううわさを聞いたのですが、それの真偽をお聞かせほしいと求めました。","respondent":"河野指導課長、古里学務課長、日下部企画財政課長","answer":"平成１９年度から、東京都の教育委員会で実施いたしますが、あるいは副校長の任にあるという人数が大変多うあります。… 議案説明会の資料の２９ページ、確かに１０校から２３校と書いてあります。実は１０校は、昨年度の実施校数が１０校でございまして… 学務課長からご説明させていただきましたが、議案説明会の資料のほうは、その関係で２３校という表記になっております。","id":"exchange-115"},{"speaker":"松澤委員","kind":"質問・要望","question":"あるいは、これがまた数が将来増えていくのかどうかについてお伺いをしていきたいと思います。プラン２１が行われる中でというのは、不登校というのはなくなっているのかどうか、最近の傾向と対策をお伺いしたいと思います。","respondent":"河野指導課長、古里学務課長、長田教育次長","answer":"心の悩みに対応するのか、特別支援に対応するのかですが、発達障害に起因しているのではないかと思われるケースも相当数あります。… 来年度の調理代行にかかわる契約の方法ですが、簡易型総合評価方式の試行という形で今年度やらせていただきました。これは、価格面、業務の提案面… だれがというのは、先ほど指導課長が申し上げたとおり、人事案件ですので、まだ内示の状況ですから、発表できる状況にはないです。","id":"exchange-116"},{"speaker":"松澤委員","kind":"質問・要望","question":"どうするかという問題なんですけれども、できるだけ地場産業の育成ということで、区内にある業者にも開放すべきだ。すべてとは言いませんけど、そう思っておりますので、その辺の考えをお聞かせほしいと求めました。","respondent":"本間助役","answer":"そういう業者が少しでも多い中で選定できる状況が好ましいわけですから、どのような形で取り入れるか、今後検討させていただきたいと考えています。","id":"exchange-117"},{"speaker":"西本委員","kind":"質問","question":"２９７ページのプラン２１関連で、２９３ページの学校適正規模検討経費について、それぞれお聞きします。その中で、カウンセリングを個々の学校でするときの部屋の確保はどうなっているのかをお聞きしたいと思います。","respondent":"河野指導課長","answer":"スクールカウンセラーがそれぞれの子どもと面談をするための部屋については、まだ１００％とは言えない状況があります。これから年次を追って整備していくということで、今、予定を立てているところです。","id":"exchange-118"},{"speaker":"西本委員","kind":"質問・要望","question":"ソファ等々、備品等についてもきちっと設置をしていただきたいと考えています。地域の方にお願いしたりということで、いろいろ確保されていると思うんですが、各学校によっての状況はどのような形になっているんか尋ねました。","respondent":"市川庶務課長","answer":"４０校の実情から申し上げますと、かなり盛んなところもあれば、そうでないところもあるというのが実情です。","id":"exchange-119"},{"speaker":"西本委員","kind":"質問","question":"指導員の方たちが非常にご苦労されて、お願いをしながら、ボランティア等々を探しているという現状だとお聞きしています。派遣していただくとか、そういう共同作業ができるのではないかなと思いますが、そういう考えはいかがか尋ねました。","respondent":"市川庶務課長","answer":"ご指摘の点は、確かに実務上、私どもも高い関心を持ってあります。今後そういう方の人材確保というか、私どもの事業の充実に向けてご協力をいただける、そういったことについて検討していきたいと考えております。","id":"exchange-120"},{"speaker":"西本委員","kind":"質問・要望","question":"次に、教育振興費ですが、これはここに入るのかどうか、間違っていたらすみません。その方たちに対して何か区として手立てができないものかなと思いますが、いかがか尋ねました。","respondent":"古里学務課長","answer":"現在、入学支度金については、小学校１年生、中学校１年生、私どもで言えば７年生、この進学時にそれぞれ入学支度金をお渡ししています。就学援助は、国の基準等々で決まっておる内容ですので、現在の段階でそうした個別の学校の事情に応じた支給は大変難しいかと考えています。","id":"exchange-121"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜ日野学園、伊藤学園が標準服を採用したかということは、どういう一貫校にしていくか。教育上よいとは思いませんので、品川区として何かの手立ては今後考えてほしいと求めましたが、いかがか尋ねました。","respondent":"古里学務課長","answer":"就学援助という枠組みで考えれば、これは法律で決まっている形です。この制度の中での検討は非常に難しいということ、繰り返しですが、そのような言い方をするしかないかなと思ってあります。","id":"exchange-122"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、強く要望をさせていただきたいと思っています。他の自治体のところで、兄弟枠をとっていたけれども、それをやめたというところはあるのかどうかをお聞きしたいと思います。","respondent":"古里学務課長","answer":"検討を進めてまいったわけですけれども、制度設計上、品川区は当初から兄弟枠を設けないということでスタートしてきております。安易に、兄弟がいるからということで優先するということは、特色ある学校づくりそのものの努力もひとつ考えてもらいたいというご意見もございました。","id":"exchange-123"},{"speaker":"西本委員","kind":"質問","question":"そのリスクの中で保護者が判断するべき内容だろうと思っています。原点に立ち返ってお聞きしたいと思います。","respondent":"古里学務課長","answer":"学校選択制の動機については、毎年私ども、類型化していますけれども、アンケートをとっております。あるいは、学校の指導方法の評価、こうしたものから学校を選択しているということだろうと類推できるかなと考えています。","id":"exchange-124"},{"speaker":"西本委員","kind":"質問・要望","question":"そのための１つの方法。隣の子も、自分の子も大切にしていくという形の１つとして、学校選択の考え方についての今後の考え方を教えてほしいと求めました。","respondent":"吉村小中一貫教育担当課長","answer":"それをねらった方策の１つというとらえ方です。今まである程度の成果を上げてきておりますので、これを継続して、さらなる学校教育の質を高めるために努力していきたいと考えております。","id":"exchange-125"},{"speaker":"西本委員","kind":"質問・要望","question":"平成２２年度に６校構想はスタートしているわけですから、そうすると、隣の中学校の親たちが「どうぞ」と何で言ってあげられないのかなと思いました。それだったら、どうぞうちの学校に来てください、その考え方についてはいかがか尋ねました。","respondent":"古里学務課長","answer":"今回伊藤学園、伊藤中学校の子どもたちが仮設の校舎から本校舎へ戻ったときに、「仮校舎ありがとう」と黒板にたくさん書いてくれました。そういうこともありますけれども、それよりもっといい環境があるのであれば、それを出すべきだと思ってあります。","id":"exchange-126"},{"speaker":"木下委員","kind":"質問・要望","question":"おわかりになるんだったら、教えてほしいと求めました。今後子どもたちに対する取り組みとして考えていること等ございましたら、お伺いしたいと思います。","respondent":"河野指導課長","answer":"先日、日本の子どもの学習に対する意欲が低くなっているということについては、文部科学省が行っております教育課程の実施状況調査でありますとか。区として調査しているわけではございませんので、またさまざまな調査結果を分析しながら、検討してまいりたいと考えます。","id":"exchange-127"},{"speaker":"木下委員","kind":"質問","question":"この間の新聞発表で気になったものですから、質問させていただきました。ちゃんとした教育というか、訓練を受けてこなかったんじゃないかなと思っているんですが、そこら辺の認識としてはいかがなものか尋ねました。","respondent":"河野指導課長","answer":"そういう障害があるということをお互いに認識した上で、ともに支え合っていける、そういう子ども同士の人間関係を築いていく。このあたりがこれから品川区で展開する特別支援教育の大切な部分であると考えているところです。","id":"exchange-128"},{"speaker":"木下委員","kind":"質問","question":"その子にとっては二次災害みたいなものでしょうから、これからもう一歩踏み込んだ形での、この考えについていかがでしょうか。ご認識をお聞かせ願えればありがたいんですけど。","respondent":"河野指導課長","answer":"できるだけ早く関係機関等とも連携をとりながら、二次障害を起こさないように、非行等に走らないように適切な支援をしてまいりたいと考えております。","id":"exchange-129"},{"speaker":"木下委員","kind":"質問・要望","question":"監修してもらったりなんかしているわけですから、これは私の要望ということで、よろしくお願いしたいと思います。それから、実際に文部科学省の標準に達している学校の割合は、小学校、中学校でどのぐらいなのか、そこら辺を教えていただけますか尋ねました。","respondent":"工藤品川図書館長","answer":"小学校で、標準というふうに考えてみますと、８５.５％ということになってあります。そういった中で、基準に達しない部分を公共図書館と学校図書館との蔵書の連携等で今、補っているところです。","id":"exchange-130"},{"speaker":"木下委員","kind":"質問","question":"文部科学省、１,０００億円増額ということなんですが、品川には大体どのぐらいが来る予定なんでしょうか。そこら辺、どのようにお考えになっていらっしゃるのか、お聞かせ願えますか尋ねました。","respondent":"工藤品川図書館長","answer":"展開していますので、学校図書館整備をやっている学校に関しましては、小学校で５５万円を３年から５年間で増配でつけておる。中学校に関しましては、７５万円を数年間で補強といいますか、余分につけている状況です。","id":"exchange-131"},{"speaker":"木下委員","kind":"質問","question":"国の定めた基準でしょうから、蔵書がいっぱいあったほうが子どもたちも選べるでしょうから、それに向けてひとつよろしくお願いいたしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"石田委員","kind":"質問・要望","question":"ボランティアの方々は、だれにお願いをして、だれがやっているのかというのも教えていただきたいと考えています。平均的でもいいんですが、保護者の出席率がわかれば、教えてほしいと求めました。","respondent":"吉村小中一貫教育担当課長、河野指導課長","answer":"そういう子どもにとって経済用語が出てくる学習は非常に難しいので、この辺の改善を何とかできないかというような意見は出ております。２点目の、アメリカのまま実施することはできませんので… 特に２年生、３年生の４月の保護者会というのは、極端に出席率が下がります。そういうことを平均してみますと、これは推測で申しわけございませんが、平均すると、大体５割から６割ぐらいの出席が現状ではないかなと思います。","id":"exchange-133"},{"speaker":"石田委員","kind":"質問","question":"保護者会では会えないわけですから、逆に教育委員会として、こういうことをしろと。こういう指示を出して、必ずやれとか、必ずそういう親には会える機会ができるわけじゃないか尋ねました。","respondent":"吉村小中一貫教育担当課長、河野指導課長","answer":"今日の生徒は１００人を超えているので、こういった配慮をお願いしますということで、対応しているというのが実態です。これは、今後の全体のプログラムの中で改善すべき点の１つの課題としてとらえさせていただきたいと考えています。子どもと面談するだけではなくて、親御さんに学校に来ていただいて、面談の機会を設けるということを積極的に取り入れてやっている実態があります。","id":"exchange-134"},{"speaker":"石田委員","kind":"質問・要望","question":"８０人から１００人だったら、２回に分けてやるとか、そういうことをやっていただきたいなと。それはお願いだけしておきます。","respondent":"河野指導課長","answer":"当該校の担任、あるいは管理職とその子どもの対応について協議をして、具体的に取り組んでおります。その中で、家庭訪問の必要性ということが出てきた場合には、またそれで対応させていただきたいと思います。","id":"exchange-135"},{"speaker":"三上委員","kind":"質問","question":"３０１ページにかかっているんでしょうか、８３運動ということで、簡単に伺ってまいります。平成２０年度に要綱を定めて、通常の教員採用試験というのは、通年いつごろ行われているんか尋ねました。","respondent":"河野指導課長、市川庶務課長","answer":"県費負担教員の選考ですが、東京都の場合には、まず申し込みが大体４月の中旬から５月の中旬ぐらい、それから、１次選考が７月の第２日曜日。１次選考合格者に対する２次選考が８月の第３土曜、第３日曜あたりです。 昨年の１２月からこの１月にかけて、私どもが全児童の保護者を対象に実施したアンケートの中で、要望としては上がってきているです。ただ、一般的には５時帰りで、多くの子どもが帰宅をするという傾向にはあります。","id":"exchange-136"},{"speaker":"三上委員","kind":"質問・要望","question":"温水プールになるわけですから、どうせプールとしてつくるならば、水質のいいプールをつくってあげるということも大事だろう。多少の金額、５００万円とか１,０００万円という差の中であるならば、いかがか尋ねました。","respondent":"河野指導課長、市川庶務課長、吉村小中一貫教育担当課長","answer":"区独自採用教員の採用選考の時期ですが、今のところ、少なくとも東京都との選考にぶつけるということは考えておりません。今後、さらにさまざまなメリット… 跨線橋と擁壁の改修につきましては、旧日野中の第二校庭の今後の利用の仕方に伴って、必要な対応を検討させていただきたいと思います。これについては… そういった活動を進める中、高専と品川の八潮の一貫校だけではなくて、区教委と都教委レベルでも正式に協定を結んで本格的にやりましょうと。","id":"exchange-137"},{"speaker":"三上委員","kind":"質問・要望","question":"これは答弁していただく時間はないので、要望だけしますけれども、そういう形でもしっかりと取り組んでいっていただきたい。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"南委員","kind":"質問","question":"八潮の小中一貫校の関係で伺いたいと思います。地域に反対の意見はなかったのか、まずここから伺います。","respondent":"古里学務課長","answer":"地域のほうからも５校一緒にという声もございましたので、５校で一緒に小中一貫校を立ち上げるというふうに方向を転換したものです。","id":"exchange-139"},{"speaker":"南委員","kind":"確認","question":"６校構想のときに、八潮小学校のこの２校、中学校１校ずつの統合ではなかったんですか。私はこの間の八潮の小中一貫校を急遽５校にして統合していくという方針の一連の動きの中で、協議会、その点についてはどうか尋ねました。","respondent":"古里学務課長","answer":"ご説明を申し上げ、２人、八潮の一貫校についての推進を賛成していただいていると認識しております。私ども６校構想を昨年度発表したときに、中学校の統合も視野にという形で、文章のほうで表現をしています。","id":"exchange-140"},{"speaker":"南委員","kind":"質問","question":"何回か一貫校をつくったらどうか、あるいは統合したらどうか、教育委員会の答弁はどうだったんですか。平成１７年度までの教育委員会としての見解は。","respondent":"古里学務課長","answer":"平成１８年２月７日にプレス発表した際のものですが、保護者と協議し、検討を進めていくということを申し上げてあります。八潮地区の将来の学校環境を考えていくという、これは教育委員会の責務ですので、そうしたことの中で検討をしていったということです。","id":"exchange-141"},{"speaker":"南委員","kind":"質問・要望","question":"区民の声を聞く努力はどういうふうにしてきたんですか。どういうふうに検討したんか尋ねました。","respondent":"古里学務課長","answer":"新しく施策をご提供申し上げ、一貫校を設置するという状況の流れの中で、必要な対応をとってきているです。その情熱でこのことに対応しているものです。","id":"exchange-142"},{"speaker":"南委員","kind":"質問","question":"これは、区長が今年の施政方針でお述べになった見解とも全然違いますよね。こういうことに対して、区長は教育委員会のやり方をどういうふうにごらんになっておられるか尋ねました。","respondent":"濱野区長","answer":"この思いは八潮全体の思いだと考えていますので、その思いに従って、学校施設の再配備ということに手をつけたわけです。そういうことでご理解をいただきたいと思います。","id":"exchange-143"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことに対して見解を求めたのに、全然違うことを答弁する。もう少し時間をかけて、住民の声をしっかり受けとめて、平成２０年度の一貫校開始はやはり見直すべきだと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-144"},{"speaker":"須藤委員","kind":"質問","question":"２９５ページの教育事情視察、２９７ページ、プラン２１関連事業に関連しまして、市民科と各教科の充実に関連して質問します。こういった江戸しぐさに関しては、市民科の教材として、品川区ではどういうふうにお考えか尋ねました。","respondent":"吉村小中一貫教育担当課長","answer":"これは市民科の中で十分生かしていける素材だという意見がかなり出ておりました。江戸しぐさのことを入れて実践していこうと考えている学校が今年度も数校ありまして、私の記憶では、２校から３校実施したと聞いております。","id":"exchange-145"},{"speaker":"須藤委員","kind":"質問","question":"ほかの地域では逆に副読本のような形で、このことを取り入れているというお話がありますけれども、そのあたりは教育委員会としてはいかがか尋ねました。","respondent":"吉村小中一貫教育担当課長","answer":"その部分を入れるということは難しいんですが、この市民科の教科書も当然何年かたっていきますと、改訂をしてまいります。江戸しぐさだけではないんですけれども、やっていきながら、そのうちの１つとして江戸しぐさも考えていきたいと思っています。","id":"exchange-146"},{"speaker":"須藤委員","kind":"質問・要望","question":"いい世の中にしていったらいかがでしょうかというようなことを思って、上手に使ってほしいと求めましたので、よろしくお願いいたします。同じ２９７ページのふれあい教育、３００ページの学校管理費に関連いたしまして、区内ではどんな状況になっているんか尋ねました。","respondent":"古里学務課長","answer":"学校における飼育動物ですが、現在、鳥類、爬虫類、魚類、哺乳類も当然ありますけれども、小学校２３校ぐらい、中学校でも二、三校、そうした飼育の状況があると把握しています。","id":"exchange-147"},{"speaker":"須藤委員","kind":"質問","question":"そういった教育、獣医師の先生からいろんな教育をされたりということも必要じゃないかなと思うんですが、いかがか尋ねました。","respondent":"古里学務課長","answer":"先だっては、鳥インフルエンザの対策のときには、学校における鳥類の飼育についてのご指導も、先生方にいただきました。そうした獣医師の先生方のご指導、あるいは学校の中での授業等々、そういうこともトライしている学校も幾つもあると聞いております。","id":"exchange-148"},{"speaker":"須藤委員","kind":"質問","question":"学校の中で、学校獣医師みたいな形で、整理をされてきたらどうかなと思うんですが。そのあたりを生かしていって、そういう仕組みづくりをされたらと思うんですが、いかがか尋ねました。","respondent":"古里学務課長","answer":"制度としてこうしたものがしっかり学校、それから獣医師の皆さんのご協力を得てできるような研究、検討を始めてまいりたいと思います。そういう意味で、ご提案について受けとめてまいりたいと思います。","id":"exchange-149"},{"speaker":"須藤委員","kind":"質問・要望","question":"２５年間にわたってこういった情操教育というか、作文コンクールをやられているというのは、品川区だけじゃないかなと思うんですね。小学校、場合によっては中学校という形で、整理をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/472478?Template=document&Id=886#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":115693,"voices":344}},{"id":"h19-20070319-3","meetingId":"h19-c-budget","date":"2007年3月19日","dateIso":"2007-03-19","committee":"予算特別委員会","time":"午前１０時０３分～午後６時３０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を102件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田委員","kind":"質問","question":"私は、来年度策定が予定されている新基本構想と平成２０年度に策定が予定されています第四次長期基本計画について伺います。昭和５１年７月、また昭和６３年４月に策定されていますが、どのように考えて策定していくのかをまず伺いたいと思います。","respondent":"新美企画部長","answer":"このような状況のもとで、計画につきましても、この加速する環境の変化に迅速かつ柔軟に対応できるようにすることが重要ではないかと考えております。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問","question":"ここで何点かお伺いをしたいのは、今何に問題があると区長はお考えなのか、そこら辺の点をまずお聞かせを願いたい。そして、どこに課題があると思っていらっしゃるのか、それもあわせてお聞かせ願いたい。","respondent":"濱野区長","answer":"当然に今これから開始されようとしている都区のあり方検討会、これの結果の反映というものがその期間に入ってくるということになろうかと思います。しかし、今の時点でこの検討の行方がこうこうこうなるということは見定めることはできませんので。","id":"exchange-002"},{"speaker":"石田委員","kind":"質問","question":"それを伺ってから、改めて聞きますが、今お話になった水平調整の話であります。そこら辺の意欲というか、決意というか、そこら辺をもう一度お願いしたい。","respondent":"濱野区長","answer":"理想的にはやはり調整三税のうちの固定資産税を２３区が自前で徴収して、それを調整していくというのが望ましいことだというふうに思っております。しかしどうしてもこの区域の変更が必要であるということであれば、そういったことを加味して、区域の問題が議論されるべきだろう。","id":"exchange-003"},{"speaker":"石田委員","kind":"質問","question":"期間も伺うと、その二つの関係をどう整理していくのかというのが、これから問われてくるのかなと考えています。そこに計画があると思うんだけれども、双方の位置づけをどう考えてまず取り組んでいかれようとされているのかというところをお伺いしたいと思います。","respondent":"新美企画部長","answer":"基本構想と長期基本計画の関係ですが、今回基本構想と第四次長期基本計画を、２カ年をかけまして同時に検討していくということになるわけです。","id":"exchange-004"},{"speaker":"石田委員","kind":"質問・要望","question":"そこら辺のところは、理念を書くということだと、書かないという、ある程度書かないよという確認をしたいのと、それは計画ですべてやっていくんだ。改めてそこら辺の、区議会がどうかかわっていくということを、双方どういうふうにお考えなのかというところもあわせてお聞かせ願いたいと思います。","respondent":"新美企画部長","answer":"来年、この５月末か６月初めには、その検討組織を立ち上げる必要があると考えております。この外部委員による検討組織になるわけですので、ご意見をいただく、そういった形のほうがよいのではないかというのが現時点での考え方です。","id":"exchange-005"},{"speaker":"石田委員","kind":"意見","question":"もう一度長期基本計画には議員が入っていくのかどうかというところもあわせてお聞かせ願いたいのと、行政側のメンバーはどういうふうに、議員がそれには携わっていくかということをあわせてそこら辺をもう一度お答え願いたいとの意見を述べました。","respondent":"新美企画部長","answer":"検討組織ですが、この２年間の検討の進め方を考えてみますと、同一の検討組織で検討していくことが一番スムーズであり。若干並行しながら長期基本計画にかかわるような部分を検討するということになりますと、現時点ではこの長期基本計画も検討する検討組織に議会。","id":"exchange-006"},{"speaker":"石田委員","kind":"質問","question":"これはこれからまた皆さんと話していく話でしょうから、議員は議決という一つの我々区議会に与えられた権利があるわけですから、もう一度お考えがあったらお聞かせ願いたい。","respondent":"濱野区長","answer":"一つは、特別委員会なりというものが設置されるのかどうなのかわかりませんが、議会としてもいろいろな検討の体制がとられるのではないだろうか。","id":"exchange-007"},{"speaker":"石田委員","kind":"質問","question":"ここら辺の「５つの都市像」、やっぱり、１回さらにして考えていこうとされているのかをお伺いしたい。これもどういうふうに考えられて、今７つあるわけですけれども、今行政側としては何があるととらえられているかということもお聞かせ願いたい。","respondent":"新美企画部長","answer":"やはり少子社会への対応、高齢社会への対応、少子高齢化ということにどう向かっていくかです。そういった意味では、今申し上げたような諸点について、いろんな施策をくくるような形での都市像設定が重要かというふうに考えているところです。","id":"exchange-008"},{"speaker":"石田委員","kind":"質問","question":"今、ソフトの部分で変えていけるというところも入れ込んでいくべきだろうと考えていますが、そこら辺の点はどう考えていらっしゃるのか。こういうことが必要だと考えていますが、そこら辺の点の考え方をまずお聞きしたい。","respondent":"新美企画部長","answer":"これから具体的にはこれからの第四次長期基本計画の中で具体策を考えていくわけですが、検討を進めていくことが肝要かというふうに思っております。行政がそれをどのように支援すれば、これも今度の第四次長期基本計画の大きな柱になっていくかと思っているところです。","id":"exchange-009"},{"speaker":"石田委員","kind":"質問・要望","question":"高齢者の部分は、もう一点お聞きをしたいのは、今地域でよろず相談所も含めて、介護予防、お元気で高齢者の方も常にいていただきたい。２０年後を構想していくとなると、これから団塊の世代の方々が高齢者の仲間入りをしていった中の１０年後、そこら辺をあわせてお聞かせ願いたい。","respondent":"新美企画部長","answer":"今のご質問ですが、おっしゃるとおり団塊の世代がこれから高齢者に入っていくわけでございまして、高齢者の数が増えることは必至です。区として公的な介護施設、これをきちんと計画的に増設していく、これは当然必要な重要施策であるというふうに考えているところです。","id":"exchange-010"},{"speaker":"石田委員","kind":"質問・要望","question":"だけど、具体的にＣＯ２をどれだけ削減するんだということを考えていくと、なかなか都心ではできないんだろうと考えています。国を動かしていくんだ、こういうところへ行くべきだと思いますが、そこら辺の考えを改めてお聞かせ願いたい。","respondent":"新美企画部長","answer":"ここで言えば、おっしゃるように、単純にある事業をやるんではない取り組みというのが環境対策においては重要であるということは認識をしております。","id":"exchange-011"},{"speaker":"石田委員","kind":"質問","question":"もちろん最終的には公助だ。最後にどのようにここら辺を明確に役割分担していくというお考えをお持ちなのかお聞きして、私の質問を終わりたいと思います。","respondent":"濱野区長","answer":"あるいは活用し、あるいは助け合っていくかということについて、しっかりとしたノウハウがあるわけではありません。非常に難しい分野だというふうな認識をしておりますけれども、基本構想なり、基本計画の中でしっかりと共助。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"確認","question":"そこで確認したいのが、その回答方法ですね。そこの中で全庁の方々がかかわり合いをする中でこのアンケートを評価すべきと思いますが、いかがでしょうか、お答えをお願いいたします。","respondent":"木下福祉高齢事業部長","answer":"例えばインターネットのサイトのほうから回答を出していただくというようなことも今後の回答手法の方法として検討してまいりたいと考えています。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問・要望","question":"でも、そこで経験してきた内容とか知識とか経験等をさまざまな形で生かしていくためのステップとしてこれはあるわけですから、その調査から始まって。いろんな分野でこういうパワーを生かす体制を構築していくべきと思いますが、いかがでしょうか、答弁をお願いいたします。","respondent":"新美企画部長、本間助役","answer":"したがいまして、調査の設計から分析検討につきましても、有効に生かすための分析検討を行っていく必要があるというふうに考えているところです。ＮＰＯ法人等との連携協力の仕組みづくりというテーマで検討を全庁的に進めておりますが… まさに私どももそういう観点でこれから非常に重要になってくるというふうな認識を持ってあります。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それから、コミュニティビジネスのこと等々たくさんの要望なりニーズを引き出した上で、それからボランティアやＮＰＯ。こういう入り口から出口までの間についての品川区の取り組み、それから具体的施策として展開する際の品川区としての設計を改めてお伺いいたします。","respondent":"新美企画部長","answer":"地域別の特色があるのかどうかという分析、その他、いろいろな形でこの調査結果を生かしていけるのではないかというふうに考えているところです。","id":"exchange-015"},{"speaker":"伊藤委員","kind":"確認","question":"それに伴いまして確認したいのが、やはり、新しい優秀な人材を確保していくということも当然必要となってくるわけであります。確認したいのが、採用に対する考え方、品川区の仕事に対する新規職員採用について説明を求めました。","respondent":"本間助役","answer":"２点目の新規採用職員ですが、人事考課を使いまして継続的な若手の育成に今後とも努めていきたいと、かように考えているところです。引き続いて任期付職員の採用も継続してまいる中で、このような点にも努めまして、区としてとっていく考えです。","id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうしなければいけないということもあったわけですから置いておきまして、むしろ、これからのことを考えていかなければならないと考えています。お願いします。","respondent":"新美企画部長","answer":"基本方針を策定いたしまして、その中で区といたしましては、指定管理者制度を積極的に活用していくことを明示しております。ただ、区のその他の政策、継続性あるいは基本的なほかの政策との関連性を十分斟酌していく必要があるのではないかと現時点では考えているところです。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確認したいのが、区が求めるサービス水準、非常に品川区の対応がもう少しという感があります。確認したいのが、そういう品川区側の高度な状況判断、情勢判断等々についての考え方を説明を求めました。","respondent":"新美企画部長","answer":"民間にお任せをすることがいいのではないか、現在区の施設以外の事務、業務についての民間委託をさらに推進しようということで検討を進めております。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"確認","question":"ですから、私はこの制度自体が担保されると考えていますので、改めてその高度な品川区の体制整備をお聞かせください。そのことについての確認の答弁をお願いしたいのと、これも同じように５年、それを次のステップにつなげていくのかということを説明を求めました。","respondent":"新美企画部長","answer":"経営会議の中で、それぞれの指定期間が３年間終了した時点で３年間をトータルに評価し、今後の方向について検証検討する機会を設ける予定です。やはりそのような節目節目の経営会議の中で、制度全体の見直しが必要かどうか検討していくことになろうかと考えております。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問","question":"次に都市型水害対策等について質問をします。正しい情報の提供と、万が一のときの体制は十分必要であると思われますので、災害発生時の情報提供体制について改めて答弁をお願いいたします。","respondent":"岩田まちづくり事業部次長","answer":"当品川区でも、区ではそれに対応するために、目黒川と立会川の河川管理システムというのを既に整備しております。今後いろんなメディアが開発されてまいりますので、そういったものを使いながら、区民の方の情報提供というのは検討してまいりたいと思います。","id":"exchange-020"},{"speaker":"菊地委員","kind":"質問・要望","question":"この中で特別養護老人ホームなど、高齢者施設、これらにかかわる問題についても多くの要望やあるいはそれぞれの生活にかかわる記載が行われています。それからもう一点、区内の特養に９４名の方が入所されたそうですけれども、この皆さんの年齢と介護度の構成をお聞かせ願いたいと思います。","respondent":"木下福祉高齢事業部長","answer":"適切なケアマネジメントのもと、在宅サービスあるいは在宅が難しくなれば施設サービスにつなぐという形で対応させていただいているところです。年齢的には、８０代の方が一番多うございまして、その次に７０代というような形になっているところです。","id":"exchange-021"},{"speaker":"菊地委員","kind":"質問・要望","question":"もう一点お聞きしたいのは、今お知らせをいただいたこの９４名の方で、このことも教えてほしいと求めました。９月の入所調整に４５０名の方が申し込みをされたそうですけれども、それとも病院あるいは老健、このことについてもお聞かせを願います。","respondent":"木下福祉高齢事業部長","answer":"特別養護老人ホーム、区内の施設に９４名の方が入られましたけれども、その方々の入所前の居所ということで、在宅の方が６５人、約７０％弱です。それから、申し込みをされた方ですけど、約４５０名の申請がある中で、在宅の方は約１５０名という数字になっているところです。","id":"exchange-022"},{"speaker":"菊地委員","kind":"質問","question":"９４名の方で在宅から入所された方が６５名ということですね。かなり在宅介護の状況そのものが現実的にはないわけですから、こういう皆さんは入所が不可能なのかというところをまずお聞かせを願えますか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"私どもの基本的な考え方をちょっと申し上げますと、そして共助、やはり在宅介護を進める方の中で非常に重要なことだというふうに考えております。","id":"exchange-023"},{"speaker":"菊地委員","kind":"質問","question":"四つの項目で１００点を基準にして何点になるかということで入所されるわけですよね。それとも３項目で審査をされるのか、それとも４項目で審査をされるのか、その辺をちょっともう少し明確に教えてほしいと求めました。","respondent":"木下福祉高齢事業部長","answer":"入所調整基準は大きく四つの柱があるわけでありますけれども、いわゆる老健等に入所されている方については先の三つの項目、この部分で評価をしています。","id":"exchange-024"},{"speaker":"菊地委員","kind":"質問","question":"鈴木（ひ）委員が以前に本会議の一般質問で紹介をしていましたけれども、３人のお子さんを抱えて、結局は半年ごとに転々とせざるを得ない。今事例を紹介しましたけれども、こういう事例の方をどのように考えるのか、この辺もお聞かせ願いたいと思います。","respondent":"木下福祉高齢事業部長","answer":"三多摩を含めますと、私どもはやはり多様な選択肢を用意するという考え方で、この間ケアホームも進めてまいりました。そういう点では、多様な組み合わせの中で基盤整備を進めてきている、今後もそういう考え方でいきたいというふうに考えているところです。","id":"exchange-025"},{"speaker":"菊地委員","kind":"質問","question":"ですから、東京２３区でこれまで１８番目というふうに話をしてきましたけれども、２０番目になっています。約４割ぐらいか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"特別養護老人ホームについては、そういう意味では区内の施設を基本にしつつも、その他の施設についても利用されたいという方のご要望を踏まえながら適切につないでいるという状況にあるです。","id":"exchange-026"},{"speaker":"菊地委員","kind":"質問","question":"広域的な施設だということであれば、例えば品川区内にある５７２床ですか、ここには他区からの皆さんを受け入れておられるということなんでしょうか。資金的に余裕がなくても、補助制度などでケアホームに入所ができるような施設なのかどうか、この点もお聞かせを願いたいというふうに思います。","respondent":"木下福祉高齢事業部長","answer":"私ども特養の基盤整備は平成１２年まで、これも２３区の中では非常に早かったわけですけれども、基盤整備をしてまいりました。今度高優賃という新しいものを導入して、より工夫をしていきたいというふうに考えておりますので、ご理解をいただきたいと思います。","id":"exchange-027"},{"speaker":"菊地委員","kind":"質問・要望","question":"入所ができるのかどうか、この点をお聞きしたので、ちょっとその辺は明確にお答えいただきたいんです。こういう皆さんが入所できるのかどうか、そこのところを先ほどお聞きしたので、その辺を明確にお答え願えますか。","respondent":"木下福祉高齢事業部長","answer":"数万円ぐらいの負担ということもありますから、やはり経済的な状況の中では、ケアホームというのは厳しい方も当然おられると思います。","id":"exchange-028"},{"speaker":"菊地委員","kind":"質問","question":"それができないのに保険料をとっているわけですから、私は今のご答弁というのは、区民の信頼を大もとから崩すものだというふうに思います。お金のあるなしで高齢者福祉に、介護の提供に差がつくのは当たり前だという考え方なのかどうかをお聞かせ願います。","respondent":"木下福祉高齢事業部長","answer":"同時に、やはり、そういうような部分というのもあわせて保険者としては考えていく必要があるということであります。すべての方にご満足いただけるような介護保険制度の運営について、これからも私どもは努力をしていきたいというふうに考えているところです。","id":"exchange-029"},{"speaker":"菊地委員","kind":"質問","question":"住民の皆さんと一緒に都南病院跡地に特別養護老人ホームをつくってほしい、こういう運動を進めてきましたけれども、この運動の中で。それでお聞きしたいんですが、北品川以外に６９０億円に含まれていない新しい補助金などがありましたら、お聞かせを願いたいというふうに思います。","respondent":"福田まちづくり事業部長","answer":"これからの再開発に関する補助ですが、これは北品川の１２８億円を除きますと、１６４億円です。現在竣工済みのものが４,７００戸、これから竣工または計画中のものが４,６００戸、合計で９,３００戸です。","id":"exchange-030"},{"speaker":"菊地委員","kind":"意見","question":"開発事業者が行政が行うべき公共整備を行ってくれるというのが補助金投入の最大の理由となっていますけれども、公共整備は確かに重要な課題です。","respondent":"福田まちづくり事業部長","answer":"長さで言いますと２,５８０ｍ、累積換算では１万１,８００ｍ、こういうような公共事業が整備をされてまいりました。それから、目には見えないかもしれませんが、乱開発からまちを守ることができた、こういう大きな財産も隠されているというふうに考えております。","id":"exchange-031"},{"speaker":"菊地委員","kind":"意見","question":"品川区は、やっぱりもっともっと品川全域も含めてですけれども、もっときちんと目を向けるべきではないかなというふうに思っています。区民にとって、それじゃあこれがどのように役立っているのか、この点を説明を求めました。","respondent":"福田まちづくり事業部長","answer":"１点目と２点目はほぼ同じようなご質問だと思いますので一括してお答えしますが、その中で、当時あの地域にはこういう声がありました。大井町駅との都市軸の形成に努めていきたいというふうに思っておりますし、そうしたこと、区民全体の利益だというふうに考えております。","id":"exchange-032"},{"speaker":"菊地委員","kind":"質問","question":"合意形成の問題についてお聞きしますけれども、私はこうした開発に対して合意形成のシステムをきちんとつくるべきなんだというふうに思っています。こういうことだけでは何の解決策にもならないんじゃないかというふうに考えますが、その辺もお聞かせを願います。","respondent":"福田まちづくり事業部長","answer":"例えば準備組合等が主催する住民説明会がありますし、相談にそれぞれ事業者側が当たっていると、こういう現状があります。この現状を通しまして、周辺の方たちの意見は吸い上げられていると、このように認識しております。","id":"exchange-033"},{"speaker":"菊地委員","kind":"質問・要望","question":"今回の質問に当たって、特別養護老人ホームの入所調整基準をいただきたい、このように拒否をされました。しかも、先日の答弁ですと、予算の編成過程でこれが決められたということですから、思いつきの政策以外の何物でもないような気がします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"中島委員","kind":"質問","question":"款別の中でも、シーソーの話が出ておりましたが、答弁を伺っていますと、危険なものを避けなければならないという実情もあり、難しさを感じます。単なる子育ての精神的負担を軽減するだけでなく、親子ともにたくましく成長する支援を工夫していくべきと考えますが、区のご見解をお伺いいたします。","respondent":"古川児童保健事業部長","answer":"あるいは基本的な生活の規範でありますとか、そういったものについても必ずしも十分に身についていない、こういう実態がまた見えてまいります。親が育っていくためにどのような支援ができるか、そういう施策を工夫してまいりたいと、このように考えてあります。","id":"exchange-035"},{"speaker":"中島委員","kind":"提案","question":"私は平成１４年第４回定例会において、その意味で、今回早川町から「丸山」を無償で提供していただけるということを伺っております。これをはぐくんで、たくましさを培うような親育ち支援に利用されてはいかがかなと思いますが、ご見解をお伺いいたしますとの意見を述べました。","respondent":"山田区民生活事業部長","answer":"大変共通した体験であるとか、共通した時間を持ってお互いに汗を流したり、知恵を出し合ったりするような場面という形が考えられます。自分たちが考えていく、新しい事業展開を工夫しながら進めてまいりたいというふうに考えてあります。","id":"exchange-036"},{"speaker":"中島委員","kind":"質問・要望","question":"公明党は、昭和６１年から乳幼児の医療費に対する助成制度の創設をどこよりも早く要望し、直接その制度の創設を要望しました。その後、私どもは平成１０年に所得制限の撤廃と義務教育である中学３年修了までに年齢を拡大してほしいと提言、毎年予算要望を続けてまいりました。","respondent":"古川児童保健事業部長、濱野区長","answer":"ご案内のとおりこの子どもすこやか医療費助成の費用負担につきましては、今回東京都の補助金から都区財調の算定対象と、こういうふうになりました。したがいまして… それを受けて、私ども児童手当の増額、そして所得制限の撤廃を継続して行っていくということを決めました。そういう時機に応じた財源の手当を考えながら、物事を決めていきたい、こんなふうに思っているところであります。","id":"exchange-037"},{"speaker":"中島委員","kind":"質問","question":"入院を問わず、すべての保険医療の自己負担額が助成されますが、先日区民の方から子どもの歯の矯正には適用されないのですかという質問がありました。区として、品川の子どもたちの現状をどのように把握されておられますか尋ねました。","respondent":"宮本品川区保健センター所長","answer":"３歳のお子さんで約１０％、小中学生ですと５％ぐらいが歯並びとか咬合が悪いと、そういう異常のある方が指摘されているところです。そういうような日常習慣の改善等の指導あるいは虫歯予防の大切さなどについて、指導も行っているところです。","id":"exchange-038"},{"speaker":"中島委員","kind":"質問・要望","question":"子どものうちに矯正すれば、比較的治しやすく、将来健康な歯を維持するためにも大事であると聞いております。今後、保険適用について国や都に働きかけるとともに、区としても公費助成も幾分か考えてほしいと求めましたが、いかがか尋ねました。","respondent":"宮本品川区保健センター所長","answer":"国においてもきちんとした一律の基準が確立していない現状がありますので、保険適用というのは現在では難しいところです。やはり、予防は大事というふうに思っておりますので、今後ともその観点で事業の充実あるいは普及啓発に一層取り組んでまいりたいと考えています。","id":"exchange-039"},{"speaker":"中島委員","kind":"提案","question":"平成１７年第１回定例会および平成１８年第４回定例会で里帰り出産でも利用できる、それと利用回数を増やしてほしいと提案してまいりました。早速これまでの１回から一気に１５回に増やす予算を編成するなど、この変化をどうとらえておられるか、お考えをお聞かせほしいと求めました。","respondent":"古川児童保健事業部長","answer":"東京都地域保健事業連絡協議会、いわゆる５者協というふうに申し上げておりますが、ここでの協議事項ということになってあります。その中におきまして、今後原則５回の実施に向けた検討をしてまいりたいと、このように考えてあります。","id":"exchange-040"},{"speaker":"中島委員","kind":"提案","question":"私は平成１３年３月の予算特別委員会において、元気な高齢者づくりのために屋内プールの設置を要望してまいりました。そこでぜひここでも水中散歩教室の開設を要望したいと思いますが、ご見解を説明を求めました。","respondent":"古川児童保健事業部長","answer":"ご紹介ございましたとおり、伊藤学園のほうには、今回温水プールが設置をされるわけです。私どもといたしましては、この伊藤学園のプールを使った教室を今後可能な限り開設していきたいと、このように考えてあります。","id":"exchange-041"},{"speaker":"中島委員","kind":"質問・要望","question":"多くの方が参加しやすい運営を要望しておきたいと思いますが、肺炎球菌ワクチン接種の公費助成、これが出ておりました。公費負担を実施している自治体の様子などを積極的に確認され、有効とあれば、ご見解を説明を求めました。","respondent":"青山品川区保健所長","answer":"特別養護老人ホームでの取り組みとして、それによって、肺炎を半減させたとの報告もあります。今後予防接種の効果や費用助成につきましては、国の予防接種に関する検討会での検討を見守ってまいりたいと思いますが、さらに強化してまいります。","id":"exchange-042"},{"speaker":"中島委員","kind":"質問・要望","question":"単純に読んでしまいますと、区が求める税負担は基本的には変わらない。そして、今回なぜ廃止されるようになったのか、まずご説明ほしいと求めました。","respondent":"早津区民生活事業部次長","answer":"平成１９年度に廃止を予定しております定率減税につきましては、導入されたのは平成１１年度です。経済状況がかなり進展をしてまいりまして、平成１８年度に定率減税措置を半分に縮減、平成１９年度に残りを廃止という形で進んできたものです。","id":"exchange-043"},{"speaker":"中島委員","kind":"質問・要望","question":"平成１１年、１９９９年ですが、あくまでも景気対策のためにできたものだと認識しております。基礎年金財源に活用されると聞いておりますが、それは私たちの生活の上で、どのように反映されるのか教えてほしいと求めました。","respondent":"早津区民生活事業部次長","answer":"定率減税の見直しに伴います国庫増収分の取り扱いですが、現在基礎年金の国庫負担分の引き上げが段階的に実施されております。定率減税の見直しに伴う財源をそのように充当しているというのは、年金制度自体を維持していくのに必要な措置ではないか、このように理解しています。","id":"exchange-044"},{"speaker":"中島委員","kind":"質問・要望","question":"ところが、その解決を求める場合、売主が不動産会社だったりして、その対応は決してスムーズではありません。このような確認審査は民間でも行えると聞いておりますが、区としてはどこまでの責任があるのか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"欠陥住宅の対応につきましては、その民間の機関であるという認識を私どもは持っておりましたし、その責があるというふうな認定をされております。平成１２年４月に施行された法律で、雨漏りとかそういった事例については、施工業者がきちっと直す責務を負っているところです。","id":"exchange-045"},{"speaker":"中島委員","kind":"質問","question":"今回国のほうでも先ほど言われたんでしょうか、欠陥が発覚したとき、こういったものが今年の秋ごろに施行の兆しが見えていると伺っております。今後区としてはどのような対策を考えられておられるのか、人材等の確保もあわせてお伺いいたしたいと思います。","respondent":"岩田まちづくり事業部次長","answer":"それに従わない場合、あるいは弁護士の相談はここでやっていますよということもできるだけわかりやすくご説明をしておりますし。私どものほうの建築職員の人事異動や配置等を工夫いたしまして、きちっとそれが後世に伝えられるように今後とも努力してまいります。","id":"exchange-046"},{"speaker":"中島委員","kind":"質問・要望","question":"次に、交通安全についてお伺いいたします。ここ数年の区内で発生した交通事故の状況およびその主な原因、またこれからの見直し等も含めた対策があればお知らせほしいと求めました。","respondent":"岩田まちづくり事業部次長","answer":"その対策ですけれども、先ほどご提示になられました地図のように、交通事故のほとんど７割近くが幹線道路の交差点付近で発生をしております。あるいはカーブミラーの設置等、さまざまなイベント等で交通ルールの遵守のＰＲ、こういったものを行っているところです。","id":"exchange-047"},{"speaker":"中島委員","kind":"質問・要望","question":"集中して幹線道路に多いということで、そうした要望も出ておりますが、そうしたところの見直し等も今後されていくのかなと思います。あわせて区としての対策とお考えを説明を求めました。","respondent":"岩田まちづくり事業部次長","answer":"道路の交通安全につきましては、その地域に住んでおられる方の意見を十分参考にしながら、今後とも警察のほうと対策を講じてまいりたいと思います。３番目に若者による暴走運転、今後ともこういった効果のある場所をとらえてＰＲ、啓蒙活動に努力してまいりたいと思います。","id":"exchange-048"},{"speaker":"中島委員","kind":"質問・要望","question":"次に、通学路についてでありますけど、本年は品川区小中一貫校６校構想のうち、既に２校目、伊藤学園が４月の入学を待っております。こうした通学路の設定に当たっては、どのようなプロセスを踏まれているのかお知らせください。","respondent":"長田教育次長","answer":"この最終原案に基づきまして、１月、２月には町会長会議での説明あるいはスクールゾーンにかかわる方々に対する説明と協力要請を行ってあります。","id":"exchange-049"},{"speaker":"中島委員","kind":"質問","question":"ですから、また特に交通課との連携というのは、しっかりとっていくべきではないかなと思います。この点については、どのようにされるか、ご見解をお伺いします。","respondent":"長田教育次長","answer":"この辺については、再度学校が始まるまでに周知を図ってまいりたいと、このように考えてあります。これについて、現在できるだけそうした対応ができるように前向きで検討していますので、期待をしてもらってよろしいかというふうに思ってあります。","id":"exchange-050"},{"speaker":"中島委員","kind":"質問","question":"大井警察の方が１週間ぐらい見守ってくださるということも伺っておりますが、これはそう長く続くものでは、また続けられるものではないと思います。父兄の方だけだとどうしても車がそれを無視して通ってしまうということなので、緑のおばさんとか、その点はお考えいただいていますか尋ねました。","respondent":"長田教育次長","answer":"警察のような制服ではありませんけれども、ジャンパー等統一をした服装で立っておりますので、その辺の効果はあろうかと思います。まちづくり事業部のほうとも連携をしていまして、これにつきましては、３月いっぱいですべて完了される予定です。","id":"exchange-051"},{"speaker":"中島委員","kind":"質問・要望","question":"十分に安全を確保していただくことを強く要望いたしまして、私の総括質疑を終了いたします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"大西委員","kind":"提案","question":"要するに団塊バンクのようなものですかね、地域にどう貢献できるか、大変私はこの２３区の中でも誇りを持てる区であろうと想像しています。そういう点で、その後は区がその方々にその運営を任せるという形のことを一つ提案したいと思いますが、２点との意見を述べました。","respondent":"山田区民生活事業部長、木下福祉高齢事業部長","answer":"統計を持っている関係から、私のほうから数字をお示しをします。５５歳から５９歳ということで、２万７,１９０人、こちらが品川区の人口です。そこを拠点に地域の方々にいろいろな社会貢献をしていただく、そういう足がかりの場所として設置をさせていただいているところです。","id":"exchange-053"},{"speaker":"大西委員","kind":"質問・要望","question":"その独自の、それだけの能力のある人たちが私は先ほどの答弁で２万７,０００人とあったでしょうか、すばらしい能力集団になってくるんじゃないかな。例えば１日３,０００円でもいいんじゃないか尋ねました。","respondent":"山田区民生活事業部長","answer":"やはり、これからは自主的な主体的なボランティア活動が私ども行政とパートナーシップを持ってやっていただくんだというふうに認識しています。今私どものほうは、表彰なり奨励金という形で顕彰していくという流れをつくってありますので、その点でご理解いただきたいと思います。","id":"exchange-054"},{"speaker":"大西委員","kind":"質問・要望","question":"給食をせっかく週５日つくっているわけですから、選択制にしていただきたいというのが１点ありますので、後でお願いいたします。その２点、３日前という原則の見直し、要するにサービスを開始するかどうかということについてお伺いしたいと思います。","respondent":"山田区民生活事業部長、古川児童保健事業部長","answer":"自分たちのアイデアで自分たちの１３８団体をつくり、５,０００人を組織したという力を持っているというふうに私どもも認識をしています。買物に行くという、現在の数が一番バランスがいいんだというような回答がありますので… 在宅の子育てを支援する制度としては、このオアシスルームは平成１６年度から始まった事業でありますし、平成７年度から始まっています。","id":"exchange-055"},{"speaker":"大西委員","kind":"質問・要望","question":"別に８割の方々で要らないという人たちには２食でいいんじゃないでしょうか。の２割の方々の中で、ぜひ配食がいただきたいんだという方々の要請にどのように行政がこたえるのかということであろうかと思います。","respondent":"山田区民生活事業部長","answer":"その一つのサポートとして栄養のバランスを考えて、学校給食、米飯の２回を活用してお配りをするです。新しい問題提起については、これからも研究はしてまいりますが、今すぐということにはならないかというふうに考えてあります。","id":"exchange-056"},{"speaker":"大西委員","kind":"質問・要望","question":"いいですか、残存能力といいますけど、２１食中全部を配食してくださいということを申し上げているんじゃないんですよ。せめて学校給食をつくっている５日間があるわけですから、その間だけでも、２１食のうちの５食の提供の準備をされてもいいんじゃないか尋ねました。","respondent":"濱野区長","answer":"どこからということを考えたときに、区役所は八潮にあまり関心がないようですねというようなことを言われたことがあります。よそからも人が来るような、そういう仕掛けが必要なのかなということを、これは漠然とした思いですけれども感じたところです。","id":"exchange-057"},{"speaker":"大西委員","kind":"質問","question":"中学校に広げていこうという考え方があるのかどうかをお尋ねする点、それと、これがいかにあるべきかということが議論されました。品川区内の小中学校において学級崩壊のような状態が見られるかどうか、それと、どれぐらいの学年でそのようなことが起こっているかを説明を求めました。","respondent":"長田教育次長","answer":"３点目は、ＣＡＰのスタッフも全員が対応できるわけではないというようなことの中で、今適用を見送っているところです。そういった認識を持ってしっかり対応していくことが必要かと思います。","id":"exchange-058"},{"speaker":"大西委員","kind":"質問","question":"今ちょっと答弁で抜けていたのが、まずどの学年でそういう学級崩壊のような形が起こっているのが一番多いのか。それと、どれぐらいのクラスの数で、そのような形が存在しているのか、それと、出席停止はどちらなのか、この点が抜けているのでお願いします。","respondent":"長田教育次長","answer":"やはり、その原因をつかまえなければならないというようなことがありまして、このことが重要な内容だろうというふうに考えてあります。出席停止にして問題は解決しないというような考え方から、今品川区では出席停止というような方法はとっておりません。","id":"exchange-059"},{"speaker":"大西委員","kind":"質問・要望","question":"これはプロが当然プログラムとしてやっているわけですから、ぜひこのことは、そのようなことを行っていただきたい。とりあえず環境とリサイクルについてどのような形で市民科を通じて行っているんでしょうか、説明を求めました。","respondent":"長田教育次長","answer":"それから次に、環境の教育ですけれども、これは市民科の学習として、１年生から９年生まで指導要領によりますと８３時間程度予定をしています。５から７年生、８・９年生というような形で、現在取り組んでいるところです。","id":"exchange-060"},{"speaker":"大西委員","kind":"提案","question":"なぜ、教育委員会はこのことを強制しないんですか。それをやったらどうか尋ねました。","respondent":"長田教育次長","answer":"そういった形では、それの対応をしているというようなこともありまして、件数は増えてきているんだというふうに私どもは思ってあります。そういった部分でのいじめ等をはじめとするさまざまな教育上の問題に関する対応をやってきているというようなことです。","id":"exchange-061"},{"speaker":"大西委員","kind":"質問","question":"私は座席譲りの会の会員なんですから、あなたに座ってもらわなきゃ困る」「それじゃあ、ありがとう。ぜひ始めてもらいたいですが、この点はいかがか尋ねました。","respondent":"長田教育次長","answer":"公共意識の欠如という問題がありまして、こういった部分につきましては、子どものころからそういった認識を持っていただこうということで。","id":"exchange-062"},{"speaker":"大西委員","kind":"質問","question":"いいですか、もっと積極的にやってくださいよ。その答弁をお願いします。","respondent":"長田教育次長","answer":"こういったものが一律にできるかどうかというのは、社会情勢、それから先ほどお話をしました親御さんの状況、こういったものがあります。ですから、そういった意味では、必要があれば私どもも積極的にやっていくと、こういうことでご理解をいただければと思います。","id":"exchange-063"},{"speaker":"大西委員","kind":"質問","question":"だから、学年の初めに、しっかりと家庭訪問させなさいと言っているんです。その点はどうか尋ねました。","respondent":"長田教育次長","answer":"家庭訪問につきましては、委員のご指摘もいただきまして、これからの課題として学校も含めまして検討をしていきたいというふうに思ってあります。","id":"exchange-064"},{"speaker":"大西委員","kind":"質問","question":"これで質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"西本委員","kind":"質問","question":"民間委託、それから指定管理者制度の中で、ＮＰＯの特徴をどうとらえているのでしょうか。それに合わせまして、ボランティアとＮＰＯとの違いをどう認識されているのか、お聞きしたいと思います。","respondent":"新美企画部長","answer":"区民の多様なニーズにかなりきめ細かで柔軟な対応が可能な組織体で、その活動で培った専門性を有している団体、組織というふうにとらえております。","id":"exchange-066"},{"speaker":"西本委員","kind":"質問","question":"もう少しお聞きしたいところですが、平成１８年度でいろいろと庁内で調査をしたというふうにお聞きしておりますけれども、どういう調査をされているのか、それを踏まえて、では平成１９年度はどういう流れでしていこうとしているのかお尋ねします。","respondent":"新美企画部長","answer":"平成１８年度は、どういうきっかけでどのような法人あるいはグループとどんな事業について連携をし、現在分析をしています。庁内検討委員会をつくっておりますので、今後進めていくにはどういう施策をなすべきかという検討を平成１９年度に行う予定にしております。","id":"exchange-067"},{"speaker":"西本委員","kind":"質問","question":"それで、業務委託という形で３０のほう、されているということですが、この民間委託との関係ですね。ＮＰＯに委託するという場合とでは、やはり違うんではないかなというふうに思いますが、その分析はいかがか尋ねました。","respondent":"新美企画部長","answer":"その特性を生かすケースで従来にはないサービスを、新規的なサービスを行うときに大変ＮＰＯ法人との連携が有効な場合が多いということがあります。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問","question":"近年できましたいきいきラボ関ヶ原というのがありますけれども、これは行政ニーズからある程度人選をして、今まで行政とうまく仕事をやっていたと。相手側をどういうふうに評価していくのか、これは非常に難しいところになると思いますが、そのお考えをお聞きしたいと思います。","respondent":"新美企画部長","answer":"今ご質問にありますように、一緒に立ち上げて、ある事業を実施していこう、一緒に立ち上げるときはおっしゃるとおりです。委託するサービス業務についての当然ノウハウ、実績を見た上で、それが継続的に安定的にできるかというところを基本的に評価する必要がある。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"そうしますと、既存の中での実績の表現の仕方というのがいろいろ問題になろうかと思います。どういうふうな形にその実績を求めていくのか、その情報、その仕組み的なところはどのようにお考えか尋ねました。","respondent":"新美企画部長","answer":"ただ、例えば学校図書館の支援業務、民間企業とＮＰＯ数社の組み合わせの中でお願いをしているということがあります。例えば子育て支援ポータルサイトとか、空き店舗の活用の子育て支援というのは、この辺も来年度進める中で。","id":"exchange-070"},{"speaker":"西本委員","kind":"質問","question":"そうなると、責任の所在はどうなってくるんだろうかというところが出てこようかと思います。そのＮＰＯならではの特徴でもあり、平成１９年度のいろいろ検討される中で、どういう項目として検討しようとしているのかをお聞きしたいと思います。","respondent":"新美企画部長","answer":"連携の形態につきましては、あるいは役割分担をした事業協力といった、いろんな形態をとらえて連携協力という形でとらえていきたいと考えています。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問・要望","question":"じゃあ、その発展した後は、どういう形になっていくんだろうかと。どういうふうに発展をさせていこうとするのか、お考えがあれば、最後にお聞きしたいと思います。","respondent":"新美企画部長","answer":"それがずっと財政的支援がその自立を阻害することがないようにできるだけ事業で自立できるような方向性を当然求めていくべきだとは考えております。","id":"exchange-072"},{"speaker":"西本委員","kind":"質問・要望","question":"次に、小学校と幼稚園・保育園の連携についてお尋ねします。この問題をどのようにとらえているのか、それで、品川区の実態からこの問題に取り組むというふうな形になったのかをお聞きしたいと思います。","respondent":"長田教育次長","answer":"児童保健事業部と連携を深めながらカリキュラムの検討、それから情報の共有等、さまざまな観点から各事業を推進しています。平成１９年度から区内の小学校に入学予定の就学前幼児がいる全保護者に対しまして、就学支援シートという新しいスタイルですけれども。","id":"exchange-073"},{"speaker":"西本委員","kind":"質問","question":"その小中一貫校、小中というところの連携に対して、この施策の位置づけとはどういう形になってくるんでしょうか。幼保になるんでしょうか、幼保、小中という形の連携した形で今後考えていくということなのか、お答えをお願いいたします。","respondent":"長田教育次長","answer":"そういった部分では、保育課と連携をとりながら、この問題に取り組んできているところです。これを開発してまいりますけれども、小学校との連続に役立つ実践について取り組んでまいりたいと、このように考えております。","id":"exchange-074"},{"speaker":"西本委員","kind":"質問・要望","question":"これに幼保をあわせた形をやっていこうというところでは、では、具体的に連携の仕組みをどういうふうにつくっていくのかなというふうに考えています。その考え方、それから、具体的な作業レベルの話をほしいと求めました。","respondent":"長田教育次長","answer":"先ほど申し上げましたけれども、平成１９年には就学支援シートというものを就学時前の保護者の方に全部お配りします。自分の子どもの特徴ですとか、あと教育に要望する内容、こういったものを書き込んでいただけるように改善をしていく予定です。","id":"exchange-075"},{"speaker":"西本委員","kind":"質問","question":"いろんな委員会がありますよというお話ですが、だれが中心にまとめていくんだろうというところが見えないんですね。それから地域になるんでしょうか、そちらのほうで全部集約をして管理をしていく、その中心になっていく担当はどこになるのか尋ねました。","respondent":"長田教育次長","answer":"どちらが中心になるというような話ではなくて、それぞれ教育委員会と児童保健事業部の持っている仕事上の性格の問題、こういった問題をお互いに理解をしながら共同して進めていくと、こういうような形にしてまいりたいというふうに思ってあります。","id":"exchange-076"},{"speaker":"西本委員","kind":"質問・要望","question":"あくまでも教育の場でありまして、０歳から１８歳までを視野に入れてという形になりますと、かなり福祉という観点が入ってこようかと思うんですね。先ほどの１本の柱を立てるときに、その私立との関係をどういうふうにつくっていくのか、その関係もあわせてお答えほしいと求めました。","respondent":"長田教育次長","answer":"そういった意味では、まさにこの辺につきましても児童保健事業部との連携というのが必要になってこようかというふうに思ってあります。そういったワンクッションを置いた中でも、そういった十分な協議はできるものというふうに考えてあります。","id":"exchange-077"},{"speaker":"西本委員","kind":"提案","question":"一つの具体的な提案になりますけれども、昨年の第４回定例会でも提案させていただきましたけれども、食物アレルギー対策。少なくとも栄養士がおりますので、その一つの具体例として、そちらのほうの着手のほうはいかがか尋ねました。","respondent":"長田教育次長","answer":"ただ、この連携につきましては、必要な情報交換を行っていきますけれども、個人情報の問題ということで、難しい部分も出てきているのも事実です。先ほど申し上げました来年度から実施する就学支援シート、大きなものとしてあらわれるだろうと、このように思っているところです。","id":"exchange-078"},{"speaker":"西本委員","kind":"質問・要望","question":"私はそれよりも、栄養教諭も含めてですけれども、そこの蓄積をやはり共有するということは非常に大切なことではないかなというふうに思っています。食物アレルギーが何ぞやというところも含めて、ぜひその関係を築いていただきたいというふうに思いますが、再度今後の展望はありますか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問・要望","question":"では次に、コミュニティ組織による子育て支援についてお聞きします。平成１９年度は親育ちという対策が非常に、まずこれを先にお答えをしていただきまして、後でまとめて質問させてほしいと求めました。","respondent":"古川児童保健事業部長","answer":"これは大変微妙な問題であろうと考えていますけれども、これが親育ちに対して品川区は平成１９年度、新しい施策として取り組む大きな背景であります。","id":"exchange-080"},{"speaker":"西本委員","kind":"質問","question":"その上で、保育園ＰＴＡができたという経緯があります。保育園ＰＴＡができた経緯、その当時の父母の会をどうとらえていたのかということをまずお聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"それは１０年ほど前の父母の会、あるいは父母連、さらにはその上位組織である保育問題協議会との品川区の保育がとった一つの考え方です。３カ年ですべての年にＰＴＡができたわけでありますけれども、新しい組織の運営を今後目指していきたい、このように考えてあります。","id":"exchange-081"},{"speaker":"西本委員","kind":"質問","question":"ですから、ある一定の整理が必要だったという時期は仕方ないし、当然のことだったのかなということで非常に私もいろんな思いがあります。その内容と、それから保育園ＰＴＡをどのような位置づけをして、再構築をしようとしているのか、お考えをお聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"保育園の中だけではなくて、あるいはブロックの中での共同の事業も当然考えられるわけでありますので、なかなか動きの悪いＰＴＡになってまいります。","id":"exchange-082"},{"speaker":"西本委員","kind":"質問・要望","question":"何年続いたでしょうか、保育運動。そこの垣根を超えるための施策があれば、教えてほしいと求めました。","respondent":"古川児童保健事業部長","answer":"ご覧のとおり保育園のさまざまな保育の事業の実施状況、少なくとも従前のような関係から大きく改善されておりますし、このように考えてあります。","id":"exchange-083"},{"speaker":"西本委員","kind":"質問","question":"やはり、そういうことは二度と起こすべきではないと私は思っております。ともに保育園をつくっていく、子育ての輪をつくっていくということに対しまして、区の見解をお聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"何度もお話ししていますが、保育園と保護者との関係は緊密にあるべきだろうと、このように考えています。こう思ってありますので、ＰＴＡを中心に保育園と保護者の関係をより正常に持っていきたいと、このように考えてあります。","id":"exchange-084"},{"speaker":"井上委員","kind":"質問","question":"２点目ですが、実際に区長は基本構想策定のプロセスをどのように考えているのでしょうか。２月２０日には、基本構想策定支援事業者説明会という会議が行われていましたが、コンサルタントの仕事の内容は、どんなことになるのか尋ねました。","respondent":"濱野区長、新美企画部長","answer":"１点目の基本構想の目指す私のイメージがどういうものかということでありますけれども、基本構想はそれで終わってしまいます。策定のプロセス等については、部長のほうからお答えします。そのような作業を進めつつ、５月末から６月の当初には外部委員の方による検討組織を立ち上げてまいります。","id":"exchange-085"},{"speaker":"井上委員","kind":"提案","question":"こういった分野ごと、課題ごとに市民が自由に参加をして行うワークショップ形式によって、積み上げていく作業を取り入れた素案づくりを提案します。あわせて、基本構想の柱立てになる課題をどのようにとらえているのか、お答えほしいと求めました。","respondent":"新美企画部長","answer":"したがって、こういう構想関係でのワークショップ方式による検討の事例というふうに私ども調査しておりまして、先ほど申し上げたような方法で。環境問題、都市基盤としてのまちづくり、いろいろあろうかと思いますが、これは検討の中でぜひ柱立てをお願いできればと考えています。","id":"exchange-086"},{"speaker":"井上委員","kind":"質問・要望","question":"区民の方の要望もたくさんあるということはそうかと思うんですけれども、でも、ワークショップも前向きに議論していただきたいんですが。次は、パブリックコメントの制度化について伺います。","respondent":"新美企画部長","answer":"これは施政方針の中でも述べられておりますように、区が区民と共通認識のもとに地域の課題を考え、解決策を探っていく必要がある。","id":"exchange-087"},{"speaker":"井上委員","kind":"提案","question":"これから意見を求める対象の意見聴取の期間とか、情報の提供、すなわち提案に対する検討の経緯と結果も含めた回答をするということになると思います。","respondent":"新美企画部長","answer":"実施に移し、より趣旨に沿った、目的に沿った制度になるように運用を工夫していくことが大変重要なのではないかという認識です。したがいまして、できるだけ早く要綱を策定し、実施に移していきたい。","id":"exchange-088"},{"speaker":"井上委員","kind":"質問・要望","question":"２点目は、荏原西地区の小中一貫校建設にかかわる荏原第二中学校統合について伺います。なぜ教育委員会は２００８年４月に荏原第二中学校と平塚中学校が一緒になる必要があると判断したのか、その理由を説明を求めました。","respondent":"長田教育次長","answer":"昨年の７月に平塚中学校と平塚小学校の一貫校の建設についての説明会に入っていったわけですけれども、こういうような希望が出てきてあります。２２年の４月、２２年というのは一貫校の開設時期になるわけですけれども、この三通りについてそれぞれ比較検討をしてきました。","id":"exchange-089"},{"speaker":"井上委員","kind":"質問・要望","question":"６校構想の学校の決定の過程で地域の声を聞きながら進めていくべきであるということを生活者ネットワークは一貫して求めてきましたけれども。それから、今後どういう形で住民および保護者、生徒の声を聞いて合意形成を図っていくのかお伺いをいたします。","respondent":"長田教育次長","answer":"保護者への説明会ですけれども、それからそれに先立ちまして、平成２０年４月に中学校２校を統合するというようなお話をさせていただきました。","id":"exchange-090"},{"speaker":"井上委員","kind":"提案","question":"子どもの声を直接聞くようにという生活者ネットワークの提案に対しては。そこでこの計画に対して、子どもたちの声はどのように聞こえているのか、また、教師の声はどのようなものなのか、お伺いをいたしますとの意見を述べました。","respondent":"長田教育次長","answer":"１０日以降、それから７年生に入学をする保護者、こういった方々について説明と意見等を聞いてきたところです。その中では、やっぱり教員が一致団結をして、この施策を進めていくというようなことでは、確認をしています。","id":"exchange-091"},{"speaker":"井上委員","kind":"質問","question":"私の質問が通じなかったかもしれません。今後子どもたちにどうするかではなく、現時点で子どもの声はどうなのかということをもう一度、答えるよう求めました。","respondent":"長田教育次長","answer":"子どもの声も、もう中学生ですので、十分自分なりの考えは言えるという観点の中で、学校の中でそういった部分を取り上げまして意見を聞く機会、こういったものを設けたいと、このように思っているところです。","id":"exchange-092"},{"speaker":"井上委員","kind":"提案","question":"広くだれもが参加できる形で設け、６校構想ありきで計画を推進するべきではない、見直すべきだということを再度求めておきます。区として解決に向けた取り組みができるものがあると思われているかどうか、また、具体的な取り組みについて見解を伺いたいと思いますとの意見を述べました。","respondent":"福田まちづくり事業部長","answer":"それから、事業者の行う説明会が不十分だとか、こういうような項目が非常にたくさん見られます。今後につきましても、区の市街地整備基本方針に沿うならば、そのような支援策を積極的に講じてまいりたいというふうに思っております。","id":"exchange-093"},{"speaker":"井上委員","kind":"質問・要望","question":"この数字は開発要綱の対象となる１５戸以上のワンルームマンションですから、１４戸以下のワンルームの戸数を含めると。ワンルームマンションの急増に対して適正に建設を誘導する考えは区はまだお持ちにならないのかどうか見解を伺います。","respondent":"福田まちづくり事業部長","answer":"このことは区がその当時からワンルームマンションには、他のマンションには見られない固有の問題があるという認識を持っていた。このような指導を続けてまいりたいと考えていますが、三年の例を見ますと、そういう問題意識を持って臨んでいるところです。","id":"exchange-094"},{"speaker":"井上委員","kind":"質問・要望","question":"住民の方たちが非常に困惑しているというところがありましたので、積極的にこの部分についてはさらに取り組んでいただきたいと思っています。ここで要望なんですけれども、住民主体の地区計画ができ上がることを要望して、総括質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"}]},{"id":"topic-02","title":"休憩前に引き続き、会議を開きます。 第５号議案、平成１９年度品川区一般会計予算に対する修正案","agenda":"休憩前に引き続き、会議を開きます。 第５号議案、平成１９年度品川区一般会計予算に対する修正案","exchanges":[{"speaker":"飯沼委員","kind":"提案","question":"日本共産党区議団の提案者を代表して、第５号議案、平成１９年度品川区一般会計予算案の修正提案を説明します。条例に関する提案説明は本会議において行わせていただきましたので、この場では予算修正説明のみを行いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-096"},{"speaker":"須藤委員","kind":"質問・要望","question":"我が会派が区長に２０５項目にわたり政策予算要望いたしました子育て支援の充実、商店街や中小企業の振興施策、行政改革の着実な推進が見てとれます。平成１９年度品川区各会計予算の原案に賛成し、議員提出の予算修正案につきましては、修正の必要のない案として反対をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"宮崎委員","kind":"提案","question":"品川区で働く９００人のパート、派遣は１０万円から１４万円の生活保護基準以下、均等待遇の原則を求めるものです。特別養護老人ホームの入所基準が、なぜ情報公開の手続がなければ公開できないのか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"三上委員","kind":"提案","question":"すこやか児童手当についても現行の小学６年生までを中学３年生まで拡大することなどを含め、一層の負担軽減を要望しておきます。最後に、共産党から提案された予算修正案に対し意見を述べますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-099"},{"speaker":"土井委員","kind":"質問・要望","question":"学校を転用して、地域要望の強い高齢福祉施設と幼保一元施設への改修など、今後の区政展開の方向をも示唆するものです。あわせて、新しい基本構想と第四次長期基本計画の策定の中に、我が会派の意向が反映されるよう望みます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"藤原委員","kind":"提案","question":"平成１９年度予算の基本テーマ、区民の要望と期待にこたえたものであり、品川区の特色と独自性を発揮したさまざまな施策が打ち出されています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-101"},{"speaker":"三村委員","kind":"質問・要望","question":"２００７年度一般会計予算では、廃止を求めた議員のＯＢ会である議員待遇者会への補助金が引き続き計上されました。こうした議員に関係する予算についても、聖域化せず、見直しをしていくことを求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/472478?Template=document&Id=888#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":120459,"voices":237}},{"id":"h19-20070326-10","meetingId":"h19-cm03","date":"2007年3月26日","dateIso":"2007-03-26","committee":"議会運営委員会","time":"午前１０時０３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"平成１９年請願第４号 政務調査費不正支出について真相を徹底調査し区民に報告を求める請願","agenda":"平成１９年請願第４号 政務調査費不正支出について真相を徹底調査し区民に報告を求める請願","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"審議をして、その後に意見陳述を受けるかどうかということですか。そのように諮ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"石田委員","kind":"意見","question":"請願書に基づいて我々がいろいろな意見・議論を交わした後、それを踏まえて意見陳述をしたいという申し出があったとき我々が諮るというのが今まで我々が行ってきた請願審査の流れだと思いますので、その流れで結構だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"確認","question":"あまり通常と言われると、通常ではないというように思いますけれども、そこの申し合わせとか、こういうふうにやるという確認はありましたか。通常と言われると、通常ではないと思いますけれども、こういう確認だということであれば、その確認を示していただけばいいですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"土井委員","kind":"質問","question":"皆さんがいろいろ判断するにあたってご意見を伺うというスタイルでやってきたと理解していましたので、それでいいと思ったものですから、発言しようとしたということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問・要望","question":"今回の問題は、私も含めて議員として非常に大きな問題として、区民の皆さんの中で扱われていると思います。今回、まず先に区民の皆さんの声を聞くことで進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"意見","question":"今、どういうふうにしようかという、いい方法が議論されていないのに多数決でやるというのは少し乱暴です。最後になって、やはり必要ないとなったら、またせっかく意見陳述の希望があるのに背いてしまうことになりますのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"南副委員長","kind":"質問・要望","question":"やはり、それが直接意見を述べていただいて、やはり昔のように初めに聞いていくことを大事にしていったらいかがかと思います。今日は傍聴席いっぱいの方々が傍聴にお出でになっているわけですから、趣旨をきちんとしていただけるようにはからってほしいと求めました。","respondent":"須藤委員長","answer":"今までは委員長が話したように進めてきておりますので、意見陳述につきましては、最初にいただくことに賛成の方は挙手を願います。","id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、請願書に出されていない、ここに反映されていないいろいろな意見も出ているから、意見陳述の要請が出ていると思うんです。ですから、ぜひ皆さんにお願いしたいのですけれども、最初にお伺いして、それから審査に入るようにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"菊地委員","kind":"意見","question":"この請願理由の中に、会派として築舘議員は当時は幹事長でしたから、会派を離脱し自由民主党も離党するという申し入れを了承したということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"石田委員","kind":"質問","question":"それに対する法的な効果はないわけですから、ここでその方が辞職をしなくてはならないというのは、現在の法的な部分ではないわけです。今のお答えになっているかどうかわかりませんが、そういう制度があるわけですから、辞職についてはそういう考えでいます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"菊地委員","kind":"質問","question":"ただ、テレビの中でも発言されているわけですから、政務調査費がどういう性質を持ったものかということを明確にとらえないまま使っていた。任期まで間があるわけですから、そこで今回の問題の一つ一つの内容について明らかにしていくことが絶対に必要だと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"石田委員","kind":"質問","question":"ルールとして１００条委員会でも、今は請願審査をしているわけですから、それに基づいて我々も対応をします。だから、隠しているということではないわけですから、すべてお出ししてやっているつもりです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"不正使用について真相解明を議会として行ってほしいというのは、今、こういうことについて明確に論議をすることが必要だと思うんです。議会についても道義的責任として明確にあるわけですから、ぜひ請願の三つの項目について取り入れていくという論議を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"土井委員","kind":"質問・要望","question":"要するに、ここでの正式な答えになるのではなかろうかという思いを持っているものですから、それを目指してほしいと求めました。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"宮崎委員","kind":"意見","question":"今の石田委員の発言で確かめておきたいのですけれども、真相究明というのは１００条調査委員会も含めて会議体の中でやるべきだということです。そのための会議体をやるという認識があるのかどうか、そこのところを聞いておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"土井委員","kind":"質問","question":"議会としてのルールとしての会議体をどうつくっていくかというのは、また別な議論をしていかなければならないと思います。そういうものをつくるかつくらないかというのは、我々の権限の範囲と比べてもなかなか難しいのではなかろうかということを申し上げただけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"石田委員","kind":"質問","question":"話を戻すような話をしているけれども、また我々全会派が取り組んだ部分、逆に真剣に取り組まれていなかったのですかということにもなりかねないです。その前に段階があったわけですから、それをすべて真剣に取り組んでいないとか、特別委員会でも設置できるわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問・要望","question":"真剣に議論してやってきましたけれども、本当にそれが再発防止にかみ合った対策なのかどうか、それは真相を調べなければわからないです。どのような手口でもらってきたのか、そこのところはどうですか、わかっている範囲で説明してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"石田委員","kind":"質問・要望","question":"よく話を聞いていただきたいけれども、我々は検察でも警察でもないわけですから、地検でも何でもない。違う場面で検察なり何なりが動くなら、それはその場で明らかにされる話でしょうということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問","question":"それが十分かどうかを調べるための真相解明じゃないですか。石田委員がこの場ではなくて別な会議体だということであれば、その会議体を設置することに自民党は賛成なんですかということを聞いているのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"中島委員","kind":"質問・要望","question":"確かに、私も区民の方からいろいろ話を伺っていると、やはり視察費用の透明化、どういうところに目的があって、どういう使い方をしたのかとか。当然、添付した領収書がしっかり明確になっていくというのも大事であるし、そういったことを求めているのが請願ではないのかなととらえているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"特に、築舘議員は２００万円を不正に領収書を偽造して受け取ったと認めていますから、どういう手口だったのか。諸活動というのは、一体何なのか、自民党は調査したのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"石田委員","kind":"意見","question":"公の場でも当該議員、原（雅）議員も含めて自分のお考えを述べていらっしゃるし、事実もお認めになっているということであります。それだけは言っておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"中島委員","kind":"質問","question":"一つ、質問したいのですが、今の辞職勧告決議という話が出たんですが、これは法的効果というものはどうなのか尋ねました。","respondent":"市岡区議会事務局長","answer":"昭和２６年の少し古い行政実例ですが、１１２条の議会の議決すべき事件には該当しない。なお、機関意思の決定としても、つまり議会の意思決定としても適当ではないという行政実例があります。","id":"exchange-024"},{"speaker":"菊地委員","kind":"質問","question":"やはり、そういうコメントをしているわけですから、その辺はどうでしょうか。〔「同じことだ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"菊地委員","kind":"質問・要望","question":"自分は政務調査費で行ったのは視察だと言っているわけですから、中身を一つ一つ明確にしない限り、新たに同じことが起こることを防げないはずです。そこはやはり明確にしていただきたいんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"石田委員","kind":"意見","question":"真剣に取り組んだ中で、意見を述べさせていただいて、一つの改善策が出てきている。個々のことがどうだという立場にも、そういうつもりもないですし、その中できちんと皆さんにご報告もしているつもりでありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"菊地委員","kind":"質問","question":"一つ一つの問題点が明確になっていかない限り、やはり同じ流れがつくり出されていくというのは明確なのではないでしょうか。石田委員がおっしゃっている１００条委員会があればということですから、そういう委員会をきちんと設置することは必要だと思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"個々の例の積み重ねなんですから。原（雅）議員は会派に返したと言うけれども、会派はどうしたのですか、そこのところは何かありますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"石田委員","kind":"意見","question":"会派としては、個々に１カ月ごとに収支報告まで会派としてはホームページに載せていこうと、会派としての改善策を出させていただいたわけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"南副委員長","kind":"確認","question":"１月２５日のホームページには、その後のホームページを確認しても、全然具体的なところは書かれていないんです。そこを具体的に説明してほしいと聞いているわけですから、きちんと答えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"石田委員","kind":"意見","question":"ご本人からの申し出があって、それに対する対応をさせていただきましたというのは、会派としてホームページにも載せていただいております。政務調査費は会派として受けておりまして、同じことの繰り返しになるので、私どもとしてはそれに対するお答えはできていると考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"宮崎委員","kind":"質問","question":"今の私的な流用だったのかどうなのか、私的な流用はだめだということなのかどうなのか、改めて伺いたいと思います。私的流用がだめなのかどうなのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"石田委員","kind":"質問・要望","question":"請願審査をして、最初からずっとそういう話ですけれども、何度もご説明をしているとおりでありますので、ご意見はどうぞ言ってください。その部分についてのお答えは同じことを何度をしておりますので、繰り返しになるようなことはやめてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"宮崎委員","kind":"意見","question":"私は逆だと思うんですけれども、逆に今の議論を聞いてどう思うかということも含めて、やはりしっかり請願者の意見を聞くことが必要だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"土井委員","kind":"質問","question":"最初に議論をしてきた経緯もあるものですから、その意味では今の状況では時間的にもきつさがあると思います。したがって、特段、今の状況の中では、先ほど来からの議論も踏まえてもよろしいのではないかと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"菊地委員","kind":"意見","question":"今、中身が伝わっているとおっしゃいましたけれども、自民党の発言の中で請願の趣旨に沿って説明があった、論議があったとは到底思えないのです。やはり、きちんと請願者の陳述を聞くべき中身があると私たちは思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"宮崎委員","kind":"意見","question":"当然、説明があってしかるべきだと思いますし、それがないというのは非常に残念だと思います。ほかの会派でも返したけれども、説明がされていないというのは、指摘しておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"中島委員","kind":"意見","question":"印刷代ではどこに何部配られてどういう印刷をしたのかとか、書籍は何を買ったのか、私は問題だと考えています。それだけ申し上げておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/148794?Template=document&Id=5126#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":21052,"voices":71}},{"id":"h19-20070604-6","meetingId":"h19-cm06","date":"2007年6月4日","dateIso":"2007-06-04","committee":"区民委員会","time":"午後４時３５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"番目、事務事業概要","agenda":"番目、事務事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"介護とのバランスを目指していると伺っているんですが、どういうふうに、聞きたいと思いました。１１ページですか、その原因をどのようにつかまれているのかというのを、ちょっと知りたいと思います。","respondent":"鷹倉区民課長、高濱生活安全担当課長、金子産業振興課長、原国保年金課長","answer":"平成１７、１８年度はほぼ同じという内容になります。平成１６年度から１７年度でちょっと下がっているわけですけれども… 正確な助成先については、後ほど、確認した上でお答えさせていただければと思います。五反田と武蔵小山の商店街において、助成をして… 次世代育成支援対策推進法ができまして、３００人以上の事業所については、届出なければならないとなっております。私どもの事業の趣旨は… 合計でいきますと、平成１８年度で、対前年０.０６ポイントの増です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"そのカメラから得た情報といいますか、それをどういうふうに防犯対策に生かしているのかというのを、ちょっと具体的に知りたいと思います。滞納の悪循環といいますか、それを解消する一番の根本策になるんじゃないかと思うんですが、そこら辺の考え方はいかがか尋ねました。","respondent":"原国保年金課長、高濱生活安全担当課長","answer":"今年でありますと３万５,１００円ということで、７割減額、５割減額というような制度で実施しております。激変緩和ということで、経過措置を設けしていますので、そういった中でご理解をいただきたいと考えています。設置されている防犯カメラの運営についてのご質問ですが、管理主体であるまちの団体のほうで、管理運営要綱をつくって運営していただいています。","id":"exchange-002"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"その後、ご意見が出ていないかどうか、ちょっとその辺をお伺いしたいのが１点です。１０年前にさかのぼって、品川区の今までの事務のかかわりというんですか、ちょっとお伺いしたいんです。","respondent":"高濱生活安全担当課長、金子産業振興課長、原国保年金課長","answer":"２点目、皆様からお声を聞いておりますが、防犯の面ではあえて要望という形でのご意見は伺っておりません。３点目… この検討のメンバーに考えているのかということですけれども、あるいは企業にかかわる方、それから地元の商店街の方も委員として考えております。現在… 区のほうでも、そういった調査の中で、必要とあれば協力しながら実施していくと考えているところです。","id":"exchange-003"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"１年とか、手だてがいろいろあると思うので、していただきたいなと思っています。国のほうは、もう廃棄の指示が出ているとか、そういう話もちょっと聞いているんですけれども、その辺、どうなんか尋ねました。","respondent":"原国保年金課長","answer":"５年の保存とか、５年経てば、通常の文書と同じように処分するです。それは大事にとっておきながら、これからの調査の中で、協力できることについては協力していくという考え方です。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"確認","question":"これは区から、この施設に対して、利用者の人数分の経費を負担することになるんですか。金額的には、どのぐらいか尋ねました。","respondent":"鷹倉区民課長","answer":"三つの施設は３部屋ずつ。それぞれの施設の借上料と、近畿日本ツーリストに受付代行業務、合わせて４,０００万円ちょっとという形になっております。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ということは、各ホテルに３部屋ありますけど、使わないときも、借上料として一定金額を払うという形になるんか尋ねました。","respondent":"鷹倉区民課長","answer":"今回、借上型という形をとっておりますので、そういう形になります。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ちょっと区のホームページの中の予約件数を見ていて、まだかなり空き室もある。７月あたりでも土日は入っているけれども、ぜひ、有効に使っていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいんですが、その中の国保年金課という窓口があるわけですから、そういったことも含めて情報を提示していただければありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"認証されたのが平成１６年で、３年に１度更新ということなんですけれども、どこまでの範囲ですか。４１ページで、それを、区側としてはどう分析しているのかというのをお聞かせいただきたい。","respondent":"田村環境課長、島袋品川区清掃事務所長、秋山資源循環推進課長","answer":"ただ、その学校を除いても、先ほど、事業概要でご説明したように、学校ＩＳＯというような別の取り組みで、内容的に取り組んでいるところです。… 先ほど資源循環推進課長が説明しましたように、平成１７年７月から、その影響が強いんです。一番大きいのは、先ほど申しましたように… 平成２０年度の本格実施と書いてありますのは、世帯数で１５％、モデル地区をやるです。","id":"exchange-009"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"５３ページで、問題なしですからご安心くださいというご答弁があって、私はとても安心できないところなんです。特にサーマルリサイクルなんかは、どう考えていらっしゃるのかというのを、ちょっとお伺いしたいんです。","respondent":"岩崎環境清掃事業部長","answer":"それから、ダイオキシンですが、これは一部事務組合の事業でありまして、検証作業を、昨年度２回実施いたしました。それからＣＯ2と可燃化、分別変更との関係ですが、そこから出てくるＣＯ2というのはやむを得ないものであるというふうに考えております。","id":"exchange-010"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"この地上からなくしてしまうというところと、ＣＯ2の排出が、微増ながらも増えるということですよね。広い意味での対策をしていただきたいなと思うところで、一緒にあわせたところで考えていただきたいなと思うんですが、ご意見をいただきたいんです。","respondent":"岩崎環境清掃事業部長","answer":"今、述べたとおりで、私は、環境も清掃も所管している立場から、ＣＯ2は、京浜島で燃やしているものを、きれないプラスチックに限りますけれども、それをリサイクルするわけですので、ＣＯ2は減るというふうにご理解をお願いしたいと思います。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"確認","question":"確認させてもらいたいと思うんですが、中継作業所に５億円近くかかっている中で、他区の分担金があるんでしたっけ。それをちょっと忘れたので。","respondent":"島袋品川区清掃事務所長","answer":"一応、各区の負担金はありません。区のほうの持ち出しなんですけれども、実際は財調で補正されています。","id":"exchange-012"}]},{"id":"topic-02","title":"番目、報告事項","agenda":"番目、報告事項","exchanges":[{"speaker":"稲川委員","kind":"質問","question":"これは基本的に国がやったものに基づいてつくったものなんか尋ねました。","respondent":"斉藤防災安全担当課長","answer":"さらに、区市町村がつくる場合は、東京都知事の協議を受けなさいということになっておりますので、国のほうから段階的に落ちてきていると。その際に、モデル計画というのが示されてきておりまして、基本的には、そのモデル計画の指針にのっとった計画という形になっております。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"どう攻めてくるとかという具体的な事例を示せないような状況ですけれども、憲法第９条で、ほんとうに身の毛がよだつ思いをしたんです。どのように行われるかというのを、わかる範囲でいいんですけれども、ちょっと教えていただきたいなと思います。","respondent":"早津区民生活事業部次長","answer":"その対応措置が法制化されていなかったということを受けまして、万一の事態に対してどういう対応をしたらいいのかということで、自治体までにおりて。訓練については、具体的なものは、今後、検討します。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"日米安保に基づいているわけですから、やっぱりちょっと違和感があるなという、私の思いはあるんです。現時点でのお考えはどうか尋ねました。","respondent":"早津区民生活事業部次長","answer":"というのは、２番目のところにある、大規模テロ等ということで、武力攻撃と分けて書いてある関係でのお尋ねかと。武力攻撃の2)でゲリラ・特殊部隊による攻撃というものもテロになる可能性があるわけで、どうしてなのかと、そういうことではないんですか。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"非常に理解しにくいということなので、今のこの法律を具体化する上で、その定義をどういうふうにしているのかなというお考えをお聞きしたいということです。","respondent":"早津区民生活事業部次長","answer":"一つのテロの、殺人にかかわらず、起こるかと思うんです。１番の武力攻撃事態ということで、大規模テロ等といったジャンル分けをしているというふうに認識しております。","id":"exchange-016"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"１ページ目を見ると、多分、後段の半分しかない。しっかりととらえて、区の計画が今後どうなるのかというチェックもしたいので、これは時間をかけてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の委員長のお話の中で、報告はわかったんですけれども、議論は区民委員会でしないというお話か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"稲川委員","kind":"質問","question":"それは防犯防災上もそうですし、やっぱりこういうのは大切だと思っています。さあっと見ただけでも疑問に思う点がいっぱいだと、私も思うんですが、いつごろお配りなるんか尋ねました。","respondent":"早津区民生活事業部次長","answer":"４月から、区民生活事業部のほうに移管してきましたのは、この計画を作成した段階で、今度は実施ということになってまいります。字句の修正を除いては差はないと考えておりますので、その辺の議会経過も含めまして、進めていただければと考えております。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その上で、この計画が東京都の承認をもらって品川区がつくったんですから、これは流れの中で、これはもう出していいと思うんです。本来は、周知しているんだけれども、なかなかわかりにくいから、その辺をわかりやすく考えていただければなと思うんです。","respondent":"田中区民生活事業部長","answer":"平成１８年度中に、区市町村でこれをつくって、法に基づいて実施していくということになっております。行政としての継続性というものも難しくなりますので、今回は、こういう取り組みをしていますというご報告をさせていただきました。","id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"確認ですが、総務委員会の中間報告をされたのが、いつの委員会なのか、後でも結構なので、教えていただきたい。〔「会派が知っている」と呼ぶ者あり〕それは個々に一人一人ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/598842?Template=document&Id=2486#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":61388,"voices":135}},{"id":"h19-20070604-7","meetingId":"h19-cm06","date":"2007年6月4日","dateIso":"2007-06-04","committee":"厚生委員会","time":"午後１時０３分～午後４時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"宮崎副委員長","kind":"意見","question":"副委員長の共産党の宮崎です。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"須藤委員","kind":"質問・要望","question":"自民党の須藤です。何もわかりませんので、よく教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成１８年度のまとめはいつ頃できるのかということと、ぜひ報告をしていただきたいと思うんですけれども、そのことについてお聞かせください。予算の割合なども含めて、ぜひこの部分について改めてどこかで報告をいただきたいと思うんですが、そのことについて説明を求めました。","respondent":"上山介護保険担当課長、高橋障害者福祉課長","answer":"６月８日の介護保険制度推進委員会に運営状況を報告する予定ですので、今、準備作業を進めている状況にあります。ほかの特別会計と同じような形で考えたいと思いまして、平成１８年度の第三期からにつきましては… 先ほどの地域生活支援事業ですが、移行時期に８月の委員会で報告されているかと思います。したがいまして、事業内容につきましては、それぞれのところで報告は済んでいるかと思いますので、よろしくお願いいたします。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一昨年の１０月から施設の負担等が大きく変わりましたし、またしくみが大きく変わった部分の実態があると思うんです。傍聴者が意見を言うことはできませんし、厚生委員会に資料を示していただいて報告をいただきたいということを要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須藤委員","kind":"質問・要望","question":"教えていただきたいんですけれども、これは品川区内全体の結果という認識でいいのか。今、６５歳以上６万５,０００人という中で、要支援が０.７％、要支援１が２１.０％、これが現在の品川区の人数として把握していいのか。","respondent":"蓼沼高齢福祉課長","answer":"ご指摘ありましたように、これが区の認定者の状況です。","id":"exchange-005"},{"speaker":"須藤委員","kind":"質問","question":"もう少しボリューム的に上げていかなければいけないだろうというような考え方になってくるわけですが、そのあたりのご見解。そのあたりのチェックの仕方はどの程度、そのあたりはどのように考えてチェックされているか、そのあたりを説明を求めました。","respondent":"蓼沼高齢福祉課長","answer":"３７ページのものは審査の結果の内訳ですので、新規の方あるいは更新の方含めて延べ件数がここに掲載されているものではないかと考えます。年を通じて適切に定期的に指導している状況で、全体としては、保険者の指導を通じて保険料請求の適正化について努めている状況です。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本年度は３回ぐらい予定されているということですけれども、３回の予定の内容と時期について、わかっていたら教えていただきたい。決算額を見ると、平成１９年度は９０５万円となっているんですけれども、この違いはどういうことなのかお聞かせほしいと求めました。","respondent":"高橋障害者福祉課長、蓼沼高齢福祉課長、上山介護保険担当課長","answer":"１点目の手引きにつきましては２年に１回ということで、今年度作成の予定です。区独自の軽減策についても、４月から実施しておりますので、当然… これにつきましては、既に実際に動いております。認知症の方を専門的な検討が必要だと判断されたケースについて… ２月に予定しております委員会につきましては、平成２０年度の予算等を含めまして、今のところ予定しています。","id":"exchange-007"},{"speaker":"宮崎副委員長","kind":"質問","question":"生活保護のところで伺いたいのですけれども、品川区は１１.６％から１１.４％に落ちていますけれども、全都では上がっています。この要因といいますか、この辺はどのような評価をされているのか伺いたいと思います。","respondent":"志村生活福祉課長","answer":"平成４年以降統計を取って初めて開始より廃止が上回ったということがありますので、私どもの自立の取り組みも功を奏してきたのかなと考えています。","id":"exchange-008"},{"speaker":"宮崎副委員長","kind":"質問","question":"生活保護のところで気になっている点が１点あるんですが、法外援助の件で伺いたいと思います。一方では生活保護の場合ですと、服の支給はこれだけですという逆をどのように考えているのか、そこのところはどうか尋ねました。","respondent":"志村生活福祉課長","answer":"お尋ねの件ですけれども、実は昨年度から私どものほうでも対応について検討してまいりました。ですから、これはあくまでも区の単独事業ですので、私どもは法外援護の中にそれを新たに追加したです。","id":"exchange-009"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"２万円の上乗せというのは、現実はもう少し高いのが現状のようなので、やはりいろいろ調整していただければと考えています。これも要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-03","title":"続きまして、報告事項","agenda":"続きまして、報告事項","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"確か、その辺のしくみとなぜ指定管理者ではなくこのような形になったのか、もう１回説明してほしいと求めました。個人情報保護の規定はありますけれども、情報公開の規定について書かれていなかったので、規定についてあるのかどうか教えてほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"少子高齢化に対応するということで、高齢者の福祉施設、複合的な施設を既存の学校の校舎を改良して実施するという新しい事業です。このような施設運営が適するのではないかということで、今回、こういうような民設民営方式で実施しようということにしたものです。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"新築は自治体も対象になるけれども、改修のほうがだめだということなんですけれども、ケアハウスの制度だったらばなれるんでしょうか。高優賃というのは、多分初めてなんじゃないかと思うんですけれども、そこら辺の制度の違いについてもちょっと説明を求めました。","respondent":"蓼沼高齢福祉課長","answer":"当初はケアハウス制度ということも検討したわけですけれども、避難路を２方向に確保しなくてはいけないというような基準が、縛りがかかってきます。その中で高優賃というものを考えたときに、そういう福祉施設のような２方向避難路確保というような、そういう縛りがございません。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう１つ、実際の利用料がどういうふうに安くなっていくのかという、そこのところについても１つ教えていただきたい。","respondent":"蓼沼高齢福祉課長","answer":"そのほかに、所得に応じて利用料が設定できるというところがあります。防災対策につきましては、そういう施設の中の区画ごとに防火扉を設置するという形で防災対策には万全な策を講じていきたいと考えています。","id":"exchange-013"},{"speaker":"宮崎副委員長","kind":"意見","question":"そこら辺の説明はどうなっているのかということと、身体拘束禁止だとか、こんなのはそういう意味では当たり前だと思うんです。一体どういうふうにしてやりくりができるんだろうなと非常に疑問なんですけれども、説明できるところをわかりやすく説明してほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"実際に現地での説明会のときは二十数社、見学会、説明会に来ております。これは、そういうようなタイプ、２０m2ぐらいのものから３０m2後半のものまで多様に整備するというような提案の内容になっております。","id":"exchange-014"},{"speaker":"宮崎副委員長","kind":"質問","question":"そういうところですから、やっぱり区内の事業者からも非常に不満があります。ですから、事業者も含めて信用を失っていくんではないかと、私はそういう心配を持っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/928192?Template=document&Id=3172#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":55947,"voices":91}},{"id":"h19-20070604-8","meetingId":"h19-cm06","date":"2007年6月4日","dateIso":"2007-06-04","committee":"建設委員会","time":"午後１時０３分～午後３時１１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"の１番目、幹部職員紹介","agenda":"の１番目、幹部職員紹介","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"自民党の石田です。どうぞよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問・要望","question":"特別委員会というところはわかるんですが、先ほども説明はありませんでしたけれども、この辺について少し整理をしていただきたいなと思うんです。それは所管は向こうだからというようなことにならないのかどうなのかというところを少し確認させていただきたいという２点をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"井上委員","kind":"提案","question":"そこまで特別委員会の調査事項が第１回を待たずに決められて、なおかつ、ここにそういう提案が来るというのはおかしいと思うんです。委員長同士の協議が必要であればしていただきたいんですが、そういう仕切りをしていただきたいと思うんですが、それについてはいかがか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"井上委員","kind":"提案","question":"そのことについて調査を委員会としてすべきだという提案があった場合には。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"現状をお聞かせいただきたいのと、品川区としてＣＯ２削減というのはどういう考えがあるのか、内容的なところをお伺いしたいのが１点目です。それと概要の話でもう少し伺いたかったのが、いわゆる今期１年間、そこを何かお考えがあれば教えていただけますか。","respondent":"岩田まちづくり事業部長","answer":"物の考え方として、仕事をするわけですから、そういった人間が生きていく上において都市はＣＯ２を出さないということはできません。それから１年間当委員会でご議論していただくことは、私どもとすれば、私どもの仕事に生かしていければと思っています。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"どれぐらいのＣＯ２が発生しているのか、そういう目標設定があるのかどうか、考え方を教えていただきたい。３つ合わせて合計幾つになるのか、この整備地域の中、この範囲内だけで合わせて教えていただけますか。","respondent":"青木都市開発課長","answer":"調査を進めておられまして、年間のＣＯ２の排出量が床面積当たり大体１００kgを超えるであろうというのが今、一般的な建物だそうです。それを例えば１割とか２割とか減らせるようにということは議論はしておりますけれども、より適切な指導をしてまいりたいと考えております。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"中地区の工事現場が始まって、あそこに２棟建って住宅ができますけれども、一体幾らぐらいのマンションができるのかなと見ていて感じたんです。販売価格はこの前の話の中で７,０００万円、適当だという話が出たけれども、販売価格というのはどういうふうにお考えなんか尋ねました。","respondent":"岩田まちづくり事業部長、青木都市開発課長","answer":"私が先ほどお答えしたのは、現実に個々の再開発には、そういうエネルギーのことを考えた対策というのは個々でいろいろとっておられます。コージェネレーターを使ったり、そういった仕組みもやっておりますし… アートヴィレッジ大崎が５８３戸、日野学園が０戸、１,０８０戸ほど供給の実績があります。私どもで現在報告を受けておりますものは、この大崎の６０ha囲んだ中では、さらに３,０００戸ほど住宅供給が予定されてあります。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"これがどういうニュアンスなのかよくわからなかったので、そこをご説明いただきたいなと思ったのが１点と、それと大崎周辺で４,０８０戸。販売価格というのはどう考えているのか、先ほど伺ったけど直接ご答弁がなかったので、教えていただけますか。","respondent":"岩田まちづくり事業部長、齋藤住宅課長","answer":"もう１つは、いわゆる４,０００万円から７,０００万円台、それからやはり駅直近のつくり方とはおのずとつくり方も違うんだろうと思うんです。したがって、場合によっては９,０００万円台というように価格が設定されて… 市場ストックのことですが、私どもで持っているのは平成元年以降、約３万５,０００戸マンションの戸数があります。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"ほんとうに一人ひとりの区民にとって必要な住宅と言えるのか、税金が投入されているわけですから、その点をちょっと伺いたいのが最後です。第２伊藤町と大井林町の都営住宅の廃止の問題で居住者の方々の不安の声が挙がっていますけれども、現状の区の考え方を教えていただけますか。","respondent":"岩田まちづくり事業部長、齋藤住宅課長","answer":"先ほど言いましたようにファミリー向け、ワンルームともにここ１０年、民間業者による建築というのは非常に行われてきております。共同部分とか、非常に税投入の効果としては優良な税の投入の仕方であると考えておりますので… 私どもはいろいろ陳情をいただきましたのできめ細かく対応させてもらっていますが、区として云々かんぬんということについて意見はございません。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"都道、公共溝渠等は３年間で来たけれども、区から働きかけるみたいな考え方があるのかどうかということがあれば教えてほしいなというのが１つです。これはもう確認だけさせていただきたいんだけれども、でも内容は聞くとそうだよというふうになるんだから、そこら辺のお考えを教えていただきたい。","respondent":"松代管理工事課長、伊勢住環境整備担当課長、阿部都市計画課長、片田建築課長、齋藤住宅課長","answer":"これにつきましては、企画部を中心に全庁的な計画を進めてまいります。区民への施設のあり方、そういったものを十分議論して位置づけていきたい… 促進期間が１０年ということになっていますけれども、この１０年間で成果が上げられるようにどうしたらいいかと今、研究しております。… 用途の問題ですけれども、確かにここに書いてあることは用途地域の基本的な考え方ですので、その辺は重大と当然のことながら考えてあります。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひ検討していただきたいなと思うのと、１点だけもう一度お聞きしたいのは道路なんですけれども、幹線道路でもある程度の。都道の部分でお考えがあれば教えていただきたいのと、ぜひひとつ、それは意欲を伺ったということだけにしておきますので。","respondent":"松代管理工事課長、岩田まちづくり事業部長","answer":"具体的に目の前にある身近な都道の管理ということで、続けてありました中央海浜公園等の管理と同様に、区がやるということは十分あり得ると思います。都市計画道路等を見ましても、今後の広いそういった視点等の検討… これは都道府県がきちっと管理をしておると、例えば区が都道の一部を区道として管理をするということは、これは法律上非常に難しいと思います。","id":"exchange-011"},{"speaker":"井上委員","kind":"意見","question":"２つあります。１つ、そういうところの連携というのは本当は実際どういうふうにはかって、説明をしてほしいと求めました。","respondent":"片田建築課長、松代管理工事課長","answer":"木造住宅の耐震化の支援事業の、実は４月の末に庁内の検討会、１０月に入りましてパブリックコメントを打ちたいということを考えております。１２月中に一応決定… ５カ年もしくは６カ年かけて今、順次意欲的に進めている中で商店街灯を設置しているものでございまして、これは計画の一環です。","id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"街路灯のところで、同じように道路のれんがづくりというか、旧東海道に合わせて南品川３丁目の最後まできれいにしているわけですよね。計画があるにもかかわらず、区民のお金を使ってやるというところでどういうふうな協議をしているのかなというのが疑問だったものですから、その辺。","respondent":"松代管理工事課長","answer":"新しい商店街灯をつけ、舗装も石畳にするといった区間でやっていますので、それを一緒にはできないように思うんですが。〔「やるのか、やらないのか」と呼ぶ者あり〕 そういう中で北品川地区と戸越銀座地区の２カ所が電線の地中化ということで両商店街が手を挙げられて、こちらも事業として進めているところです。","id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"ここには街路灯で手当をしましょうみたいな、そういう切れたまちづくりで、そのハード整備でいいんですかということが１つは問題にあると思うんです。その分こっちが余力をつけましたよみたいな地域の誤解もあるぐらいですから、そういう連携も必要じゃないですかということで聞いております。","respondent":"岩田まちづくり事業部長","answer":"青物横丁商店街が非常に高価な石畳を地元で設置されてまだそんなに、１０年ぐらいしかたっておりませんので、区も望んでいないわけです。そして決して連携をとらずにばらばらにやったということじゃなくて、十分連携をとってますけれども、こういうことです。","id":"exchange-014"},{"speaker":"中塚委員","kind":"確認","question":"中身じゃないんですけれども、今、それぞれ目を通して、改めて今日確認するということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"中塚委員","kind":"確認","question":"委員長から改めてこれをもう一回確認したいと思われる、その理由は何かございましたら。ちょっと理由があれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/325823?Template=document&Id=3878#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":40499,"voices":94}},{"id":"h19-20070604-9","meetingId":"h19-cm06","date":"2007年6月4日","dateIso":"2007-06-04","committee":"文教委員会","time":"午後１時０３分～午後 ３時１６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"大沢副委員長","kind":"意見","question":"文教委員会はいろいろと課題が多い、非常に重要なセクションだと考えております。一生懸命委員長を補佐し、また理事者の皆様方のお力添えを賜りながら委員会運営を進めてまいりたいと思いますので、よろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"山内委員","kind":"質問・要望","question":"自民党の山内晃です。この１年間、理事者の皆様とともに活発な議論をさせていただきたいと考えていますので、ひとつ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"金野委員","kind":"意見","question":"今年１年、大変にお世話になります。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そういう関係で耐震の問題も、あわせて担当の委員会として全体的なところをつかんでおきたいなと思うので、それもちょっとお伺いしたいと思います。それから、幾つかあるんですけれども、いいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"子どもたちの呼吸器の状況を、どういうふうになっているのかというのがもし具体的にあらわれていたら、伺いたいと思います。あそこの施設の周辺に、ここで言うのが適当かどうかちょっとわからないんですけれども、この機会に教えてほしいと求めました。","respondent":"市川庶務課長、古里学務課長、工藤品川図書館長","answer":"わずかではありますが、今申し上げた今年度設計を実施するものも含めて、平成２０年度の工事に回していくという予定です。この基本設計にあたりましては… 私のほうからは学校基本調査に係るぜん息児童の状況、それから学級維持制度について説明を申し上げます。中学校は今年度、適用はございません。私どももこちらの閉館にあたりましては代替という部分も検討したわけですけれども、そういった中で、なかなか不特定多数の方が出入りしまして。","id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"あまりこれ以上のことは質問するつもりはないんですけど、今の図書館もそれはそれで伺っておくということにしたいと思います。これだけの３００なり２８０なりの数をどういうふうに見るかということになるんだろうと思うんですけど、そういう認識を持つものでありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"この仕切り方について確認したいということと、まずそれぞれの課のところで他課との連携というのがいろいろ出ているんですね。他課との仕切りがある程度決まっていって、この部分は文教委員会で議論しようとか、そういうところがあるのかどうか確認したいんですね。","respondent":"市川庶務課長、富田生涯学習課長","answer":"連携事業というからには、連携する場面で、あるわけです。そのときに私ども教育委員会の説明だけでよいのか、あるいは補助的な何か説明をするのか、指示をいただいて対応させていただきたいと考えております。 実際のＰ連の研修会としましては、専門部研修会、幹部研修会、研究発表大会等々あります。そういったところを踏まえて、正副委員長ともよくご相談した上で、ＰＴＡ連合会のほうとご相談していきたいと思います。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"そういうのも私たちどんどん参加できるものなら、お知らせいただきたいなと考えていますので、よろしくお願いいたします。最後に指導課のほうで幼・保・小のところのくくりがどういうふうになっているのか。","respondent":"河野指導課長","answer":"幼稚園との絡みということでお答えしますと、管理職の選考、それから新規採用ですね。そういう部分については連携ということで、それから、一緒に作業を進めているという連携をしております。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"小学校、中学校の一貫教育もそうでしたけれども、垣根があるわけでしょう。今年の大きな大切なことではないかなと私は思うものですから、そこのところのかかわり方というのを、それだけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"山内委員","kind":"質問・要望","question":"私からは３つ質問をさせてほしいと求めました。この１年間しっかりと議論していかなくてはならないと考えていますので、その状況を教えていただきたいんですけれども。","respondent":"富田生涯学習課長、河野指導課長","answer":"これは全小学校で３年生と５年生を対象に、ＣＡＰワークショップを実施しているものでございまして、ＰＴＡでの委託事業として実施しているものです。… 子どもの学力向上にきちんと寄与しているのかどうかということをはかる物差しの１つとしても、活用させていただいたところです。こちらのほうの比較でも、中学生、小学生ともに都の平均はどちらも上回っております。","id":"exchange-010"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"２つお伺いさせてほしいと求めましたが、校長会なんかは代表が２名ということなんですが、それを１つお伺いしたい。それはこの状態でできるのか、それとも将来的にはどのようにこの流れをお考えなのか、聞かせてほしいと求めました。","respondent":"藤森小中一貫教育担当課長、市川庶務課長","answer":"９ページの件ですけれども、体育を専門に検討していく組織だとか、基本的には兼任をしているという状況ではございません。確かに昨今、今申し上げた平成１２年度の学校完全週休２日制が始まったと同時に、それらの子どもの居場所づくりということで始めた経緯があります。","id":"exchange-011"},{"speaker":"大沢副委員長","kind":"質問","question":"学力向上のために授業を開いていくという２つの階段の違うところにお話をさせていただきましたけれども、本区においては土曜日の学校の開校というんでしょうか、そういうお話というのはされているんか尋ねました。","respondent":"河野指導課長","answer":"あくまでも学校週５日制という理念のもとに編成されておりますので、品川区の各学校の教育課程そのものも、週５日を明確にしてやっているところです。","id":"exchange-012"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"１つだけ質問させていただきたいんですが、区独自で区立小学校４０校を巡回するスクールカウンセラーを１４名配置すると。もし両親に向けてだとしたら、スクールカウンセラーがそこの学校に行ったりするときに、どのようなご案内をするのかということを聞きたいんですが。","respondent":"河野指導課長","answer":"このスクールカウンセラーが相当長期にわたる継続したカウンセリングというのはなかなか困難な点もありますので。適切な対応について、学校がアドバイスを受けて、そのアドバイスを活かした対応をするというところで活用していくです。","id":"exchange-013"},{"speaker":"金野委員","kind":"質問・要望","question":"特別支援教育体制についてお伺いさせてほしいと求めました。介助員制度は今までどういった形で介助員の方を採用していたのか、見直しですから、お聞きしたいなと思うんですが。","respondent":"河野指導課長","answer":"ただ、そのような活用の仕方で発達障害の子どもたちとのかかわりを考えたときに、逆にそういう行為がずっと継続して行われることを考えたときには。","id":"exchange-014"},{"speaker":"金野委員","kind":"質問・要望","question":"この発達障害児のお子さんは今、ちゃんと病名がついてこのような形でお子さんがふえている現状なので、今お話しいただいたのをぜひ進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"１点だけ、適正規模の関係なんですが、２６ページに平成１９年度に設置しますとなっているんですが、この基本的な考え方というか、なぜこの検討会を設置するのか、何を議論する予定にしているのか、ここだけだと読み取りにくいので、その説明をほしいと求めました。","respondent":"古里学務課長","answer":"今あらゆる検討をしておりまして、教育委員会の中でも論議を進めなければいけないところです。これからは検討していかなければいけないですので、そういう方向で今、検討を進めているところでございまして。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"これからのものですから、いろいろな議論を活発にして、学校とはどうあるべきなのかということを検討していっていただきたいと思うんです。なかなか詳しいことがわかってこないので、教えていただける範囲のことで、これ以上のことは全然まだないんか尋ねました。","respondent":"古里学務課長","answer":"先ほどお話ししたとおり、詳細については別途ということでお願いをしたいと思います。現在のところ、論議の過程の中で、委員としてどのような方をお迎えするのかということも詳細を詰めてまいりたいと思います。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"１年とも２年ともこの検討期間は書いていないので、その期間をどのくらいの規模で検討していきたいと考えておられるのか、そこだけ最後に伺って終わりたいと思います。","respondent":"古里学務課長","answer":"そうしたものとの関連で区民意見の聴取を進めていくとすると、時間はかなりかかってくるような部分も出てこようかと考えています。そういう新しい状況も踏まえながら現在検討をしているというところで、ご理解をいただければと思います。","id":"exchange-018"},{"speaker":"若林委員長","kind":"提案","question":"ないようですので、今後の委員会運営につきまして、私のほうからご提案をさせてほしいと求めました。〔「異議なし」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/120587?Template=document&Id=4602#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":37458,"voices":68}},{"id":"h19-20070604-5","meetingId":"h19-cm06","date":"2007年6月4日","dateIso":"2007-06-04","committee":"総務委員会","time":"午後１時０３分～午後２時４５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"の１、幹部職員紹介","agenda":"の１、幹部職員紹介","exchanges":[{"speaker":"伊藤委員","kind":"意見","question":"自民党の伊藤です。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"の２、事務事業概要","agenda":"の２、事務事業概要","exchanges":[{"speaker":"菊地委員","kind":"提案","question":"その期間、それに対する意見というのはどういうふうにこういう場合取り入れられていくのかというのを教えていただきたいんです。危機管理室のところで、それから、防災課に移管をするということの経過というのか考え方というのをもう少し教えていただきたいと思うんですとの意見を述べました。","respondent":"福島長期計画担当課長、桑村危機管理室長","answer":"基本構想ならびに長期基本計画の策定ですけれども、今年度６月からですけれども、策定委員会を設けまして検討に入ってあります。総務委員会からの意見、さらにはパブリックコメントをとる予定ですし… 実際、その意味では、危機管理室より防災課のほうが適当だろうという判断で防災課のほうに４月に動かしたということです。計画につきましては本日、区民委員会のほうで実際上の計画について報告させていただいているところです。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、この策定をされた時点で、この協議会そのものというのはこれで消滅をしたものだというふうにとらえていていいんでしょうかね。危機管理室との関係でちょっとそこを。","respondent":"桑村危機管理室長","answer":"やはり年々年々考え方も違ってまいりますし、計画自体はまた練り直さなきゃいけないというふうに考えてあります。その意味で、また協議会のほうで計画自体をもう一遍検討していただくときには、その辺の検討をしていただくのが適当だろうです。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"最後に、そうすると協議会そのものは生きていて練り直さなくちゃならないときというのは、また総務委員会にかかってくるという考え方でいいか尋ねました。","respondent":"桑村危機管理室長","answer":"協議会自体の今後の運営も防災課が基本的に主体にやってまいりますので、委員会の説明は区民委員会でお願いしたいというのが私どもの考えです。ですので、必要があったときには区民委員会のほうにかけさせていただきたいと思います。","id":"exchange-004"}]},{"id":"topic-03","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"これが施行されて早くやりなさいよという話になっていますよということですから、そこはどういう基準でやって。後づけで変なのを出してきて、もうしゃくだし、そういうのも含めてこれは何ですかということをお聞かせいただきたいと思うんです。","respondent":"宍戸施設担当課長","answer":"したがいまして、現在、災害対策拠点として重要な施設であるＩｓ値０.７５以上になるというふうなことを目標として耐震補強をしようとしています。","id":"exchange-005"},{"speaker":"土井委員","kind":"意見","question":"学校のときはそれが０.７でしたっけ、また今０.７５だから、何がどうしてどうなっているのということを聞きたいわけです。しばらくしたら、上がってきたから０.８にしようなんていう話になってきたらどうするのかという話になりますから、もう１回お願いしますとの意見を述べました。","respondent":"宍戸施設担当課長","answer":"今の０.７５につきましては、１００％と言われると厳しいものがありますけれども、私どもとしてはこれで大丈夫だろうというふうに思っています。","id":"exchange-006"},{"speaker":"土井委員","kind":"意見","question":"それにはえらい金がかかるわけで、その合理性の中でのせめぎ合いだろうと思うんですね。その意味での０.７５というのは、法で決まっているわけではないのかどうかということだけ聞かせてくださいとの意見を述べました。","respondent":"宍戸施設担当課長","answer":"法で定められているのはあくまでも告示ですけれども０.６以上というふうなことが、法律で言われているものでございまして、０.７５というのは推奨している数値です。","id":"exchange-007"},{"speaker":"土井委員","kind":"意見","question":"とある企業では安全率を、最後によくよく見たら３倍ぐらいの強度になっているというばかなことをやっているという結果があったものもあるわけですね。いずれにしろ、今のところこれだというならこれでやるしかしようがないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"原委員","kind":"質問・要望","question":"これは約３４億円ということなんですけれども、それがこの金額の中の全体の中に入っているか入っていないのか、お聞かせほしいと求めました。","respondent":"中島経理課長","answer":"概算工事全体で約３４億円でございまして、区分所有というお話がございましたけれども、区分所有の率でもってこの工事費を東京都と国のほうで負担してもらうということです。","id":"exchange-009"},{"speaker":"原委員","kind":"質問","question":"ですから、まだかちっと決まっていないでしょうから、お聞かせほしいと求めました。","respondent":"中島経理課長","answer":"かつて平成１０年ぐらいに出張所の移転の問題がございまして、私どもつい最近、法務局でその辺の話を伺ってまいりました。向こうの課長からは、内訳を早く教えてくださいというようなお話もいただいておりますので、私どもとしては安心しているです。","id":"exchange-010"},{"speaker":"伊藤委員","kind":"確認","question":"真ん中が議会棟、第三庁舎ということでいいかという確認、参考資料の上のほうですね。ですから、一定の損傷の可能性が高いというリスクを抱えたままでこの案を選んだ理由というのは理解できないんですが、ご説明をお願いしたい。","respondent":"宍戸施設担当課長","answer":"図面の見方ですけれども、一番左側が第三庁舎も含めてすべて免震構造で。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、もう一つ確認したいのが、なぜケースＡのほうにしなかったんでしょうかね、この第三庁舎を。同じやるのであれば、そちらよりよいと思うんですが、あえてこの第三庁舎だけを耐震構造にしたということをもう少し説明いただきたいんですが。","respondent":"田中総務部長","answer":"Ｃを私どもで検討させていただいたわけですが、Ａならば免震というのは、地震対策から言えば有効だというふうに考えております。ただ、それから３.５年という工期がかかるというところが非常に問題がございまして、設計をした会社のほうにいろいろな検討をさせました。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"その辺具体的に教えていただきたいのと、もちろん地震に対するものですから、そういった工事なども含めて耐久年数を上げていくということは考えられないのかというふうに思うんですけれども。","respondent":"中島経理課長、宍戸施設担当課長","answer":"東京都が約２１.２５％、残り７６.４９％が品川区です。これは持ち分の割合によって定められた率です。 特に免震工法ということで、耐用年数を長くする、設備の更新ですとかこういった工事はまた別途必要になるです。ただ、あと２０年から２５年ぐらい使い続けることは可能だというふうに考えているところです。","id":"exchange-013"},{"speaker":"浅野委員","kind":"質問・要望","question":"環境にやさしい、またそういう付近の住民になるべく負担とかそういう迷惑がかからないような方法をとっていただきたいんですけど。３年間そのまま規制をするということはないかと思うんですけれども、お願いという形ですけれども、これはお願いということであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"林委員長","kind":"提案","question":"それ以外にも条例提案とかいろいろありますけれども、委員会の活性化という点から、委員会として積極的に取り組んでいかなければならない。皆さん方とあるいは理事者からの意見、そういう所管事務調査ということについてのご提案を、まずはほしいと求めましたけどとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"土井委員","kind":"質問","question":"どこがやるのかということになったときに、やはりもともとこの総務委員会の事務事業ですから、去年までやってきたものを。これは我が品川区が前区長をはじめとして議会側も含めてこれの取り組みをがっちりとやってきたわけですから、調査をしていくべき。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/495406?Template=document&Id=1750#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":31793,"voices":105}},{"id":"h19-20070605-14","meetingId":"h19-cm06","date":"2007年6月5日","dateIso":"2007-06-05","committee":"行財政改革特別委員会","time":"午後１時０３分～午後２時５１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"武内委員","kind":"質問","question":"（２）番のほうの指名競争入札のところの例で、工事案件では１３０万円を超えるものが対象とか、地方自治法のこの中で定められているという理解でよろしいのか尋ねました。","respondent":"中島経理課長","answer":"基本的に地方自治法で定めている部分と、それを受けまして地方自治法の施行令で、例えば随意契約の１３０万円以下の金額とか、具体的に施行令のほうでそれを受けて実施しておりまして、さらにそれを品川区の契約規則で受けてやっているという、体系的に整理されたものです。","id":"exchange-001"},{"speaker":"武内委員","kind":"質問・要望","question":"それから、この２番の契約方法の４種類を今挙げていただいたんですが、例えば品川区の昨年実績でも結構なんですけれども、大体の割合、例えば（１）番が何割ぐらいという、（４）番は多分ないと思うんですが、その辺のことを大体で結構なので、わかれば教えていただきたい。","respondent":"中島経理課長","answer":"工事案件で申し上げますと、随意契約、これは見積もり合わせ等を含めまして、全体の約４８％です。それと、指名競争入札、こちらが３４％、制限付き一般競争入札、これが１８％という構成になってあります。","id":"exchange-002"},{"speaker":"武内委員","kind":"質問","question":"４８％ということで半分近くが随意契約という形になっているんですけれども、この１３０万円以下のものが占めているのか、どうか尋ねました。","respondent":"中島経理課長","answer":"工事案件でいいますと、約２５０件ぐらいあるわけですけれども、その中でいわゆる金額で１３０万円以下のものが約２３０件あります。そこの業者でなければできないものとかいろいろあるわけですけれども、そういったものが３３件ということで、ほとんどは金額でやられているです。","id":"exchange-003"},{"speaker":"武内委員","kind":"意見","question":"では、ほとんどは１３０万円以下なので随意契約というような認識をします。今年の４月から試行実施されたというお話があって、さまざまな要件があると思うんですけれども、どの辺まで条件をつけてやられているのかとの意見を述べました。","respondent":"中島経理課長","answer":"例えば、１,０００万円で入れたら８０点だとしますと、９００万で入れたところが９０点とか、要するに、安いほうが点が高くなるということです。あるいは、先ほど申しました価格の点数と技術の点数を合計して、一番高かったところと契約するというシステムになっています。","id":"exchange-004"},{"speaker":"武内委員","kind":"質問","question":"どうも何か給食の時間が結構頻繁に遅くなってしまう、そういうようなことをちょっと聞きまして、苦情まで行かないんですけれどもお聞きしたんです。例えばそういうことも価格とバランスというんですか、そこに条件として、その辺はどうなんか尋ねました。","respondent":"中島経理課長","answer":"今回、実際に出たのは、実際にどのくらいの年齢の方を配置する予定ですかと。そういった意味では、契約して以降、きちっとその辺の管理も含めてしていきたいというふうに考えております。","id":"exchange-005"},{"speaker":"阿部委員","kind":"質問","question":"それから、このポイントというのは、工事あるいは契約ごとに何をどのくらいのポイントにするかということは変わっていくんですか。それとも一律のものがあって、それに当てはめていくのか尋ねました。","respondent":"中島経理課長","answer":"初めに、平成１８年度の契約方法ごとの件数ですけれども、先ほど、工事関係のご説明をいたしました。それで、この総合評価方式につきまして、今度４月に実施しまして、現在、検証しています。","id":"exchange-006"},{"speaker":"阿部委員","kind":"質問","question":"後で結構ですので教えていただければ。できればお願いします。","respondent":"中島経理課長","answer":"では、資料につきましては、委員会が終わってから委員長とご相談させていただきたいと思います。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっと１つだけ、４種類の契約の種類について伺いたいと思ったのは、一番多いのは工事案件ということなんでしょうか。（２）、（３）の具体的な事例といいますか、あわせて説明いただきたいなと思います。","respondent":"中島経理課長、田中総務部長","answer":"この先ほどのあれで、合計で約４,０００件弱あるんですけれども、そのうち約３,４００件が物品購入と委託契約です。そういったものが全部入っておりますので、件数的には圧倒的に物品、委託が多くなってくるです。 どんなものがあるかというところを概要説明させていただきたいと思いますので、もしそういう意味での数字的な資料等、また委員長とご相談して論議をいただければと考えています。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"逆に考えて、そういうのはどういうルールがあるのかなということをちょっとご説明していただきたいと思ったんですね。ちょっと教えていただきたかったのは、４つ目はないかもしれませんけれども、そういうルールがあるのかご説明いただけますか尋ねました。","respondent":"中島経理課長","answer":"逆に言いますと、原則的な考え方で行きますと、それ以外はできないということになります。まずは登録をしていただくということが大前提ですので、登録をされていない業者につきましては契約はできないです。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"今年の４月からなんでしょうか、これを導入するに当たっての背景などがございましたら、もう少しご説明いただけたらなと思います。その辺の問題意識、背景がございましたら、導入した理由をあわせてご説明いただきたい。","respondent":"中島経理課長","answer":"平成１８年度に検討してきた結果、試行ですけれども、何とか委託であれば可能であろうということでやってあります。調理代行は給食につきましては平成１２年に始めておりますけれども、当初、プロポーザル方式で実施しています。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどから契約できない団体について質問したのでそれについて教えてほしいと求めました。","respondent":"田中総務部長","answer":"一番基本的なところは、いわゆる法律行為ができない民法上の欠格要件というのが基礎になるかというふうに思ってあります。いろいろな定め方がありますので、それはまたいろいろ、るる細かいところのご審議のときに整理をさせていただければというふうに思ってあります。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"それを伺ったのは、談合事件は今回だけではなくて、過去にも和歌山県や名古屋市でも繰り返し繰り返しそういう事件を起こしているわけですね。社会的なペナルティーといいますか、そういうところがどうなっているかということで、さらにもう少し教えていただけますか。","respondent":"中島経理課長","answer":"そういった意味では、その期間に入っている場合につきましては、もちろん契約できない。その辺のまた細かい、具体的にこういう場合はこうですよというのは、今後の中でご説明させていただきたいと考えています。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今後教えていただきたいなと思いますけれども、選定方法がどうなっているのかというところを１つ教えていただきたいのと、その辺で大きな企業と中小のところの割合がどう推移しているのかというのがお手元にあったら教えてほしいと求めました。","respondent":"中島経理課長","answer":"通常、４億円を超えても品川区の業者で対応できるということであれば、親の会社も子の会社も全部区内業者です。基本的に厳密に決まっているわけではないですけれども、大体６対４、あるいは７対３ぐらいの割合で実施していることが多くあります。","id":"exchange-013"},{"speaker":"原委員","kind":"質問","question":"ということは、双務契約という解釈で、片務契約自体はその程度のものだと解釈してよろしいのでしょうか。きょうは概要なのであんまり深く入りませんけれども、基本的には双務契約をしていくよということでよろしいか尋ねました。","respondent":"中島経理課長","answer":"そのとおりです。","id":"exchange-014"},{"speaker":"原委員","kind":"質問","question":"一方的なのが若干あるよということですね。平成３年６月、あとそれから一番最後のところの＊４のところで、簡易型でないものもあるのか尋ねました。","respondent":"中島経理課長","answer":"それに対して、よく手続き等を若干簡略したものを簡易型あるいは簡易なプロポーザル方式と呼んでいるです。総合評価方式も基本的にはそういう概念です。","id":"exchange-015"},{"speaker":"原委員","kind":"質問・要望","question":"では、それに関連して、これは要望という形で、若干時間がかかろうかと思いますので。１０点から３０点という形で数字を入れているのだというふうに私は推測いたしますが、その辺のところを出せる範囲で資料をお願いできればと思います。","respondent":"中島経理課長","answer":"本委員会が終わってから、委員長、副委員長とご相談をさせていただきたいというふうに思っております。","id":"exchange-016"},{"speaker":"山内委員","kind":"質問","question":"１点ちょっと教えてください。（２）番指名競争入札になりますと、結構やはり（１）番の条件を満たしている会社というか、その辺のバランスというものはどう考えていますか。","respondent":"中島経理課長","answer":"私の説明の仕方が十分でなかったのかもわかりませんけれども、この（１）の制限付き一般競争入札というのは、応募してくる形です。それが制限付き一般競争入札でございまして、（２）の指名競争入札のほうは、システム的にちょっと違ってまいります。","id":"exchange-017"},{"speaker":"山内委員","kind":"確認","question":"確認なんですが、（１）番は基本的には大手ゼネコンというか、いわゆる名の知れたゼネコンということか尋ねました。","respondent":"中島経理課長","answer":"必ずしもそういうわけではございません。例えば工事で１,０００万円以上の工事は制限付きでやりますので、大きくない会社がやるのももちろん入ってあります。","id":"exchange-018"},{"speaker":"林委員","kind":"質問","question":"議決を要するところの話なんですけれども、土地については１件５,０００m2以上という、その５,０００m2という基本的な考え方はどこにあるんか尋ねました。","respondent":"田中総務部長","answer":"この９,０００万円以上の委員会報告というのは、例の専決処分の報告ですとか、たしか９,０００万円も以前は議決をいただいていた。それを１億８,０００万円に上げる際に、この９,０００万円は、参考までにこう報告させていただこうというような経過を踏んできているです。","id":"exchange-019"},{"speaker":"林委員","kind":"意見","question":"この数字をどうとらえますか。５,０００m2で４,０００万円はあり得ますかとの意見を述べました。","respondent":"中島経理課長","answer":"これは４,０００万円というのは、いわゆる建物を想定している金額ということで考えてございまして、広さでもってやっている。土地につきましては、面積で規定して、建物についてはこの４,０００万円で規定していいのではなかろうかというふうに考えてあります。","id":"exchange-020"},{"speaker":"林委員","kind":"質問・要望","question":"さっきも５,０００m2という、どういう数字を私たちが求めていくかというのは、もう少し答えを用意しておいてください。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-02","title":"第２点目の財政（歳入）に関すること","agenda":"第２点目の財政（歳入）に関すること","exchanges":[{"speaker":"武内委員","kind":"質問","question":"この資料の一番上に、歳入の歳が年齢の「才」になっているんですけれども、これは何か意味があるんですか。単純な間違いなのか、これでいいのか、それだけ説明を求めました。","respondent":"日下部企画財政課長","answer":"大変失礼いたしました。今後は気をつけたいと思います。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"教えていただきたいと思っているんですけれども、そういうところの何か考えていることが少し整理して教えていただきたいと思ったのが１つです。もう１つは、品川区としてはどういう姿勢を今持っているのか、それを教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"１点目の目指している姿ですけれども、具体的に、具体的にそういうものというのはどれを見ても実はないんですね。それからもう１つは、やはり区自身の１つの権能によりまして歳入として見込むことができる、唯一この区税だけなんですね。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺の税収がどう変化をしていくのかというところを１点教えていただきたいのと、株式等譲渡所得割交付金、減税のまま推移していると思うんですね。この辺ももとに戻ると区のところでどのように影響するのか、１点、そこのところを説明を求めました。","respondent":"日下部企画財政課長","answer":"例えば減税がなくなったらどうなるのかとか、その辺の数字につきましては持ち合わせておりませんので、ご容赦いただきたいと思います。都が２％とか、３％という、これについてもご容赦をいただきたいと思います。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"消費税についてちょっと教えていただきたいんですが、どういうふうな割合で入ってくるのかという、大もとのところを教えていただけたらと思います。","respondent":"日下部企画財政課長","answer":"消費税のほうから申し上げますと、先ほどもちょっとご説明させていただきました。いずれにしましても、ちょっとその辺は税の関係、詳細な点についてはわかりかねるということでご理解をいただきたいと思います。","id":"exchange-025"}]},{"id":"topic-03","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれ具体的にどういうところがあるのか、必要なところの資料を用意していただきたいと思ったのが１点と、それについても資料の中に取り入れていただけたらなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"林委員","kind":"提案","question":"提案したり、区側からの考え方も出してきていただきたい、そういうふうに思います。歳入ということを行革という考え方からどういうふうに区がとらえ、それが基本的にどういう議論をするか、副委員長にもお願いしたいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"中塚委員","kind":"意見","question":"そういう視点の行革もあると思うんですね。そもそもこの行革というのは、そもそもの議論をお互い深めていくのも大事な点かなと思いますので、意見だけ述べさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/471723?Template=document&Id=5818#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":34325,"voices":92}},{"id":"h19-20070606-16","meetingId":"h19-cm06","date":"2007年6月6日","dateIso":"2007-06-06","committee":"街づくり特別委員会","time":"午後１時０３分～午後２時４３分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本間副委員長","kind":"意見","question":"副委員長の本間隆です。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"意見","question":"自民党の石田です。どうぞよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"稲川委員","kind":"意見","question":"民主党の稲川貴之です。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"}]},{"id":"topic-02","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"品川全体ではどうなのかと思いまして、品川全体では５０代後半の人口年齢が一番多いのかどうかということをちょっとご説明いただきたい。どういう形で具体的な連携、協力というのは行われるのかなということを伺えればと思ったのと、どこまであるのかなということを伺いたいと思います。","respondent":"日下部企画財政課長","answer":"それからまちづくり検討会と区側との連携協力ということでありますけれども、自治会のほうとしては、こういう検討会をつくっていきたいと。やはり地域のまちづくりを進める、そういったことでお互いに連携・協力をして、早く具体化するように取り組んでいきたいです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"すみません、検討会のことなんですが、このメンバーの中には、区側の方はメンバーとして入られるものか、ちょっとお伺いしたいんですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"南委員","kind":"提案","question":"そういう八潮のまちをどういうふうに、かつてのにぎわいを戻すためにどうするかという検討は、いろいろ区としての考え方が提案されていますよね。私は住民をもっと主体的に自分たちが住むまちなんだから、どちらかなというのを伺いたいんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"だって、具体的に説明しているからいいんじゃないか尋ねました。","respondent":"山路委員長、日下部企画財政課長","answer":"概要の説明だけをやってもらったんですが。概要説明の答弁ということで。 やはりまちづくりを進めるときは、これはやっぱり意見はまとまらないわけですから、区としての基本的な考え方をお示しする。これを相対立して、どっちがどうなんだということでは考えていないということでご理解をいただきたいです。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"でも、仕切りは委員長ですから。やっぱり一番最初のところですから、確認しておきたいと思ったんですけど、ちょっとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１つだけわからないことを教えていただきたいんですが、２枚目の「ものづくり」というところなんですが、大気の浄化というところがあるでしょう。そこだけはちょっと聞きたいなと。","respondent":"松代管理工事課長","answer":"そういったものを区民の皆さんと一緒に考えて、その環境問題をきちんととらえて対応していくといったことも必要じゃないか。詳しくはまた次回以降、きちんとご説明をしていきたいと思います。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"この部分、４キロ四方を全部緑化にしたって、たかが知れている効果なわけじゃないですか。思ったことだけ言っているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-03","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もちろん地域の方々のお考え、要望、また以前のような活気が取り戻せるのか。地区の要望として、要望の中で対応していくのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"本多委員","kind":"質問・要望","question":"地区計画への移行ですか、あとは警察や消防や医療とか、本当に集中的に八潮のことをまず重点的にやってほしいと求めました。それ以外の説明いただいたことももちろん重要だと考えておりますけれども、思いはそんなところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問・要望","question":"逆に今度、商業施設の活性化を求める。その辺もちょっと大きな論点の１つだと思うんですが、その辺、区のお考えをお聞かせいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"南委員","kind":"提案","question":"住民自治ですから、まちの皆さんに２４年間住んでもらって、ならなかった。どうこうしようという、ここに区のほうの提案でありますけれども、なかなか難しいんですよねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"意見","question":"住んでいるからどうという話じゃないじゃない。議会の話だものとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"大沢委員","kind":"質問・要望","question":"確かに八潮地区ですから、なぜこれは道路公園課の水とみどりが出てきて、目黒川という説明がされたのか。上から予定表を、上のお三方の説明と下の藤田道路公園課長、家壽田下水道河川課長の説明がどのようにリンクしているのか、教えていただきたい。","respondent":"山路委員長","answer":"ご意見、ご要望をお伺いする時間ですので、いただいて、正副で調整をします。","id":"exchange-016"},{"speaker":"大沢委員","kind":"質問・要望","question":"目黒川の壁面緑化だというお話も伺いましたし、下段の２人の課長にお話しいただいて、論点がぼけない骨の組み立て方をお願いしたいと思っています。最初にやはりインパクトが八潮地区のまちづくりということで伺って、あれ、そこのところをよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"要望ですが、やはり品川区にとって、この八潮地区というのはどうなのかという視点でやっていかなければいけないのかなと思っているんですね。ですから、その地域の方たちの要望というものも必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"委員会運営で進めていく上で、ちょっと確認したいことだけ。いろいろ意見を伺うなんていう話になると、地域の方々のご要望、それからどういう八潮であろうということを検討されていく話ですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"例えば我々はこの特別委員会をやっているわけですから、非常にその点は地区計画に変えていくというのは、必要なことだろうと思っています。これは特別委員会があるわけですから、そういうことを特別委員会でやれると思うので、ぜひそれを考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/823348?Template=document&Id=6344#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":31275,"voices":94}},{"id":"h19-20070625-6","meetingId":"h19-cm06","date":"2007年6月25日","dateIso":"2007-06-25","committee":"区民委員会","time":"午前１０時０４分～午後０時１４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"第５０号議案 品川区特別区税条例の一部を改正する条例","agenda":"第５０号議案 品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"これは区で実施するわけですから、その際に区の考え方というのをお伺いしたい。大体区としては幾らぐらいと見積もっているのかなということをまずお伺いしたいと思います。","respondent":"武内税務課長","answer":"本来は３％ですけれども、本来の３％を１.８％で計算をしますと、約２億５,０００万円ほどの減税ということになるのかなと考えております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"このところは平均すると、この税率が今回の軽減措置で２０％から１０％になるということですから、１人当たりが１,５５５万円の減税。そういう減税措置だと思うんですけれども、区としては今回の減税の１年間の延長によって、どのような方が恩恵を受けると考えておられるんか尋ねました。","respondent":"武内税務課長","answer":"言われるとおり１,０００万円のそういう譲渡益があるという方につきましては、利益が出てくるわけで、個人差が非常にあるのかなと。人によっても５万円、１０万円だとかという、私どもがそれをコメントするような立場ではないのかなと考えております。","id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"この添付されています資料の付則１４条の４のところです。この辺の違いといいますか、わかればいいなと思ってお聞きいたします。","respondent":"武内税務課長","answer":"ファンド、投資事業組合というものを通じて、それぞれの国が株をやる組織体をつくるわけですね。そういった意味で、今回は投資事業組合ということを中心の言葉として改正しておりますので、個人という言葉を取り除いたというふうに聞いております。","id":"exchange-003"},{"speaker":"飯沼副委員長","kind":"質問","question":"一般質問の中でも答弁があって、区として不公平に感じていないのかどうか、その辺をちょっとお伺いします。","respondent":"武内税務課長、田中区民生活事業部長","answer":"そういった部分では、また逆に言えば、マイナスの方も非常にいるのかなと感じております。国全体の方針として、ちょっと私にはお答えできないところがありますので、ひとつよろしくお願いいたします。 国の税制改正に基づいた対応ですので、そこはまずご理解いただきたいと思います。コメントするというのは適当ではないのではないかというところで、本会議で答弁しましたので、ご理解いただきたいと思います。","id":"exchange-004"},{"speaker":"飯沼副委員長","kind":"質問","question":"たびたび国の税制のところだとおっしゃいますけれども、最も身近な自治体で、税制改正があると、電話があって問い合わせや苦情がある。今の状況は本当に改善されないというところなんですけれども、そこは揺るがないのでしょうか、もう一度そこだけお伺いいたします。","respondent":"田中区民生活事業部長","answer":"窓口等では的確にご説明するようにやりますが、私どもとして、個々にやるつもりは当然ありません。区として、自治体としては全国の自治体は同じだと思いますが、要求していくという立場には変わりありません。","id":"exchange-005"},{"speaker":"山路委員","kind":"質問","question":"今回の改正によりまして、品川区としてはどれくらい税収を見込まれているか。その辺をお伺いします。","respondent":"武内税務課長","answer":"当然、売り上げが上がれば、税も上がるんですけれども、特にこの改正によって税の増減額ということにはかかわりはありません。全体の中で、本則の本来の税率からすると、２億５,０００万円ぐらいのマイナスになるのではないかというふうに考えてあります。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"同時にこういった同じ時期に１年間、そういうことを実施していくのが品川区の皆さんですから、やっぱり品川区だと思うんです。だから、そういう意味では、そういう怒りにどう説明するのかというか、答えるのかということは、どういうふうに考えているのか、教えていただきたい。","respondent":"武内税務課長","answer":"それはそれなりの一定の考え方というのは、地方税法の改正に基づくもので品川区としては、取り扱いをしていくというふうに考えております。","id":"exchange-007"},{"speaker":"稲川委員","kind":"質問","question":"素朴な質問なんですけれども、税に対する庶民の皆様の怒りや憤りというのは、税務課にはどれくらい寄せられているんですか。単純な質問ですが。","respondent":"武内税務課長","answer":"この数字をご説明いたしますと、電話では１週間で４,８５０件という件数です。この辺の趣旨を住民に説明して、ご理解いただくということで、区民の方には対応をしています。","id":"exchange-008"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"６と７のところで、単純な質問で申しわけないんですが、６のところの対象となるところがどういうところなのかと、あと、この内容というか、中身を教えていただきたいのと、７に対してもどういった方のためのものなのかということと、控除の内容をちょっとわかりやすく教えていただけたらと思います。","respondent":"武内税務課長","answer":"これも今年の１月に日本とフランスが租税条約というのを結ぶ中で、日本人がフランスで仕事をしている。所得の申請をされるときに、フランスの自国で社会保険料を支払っているとことが確認できれば、その社会保険料の分を控除するというシステムです。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"意見","question":"株価が下がると、それこそ日本全体の景気が下がっていくほうに向かっていくわけで、そこら辺の関係からもやむを得ないことかと思っています。この議案に対して賛成しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"安藤委員","kind":"意見","question":"私たちの会派としては、多岐にわたってあると思います。１.７兆円規模の庶民増税分の減税措置があって、そのうちの１つの重要な構成要素となっているのが、そういうことで反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"渡部委員","kind":"意見","question":"ただ、鈴木委員からもありましたが、やはり日本の中、株式というのが動くことによって、企業がどんどん景気がよくなるというのは周知の事実です。その株を取得をしやすくする、企業が株を還流しやすくするという部分でも、これに関しては私は賛成しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"}]},{"id":"topic-02","title":"の２番目に移ります。請願・陳情審査","agenda":"の２番目に移ります。請願・陳情審査","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"同じ様式のパターンで９件の請願が出ているということ、同じ会派の方にお聞きするような形になると思うんですが、１件にまとめられる。なぜ、９件になさらなければいけなかったか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もちろん、それはわかりますけど、なぜかなということが、中で話が出ているかどうかということをお聞きしたかったんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほど稲川委員の質問で、３週間たったんですけれども、先ほどの数でよかったのかなということ。今回の増税が区民の暮らしというのを圧迫しているとお考えなのかどうか、お考えじゃないのかなということをお伺いしたいと思います。","respondent":"武内税務課長","answer":"従来、単純に言えば倍になっているというふうに考えていただいてもいいのかなと思うんですけれども、それイコールではありません。来年３月１５日、そういう方たちについては、住民税はこんなに増えてしまったという気持ちはぬぐい切れないのかなと考えております。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"怒りというのをどうとらえているのかというのを、大変さ、困窮さというのをどうつかんでいるのかということをお伺いしたいのが１つ。講じていただいた軽減策以外に、川崎市ほかのようにもっと踏み込んだ、そういう実施する用意というのがあるんでしょうかということで３点です。","respondent":"武内税務課長","answer":"私自身も課長を出せだとか、区長を出せとか、そういう対応をこの間、やらさせていただきました。減免制度の創設というのは、公平の原則からいって、国の法律の中で対応をするべきものなのかなというふうに考えております。","id":"exchange-016"},{"speaker":"渡辺委員","kind":"質問","question":"この税に関することで７００件という数字でありましたが、当然、お問い合わせがあるケースもあると思うんですね。課長からの感触も踏まえて、対応した結果どうだったというのをちょっと参考のため、お聞きしたいと思います。","respondent":"武内税務課長","answer":"それが納期ごとに２万円だとか、２万円とか３万円払えるわけないだろうという、懇切丁寧に相談してほしいという状況を聞かせていただきました。","id":"exchange-017"},{"speaker":"渡辺委員","kind":"確認","question":"問い合わせというのは悪い問い合わせというんですか、それに対して答えた数字が、私は７００なり何なりだと理解してよろしいかと思うんですね。普通に全体を見れば、納得している方は大勢いらっしゃるかと思ったので、その確認でした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"渡部委員","kind":"質問","question":"今、渡辺委員からの質問にあった、いろいろ問い合わせがあったというのは、問い合わせをいただいている方って、やはり個人事業主の方が多いんですか。特にそういう方が多いというわけではないんか尋ねました。","respondent":"武内税務課長","answer":"今回は、６月４日に普通徴収という形で、個人事業主の方に発布してからの統計です。その問い合わせは６月の普通徴収、ほとんど９割方がそういう自営業というか、普通徴収の方と考えています。","id":"exchange-019"},{"speaker":"渡部委員","kind":"質問","question":"逆にその話があるんだとすれば、その翌年は、今度は減免がなくなるわけですから、もとに戻るんですね。次、どこかで文句が出てくるんじゃないかなと思う部分があるんですが、いかがか尋ねました。","respondent":"武内税務課長","answer":"委員がおっしゃるとおり、そういう個人事業主の方につきましては、青色申告会あるいは納税貯蓄組合等に参加している方も大勢いらっしゃいますので、そういう組織を通じて十二分にこういう救済措置についてご理解いただけるような準備をしていきたいと考えています。","id":"exchange-020"},{"speaker":"渡部委員","kind":"意見","question":"なおかつ７月２日の納入期限が来て、きついなという意見も確かにあったのも事実ですし、皆さんがきついとは思っているんでしょうとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"山路委員","kind":"質問","question":"十分にいろいろなお話はお伺いするんですけど、定率減税８年間の間というのは、大きな社会状況全体像もあると思うんです。その辺の状況について、ちょっとご説明をしていただけますか尋ねました。","respondent":"武内税務課長","answer":"定率減税の廃止というのは、先ほど来お話ししているように、経済状況が回復してきた。今回３,３００億円というものが国庫の年金のほうに与えられるということでありますので、利益を還元されるのではないかと考えております。","id":"exchange-022"},{"speaker":"山路委員","kind":"質問","question":"低所得者の方が一部増税になったという、ちょっと質問が悪いですけど、増税じゃないのに、増税分と書いてありますから、もとに戻す。この辺のとらえ方を説明してくださいますか。","respondent":"武内税務課長","answer":"平成１８年度に縮減したときに、１７万５,０００人の方が所得割というものがかかっていますので、減です。それと減税を基本的には戻すということでありますので、増税ではないということを改めて理解していただきたいと考えています。","id":"exchange-023"},{"speaker":"山路委員","kind":"質問","question":"ここをどう判断していいかという部分で迷うんですけど、税金とかいろいろなものにあるかもわかりませんけど、現実違うんですね。この請願項目に沿って、ちょっとお伺いしているんですけど。","respondent":"武内税務課長","answer":"現状においては、減税をするということは不可能と考えています。","id":"exchange-024"},{"speaker":"山路委員","kind":"質問","question":"請願項目の文章を理解するためにお伺いしているわけなんですね。国保も上がるかということになるんですけど、その辺の今回の税制改正とのことについて、ご説明をちょっとしていただけますか尋ねました。","respondent":"原国保年金課長","answer":"先ほどご説明させていただきましたように、平成１８年度については、国のほうで軽減措置を講じたところです。２３区でこれらに伴う影響をいろいろ考えながら、先ほど説明したような形で、保険料算定ということで軽減措置を２３区独自で実施しているものです。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"その要素をちょっと考えられる限り教えていただきたいのと、その生活実態を問い合わせの中で、絶対区民の方から訴えられているはずなんですね。その声を伺った結果、考えている区民の生活実態というのをちょっとお伺いしたいと思います。","respondent":"武内税務課長","answer":"そのほか、高齢者の方の介護施設に入居している方やなんかも、はっきりわかりませんが、影響するのかなと考えます。そういった意味では、私もそういう住民との接触の中で、確かに所得の少ない方については厳しいのかなということは実感しております。","id":"exchange-026"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"皆さん、これ、ごらんになったでしょうか。その辺のご説明もちゃんとしていただきたいなと思うのと、ぜひトータルで見てほしいというところでは、いかがか尋ねました。","respondent":"武内税務課長","answer":"平成１８年度の税制改正の中で、あえて、ここでご説明をしておりません。簡単にご説明しますと、昭和２６年に創設されたわけですけれども、２年前に見直しが行われて改正されたです。","id":"exchange-027"},{"speaker":"飯沼副委員長","kind":"提案","question":"条例提案をしたそうなんですが、ぜひ２３区で全体の部分を把握しながら、軽減策を考えていく。払えない人への減免制度を拡大していくという姿勢を持っていただきたいのですが、いかがか尋ねました。","respondent":"田中区民生活事業部長","answer":"例えばヨーロッパ並みの消費税２０％とか、大きな安心を買うという考え方もあろうと思いますし、民間の保険会社に掛ける。持続可能な形で２３区も、国も考えてやってきておりますので、ぜひその辺のところをご理解いただきたいと思います。","id":"exchange-028"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"滞納のところで伺いたいのですが、払えない人たちが多分多いのではないかと思うあたりで、私は今ある減免措置ではとても不十分。払えない人のための救済策が大事であると思うんですが、その点もお伺いします。","respondent":"原国保年金課長","answer":"世界一ということで、これは今の日本の社会の医療制度が充実していることによって、そういったものがもたらされているというふうに認識しております。ただ、そうは言いましても、いろいろなご事情で支払いができないという方も事実いらっしゃることがあります。","id":"exchange-029"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"こういうのは１つの区でできることではないと思いますが、どう大変なところを救えるのかという立場にぜひ立ってほしいと求めました。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"山路委員","kind":"意見","question":"そういうところから考えますと、この請願の内容に関しましては賛成できない。ですので、決をとっていただいて結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"この当委員会１回だけではちょっと議論し尽くせないというか、やはりどうなるかわかりませんけれども、採択をしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"違います。内容的にはすごく緊急性を求められることですので、本日、採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"意見","question":"トータルの所得税と住民税が何かごちゃごちゃになっている部分が非常に多いなという感じがします。医療費をもとにしての国保制度上の中で、２３区同率でやっている、その辺も区としては行っているということでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"稲川委員","kind":"質問","question":"庶民、それはまた話がずれちゃいますけど、例えばどこかの量販店で買い物をしている人たちが庶民なのかどうなのかという話だってあるじゃないですか。ネットカフェ難民という話はありましたけれども、その話だって、ぜいたくじゃないですか、お金を払ってそこにいられるんだから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問","question":"区民の生活実態から出発するべきだと思うんですけれども、住民の福祉の増進を目的とするということの名がすたるなと、私はすごく思っています。ですから、私はぜひ本請願には、地方自治体の本旨に照らして、すぐにでもこたえるべきだと思いますので、この請願は採択するべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"渡部委員","kind":"質問","question":"ただ、それに関してはやはり所得税のカウント等について、私たちが広報マンになって、これは聞かれた方に答えていかなければならない。これは実際、国で決まったことであって、動いているわけですから、何とかこれは自分自身も地域の広報マンになって頑張っていきたいと思います。","respondent":"川西委員長","answer":"大変遅くなって申しわけありませんが、ならびに第１８号および１９号の９件につきまして、採択とすることに賛成の方の挙手をお願いいたします。","id":"exchange-037"},{"speaker":"川西委員長","kind":"質問・要望","question":"行政視察のことにつきまして、ご意見をお出しほしいと求めましたので、よろしくお願いいたします。他に何かありますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"安藤委員","kind":"意見","question":"前回の区民委員会で、国民保護計画の報告がありましたけれども、それについて、ぜひ明日、その他あたりでやれないかなと。いつやるのか、それを委員長、副委員長のお考えもあるのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/598842?Template=document&Id=2488#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":35462,"voices":99}}]);
